window.SSAI_TERMS=[{"subject":"論理国語","topics":[{"topic":"文章の構成と接続語","cards":[{"term":"序論・本論・結論","reading":"じょろん・ほんろん・けつろん","meaning":"文章全体を問題提起、展開、まとめの三つに分ける基本的な組み立て。","note":"このテーマの土台。評論を読むときはまず三部構成を意識する。","example":""},{"term":"順接","reading":"じゅんせつ","meaning":"前の内容を受けて、自然な結果や続きが後ろに来る関係。「だから」などが示す。","note":"因果や流れをつかむ手がかりになる接続関係。","example":""},{"term":"逆接","reading":"ぎゃくせつ","meaning":"前の内容から予想される流れに反する内容が続く関係。「しかし」などが示す。","note":"筆者の主張が現れやすい転換点として重要。","example":""},{"term":"添加・並列","reading":"てんか・へいれつ","meaning":"似た内容を付け加えたり並べたりする関係。「また」「さらに」などが示す。","note":"情報を増やして説明を厚くする働きをする。","example":""},{"term":"対比の接続語","reading":"たいひのせつぞくご","meaning":"二つの事柄を比べる関係を示す言葉。「一方」「これに対して」など。","note":"違いを際立たせることで主張を明確にする。","example":""},{"term":"換言の接続語","reading":"かんげんのせつぞくご","meaning":"前の内容を別の言葉で言い直すことを示す言葉。「つまり」「すなわち」など。","note":"要旨や結論がまとめられる場所の目印になる。","example":""}]},{"topic":"段落の役割と要旨","cards":[{"term":"段落","reading":"だんらく","meaning":"一つのまとまった内容ごとに改行して区切った文章の単位。","note":"段落ごとに役割を考えるのが読み取りの第一歩。","example":""},{"term":"中心文","reading":"ちゅうしんぶん","meaning":"段落の要点を最も直接に表した一文。話題文とも呼ばれる。","note":"段落の要旨をつかむときの核になる文。","example":""},{"term":"要旨","reading":"ようし","meaning":"文章全体や段落で筆者が最も伝えたい内容を短くまとめたもの。","note":"中心文と具体例を区別して見つける。","example":""},{"term":"具体例の段落","reading":"ぐたいたいのだんらく","meaning":"抽象的な主張を分かりやすくするために実例を示す段落。","note":"主張そのものではないので要旨と混同しない。","example":""},{"term":"話題の転換","reading":"わだいのてんかん","meaning":"段落が変わり、扱う内容や視点が切り替わること。","note":"逆接の接続語や新しい語句が合図になることが多い。","example":""},{"term":"段落構成図","reading":"だんらくこうせいず","meaning":"各段落の役割とつながりを図に整理したもの。","note":"文章全体の論の流れを一目で確認できる。","example":""}]},{"topic":"論理の展開と根拠","cards":[{"term":"主張","reading":"しゅちょう","meaning":"筆者が読み手に納得してほしい中心的な考え。","note":"根拠と結び付けて読む対象。","example":""},{"term":"根拠","reading":"こんきょ","meaning":"主張を支える理由や証拠となる事柄。","note":"根拠が十分かどうかで論の説得力が決まる。","example":""},{"term":"帰納法","reading":"きのうほう","meaning":"個別の事例をいくつか集め、そこから共通する結論を導く考え方。","note":"具体例から一般的な主張へ進む展開で使われる。","example":""},{"term":"演繹法","reading":"えんえきほう","meaning":"一般的な原理や前提から出発し、個別の結論を導く考え方。","note":"前提が正しいかどうかが結論の信頼性を左右する。","example":""},{"term":"論理の飛躍","reading":"ろんりのひやく","meaning":"根拠から結論までの間に必要な説明が抜け、つながりが不十分なこと。","note":"批判的に読むときに見つけるべき弱点。","example":""},{"term":"事実と意見","reading":"じじつといけん","meaning":"実際に起きた事柄と、それに対する考えや評価を区別すること。","note":"根拠として使えるのはまず事実であり、意見は主張側に置く。","example":""}]},{"topic":"対比と例示","cards":[{"term":"対比","reading":"たいひ","meaning":"二つの事柄を並べて比べ、共通点や相違点を明らかにすること。","note":"筆者の考えを浮かび上がらせる代表的な方法。","example":""},{"term":"二項対立","reading":"にこうたいりつ","meaning":"物事を二つの対立する項に分けて捉える枠組み。","note":"分かりやすい反面、単純化しすぎる危険もある。","example":""},{"term":"例示","reading":"れいじ","meaning":"抽象的な説明の後に具体的な事例を示して理解を助けること。","note":"「たとえば」で始まる部分が目印になる。","example":""},{"term":"類比","reading":"るいひ","meaning":"似た構造を持つ別の事柄になぞらえて説明する方法。アナロジーともいう。","note":"比喩的な説明と論証の区別に注意する。","example":""},{"term":"具体と抽象の往復","reading":"ぐたいとちゅうしょうのおうふく","meaning":"具体例と一般的な考えを行き来しながら理解を深める読み方。","note":"例示と対比を読み解くときの基本動作。","example":""}]},{"topic":"抽象と具体","cards":[{"term":"抽象","reading":"ちゅうしょう","meaning":"個別の事柄から共通する性質を取り出し、一般的に捉えること。","note":"具体例を束ねて大きな考えを作る働き。","example":""},{"term":"具体","reading":"ぐたい","meaning":"形や様子がはっきり分かる、個別で実際の事柄のこと。","note":"抽象的な主張を確かめる材料になる。","example":""},{"term":"上位概念と下位概念","reading":"じょういがいねんとかいがいねん","meaning":"広く含む概念と、その中に含まれる狭い概念の関係。","note":"例として「乗り物」が上位、「自転車」が下位にあたる。","example":""},{"term":"一般化","reading":"いっぱんか","meaning":"限られた事例から、広く当てはまる言い方へ広げること。","note":"広げすぎると根拠不足になる点に注意する。","example":""},{"term":"定義","reading":"ていぎ","meaning":"言葉の意味する範囲を明確に定める説明。","note":"論を始める前に用語をそろえる役割を持つ。","example":""},{"term":"抽象化の落とし穴","reading":"ちゅうしょうかのはとしあな","meaning":"抽象的にまとめる過程で大事な違いが消えてしまう問題。","note":"具体に戻って確かめることで防げる。","example":""}]},{"topic":"働くということ","cards":[{"term":"労働と仕事の違い","reading":"ろうどうとしごとのちがい","meaning":"労働は賃金を得る活動の面、仕事は社会的な役割ややりがいを含む面に注目した捉え方。","note":"本文では二つの言葉の使い分けが主張の鍵になる。","example":""},{"term":"言葉と仕事","reading":"ことばとしごと","meaning":"言葉の意味の捉え方が、その活動への価値づけに影響するという考え。","note":"テーマ全体を貫く視点。","example":""},{"term":"楽しく働く／楽に働く","reading":"たのしくはたらく／らくにはたらく","meaning":"充実感を得ながら働くことと、負担の少なさを求めて働くことの対比。","note":"筆者が区別する二つの働き方。","example":""},{"term":"社会との関わり","reading":"しゃかいとのかかわり","meaning":"働くことが他者や社会の役に立つことと結び付いているという面。","note":"仕事の意味を個人の外へ広げる論点。","example":""},{"term":"問いを立てる","reading":"といをたてる","meaning":"答えを探す前に、自分が何を疑問に思うかを言葉にすること。","note":"評論を読むときにも使える主体的な姿勢。","example":""}]},{"topic":"論理の力―論理とは何か","cards":[{"term":"つながる力","reading":"つながるちから","meaning":"言葉と言葉、考えと考えを筋道立てて結び付ける論理の働き。","note":"論理の四つの力の一つとして示される。","example":""},{"term":"結論する力","reading":"けつろんするちから","meaning":"根拠を踏まえて自分の判断をまとめる論理の働き。","note":"曖昧なまま終わらせないための力。","example":""},{"term":"整理する力","reading":"せいりするちから","meaning":"情報を分けたり順序付けたりして分かりやすくする働き。","note":"複雑な内容を扱うときの土台になる。","example":""},{"term":"質問する力","reading":"しつもんするちから","meaning":"前提を疑い、不足している点を問うことで考えを深める働き。","note":"論理は答えるだけでなく問う力でもある。","example":""},{"term":"演繹","reading":"えんえき","meaning":"一般的な前提から個別の結論を必然的に導く推論。","note":"このテーマでは論理の代表例として帰納と並べて扱う。","example":""},{"term":"帰納","reading":"きのう","meaning":"複数の事例から共通する傾向を見つけ、一般的な結論を導く推論。","note":"演繹と対比して理解する。","example":""}]},{"topic":"科学と人間","cards":[{"term":"人工知能（AI）","reading":"じんこうちのう","meaning":"人間の知的活動の一部を機械に担わせようとする技術の総称。","note":"人間とは何かを考える鏡として本文に登場する。","example":""},{"term":"鏡としての人工知能","reading":"かがみとしてのじんこうちのう","meaning":"AIを通して逆に人間らしさが浮かび上がるという比喩的な捉え方。","note":"テーマ名にも関わる中心的な比喩。","example":""},{"term":"ロボットと隣人","reading":"ろぼっととりんじん","meaning":"機械を単なる道具ではなく、共に暮らす存在として捉え直す視点。","note":"技術と人間の距離を考える論点。","example":""},{"term":"人間らしさの条件","reading":"にんげんらしさのじょうけん","meaning":"感情や身体、他者との関係など、人間を人間たらしめる要素。","note":"AIと比較することで問い直される。","example":""},{"term":"技術と倫理","reading":"ぎじゅつとりんり","meaning":"新しい技術をどう使うべきかという善悪や責任の問題。","note":"科学の進歩と切り離せないテーマ。","example":""},{"term":"比喩の読み取り","reading":"ひゆのよみとり","meaning":"たとえが何と何を結び付けているかを読み解くこと。","note":"抽象的な評論を理解する手がかりになる。","example":""}]},{"topic":"言葉と認識","cards":[{"term":"もの命名","reading":"ものめいめい","meaning":"対象に名前を与えることで、それを一つのものとして捉える働き。","note":"言葉が認識を作る出発点として扱われる。","example":""},{"term":"言葉と認識","reading":"ことばとにんしき","meaning":"言葉を持つことで世界の見え方や分け方が変わるという関係。","note":"このテーマの中心的な問い。","example":""},{"term":"パラダイム","reading":"ぱらだいむ","meaning":"ある時代や分野で共有される、物事の見方や考え方の枠組み。","note":"科学的発見の捉え方が変わる例で説明される。","example":""},{"term":"科学的発見","reading":"かがくてきはっけん","meaning":"新しい事実や法則を見つけること。見方自体が変わる場合もある。","note":"命名や分類と結び付けて論じられる。","example":""},{"term":"常識を疑う","reading":"じょうしきをうたがう","meaning":"当たり前とされる見方を一度立ち止まって確かめる姿勢。","note":"新しい認識を得るための出発点。","example":""}]},{"topic":"知のゆくえと未来","cards":[{"term":"知識の作為性","reading":"ちしきのさくいせい","meaning":"知識は自然に与えられるのではなく、人が目的に応じて作り出す面があること。","note":"知を固定的に捉えないための視点。","example":""},{"term":"知識の構造性","reading":"ちしきのこうぞうせい","meaning":"知識はばらばらではなく、互いに関連し合って体系をなしていること。","note":"個々の情報をつなげて理解する必要を示す。","example":""},{"term":"もう一つの知性","reading":"もうひとつのちせい","meaning":"数値や論理だけでは測れない、別の形の賢さや理解のあり方。","note":"未来の知の姿を考えるキーワード。","example":""},{"term":"サピエンス","reading":"さぴえんす","meaning":"現生人類を指す学名に由来する呼び方で、人類全体を表す語。","note":"人類の歴史と未来を論じる文脈で使われる。","example":""},{"term":"未来のありか","reading":"みらいのありか","meaning":"知識や知性が今後どこへ向かうのかという問い。","note":"評論全体のまとめにつながる論点。","example":""}]}]},{"subject":"文学国語","topics":[{"topic":"日本の近代文学の流れ","cards":[{"term":"言文一致","reading":"げんぶんいっち","meaning":"話し言葉と書き言葉を近づけようとした近代の文章改革の動き。","note":"近代文学成立の土台となった運動。","example":"言文一致の文体が広まったことで、小説は話し言葉に近い言葉で書かれるようになった。"},{"term":"坪内逍遥","reading":"つぼうちしょうよう","meaning":"明治期の文学者で、写実的な小説の必要を説いた人物。","note":"代表的な理論書が近代小説論の出発点とされる。","example":"坪内逍遥は、評論『小説神髄』で近代小説のあり方を示した。"},{"term":"写実主義","reading":"しゃじつしゅぎ","meaning":"現実をありのままに描こうとする文学の立場。リアリズムともいう。","note":"近代文学の流れの初期を代表する考え方。","example":"写実主義の作品は、現実の社会をありのままに描こうとする。"},{"term":"ロマン主義","reading":"ろまんしゅぎ","meaning":"個人の感情や理想、美を重んじる文学の傾向。","note":"写実主義の後に広がった対照的な流れ。","example":"ロマン主義の詩人たちは、個人の感情や夢を豊かに表現した。"},{"term":"自然主義","reading":"しぜんしゅぎ","meaning":"人間を自然や環境の産物として客観的に描こうとする傾向。","note":"明治末から大正初期に影響を持った。","example":"自然主義の小説は、人間の弱さや醜さからも目をそらさずに描いた。"},{"term":"白樺派","reading":"しらかばは","meaning":"雑誌『白樺』を中心に活動し、人道主義や理想主義を掲げた作家たちの集まり。","note":"自然主義への反動として位置づけられる。","example":"白樺派の作家たちは、人間の成長や理想を肯定的に描いた。"},{"term":"小説神髄","reading":"しょうせつしんずい","meaning":"坪内逍遥が1885年に発表した評論。旧来の勧善懲悪の小説を批判し、人間の心理や社会をありのままに描く写実を説いた。","note":"著者は夏目漱石ではなく坪内逍遥。近代小説の理論の出発点として覚える。","example":"『小説神髄』の考え方は、その後の日本の小説の書き方に大きな影響を与えた。"},{"term":"浮雲","reading":"うきぐも","meaning":"二葉亭四迷が1887年から発表した小説。言文一致体で書かれ、日本の近代小説の出発点とされる。","note":"作者は二葉亭四迷。言文一致の最初の本格的な小説として、坪内逍遥の評論とセットで覚える。","example":"『浮雲』は、言文一致で書かれた近代小説の始まりとして文学史に残っている。"}]},{"topic":"明治の作家たち","cards":[{"term":"夏目漱石","reading":"なつめそうせき","meaning":"『吾輩は猫である』『こころ』などで知られる明治・大正の代表的作家。","note":"このテーマと『こころ』のテーマの両方に関わる。","example":"夏目漱石の『こころ』は、今も多くの人に読み継がれている。"},{"term":"森鴎外","reading":"もりおうがい","meaning":"軍医でありながら『舞姫』などを書いた明治の作家。鴎外は号。","note":"『舞姫』の作者として押さえる。","example":"森鴎外は、軍医として働きながら『舞姫』などの作品を書いた。"},{"term":"樋口一葉","reading":"ひぐちいちよう","meaning":"『たけくらべ』で知られ、短い生涯で明治の女性の姿を描いた作家。","note":"明治を代表する女性作家。","example":"樋口一葉は、二十四歳の若さで亡くなるまでに名作を残した。"},{"term":"島崎藤村","reading":"しまざきとうそん","meaning":"詩人として出発し、『破戒』で自然主義小説の代表作を残した作家。","note":"詩から小説へ移った経歴が特徴。","example":"島崎藤村は、詩集『若菜集』で注目され、後に小説『破戒』を書いた。"},{"term":"二葉亭四迷","reading":"ふたばていしめい","meaning":"言文一致体の小説『浮雲』を書いた明治初期の作家。","note":"近代小説の先駆者として位置づけられる。","example":"二葉亭四迷の『浮雲』は、言文一致で書かれた小説として知られる。"},{"term":"国木田独歩","reading":"くにきだどっぽ","meaning":"自然や田園を愛し、短編小説で知られるロマン主義的な作家。","note":"自然主義への橋渡しとも評される。","example":"国木田独歩は、「武蔵野」で自然の美しさを描いた。"},{"term":"たけくらべ","reading":"たけくらべ","meaning":"樋口一葉の代表作。下町に暮らす少年少女の淡い思いや成長を描いた短編小説。","note":"作者は樋口一葉。『にごりえ』『大つごもり』と並ぶ代表作として覚える。","example":"『たけくらべ』では、祭りの日の下町の様子が生き生きと描かれている。"},{"term":"破戒","reading":"はかい","meaning":"島崎藤村が1906年に発表した長編小説。被差別部落出身の教師の苦悩を描き、日本の自然主義文学の出発点とされる。","note":"作者は島崎藤村。詩人から小説家へ転じた後の代表作である点に注意する。","example":"『破戒』は、社会の差別に苦しむ主人公の姿を描いた小説である。"}]},{"topic":"山月記","cards":[{"term":"李徴","reading":"りちょう","meaning":"『山月記』の主人公で、詩人として名を成せず虎になってしまう人物。","note":"物語の中心人物。名前の読みに注意する。","example":"李徴は、詩人として認められたい気持ちに苦しみ続けた。"},{"term":"袁傪","reading":"えんさん","meaning":"李徴の旧友で、旅の途中で虎となった李徴の声を聞く人物。","note":"李徴の告白を聞く聞き手の役割を担う。","example":"袁傪は、旅の途中で虎となった旧友の李徴と再会した。"},{"term":"臆病な自尊心と尊大な羞恥心","reading":"おくびょうなじそんしんとそんだいなしゅうちしん","meaning":"自分を守りたい気持ちと、人前で恥をかくことを恐れる気持ちを表す作中の言葉。","note":"李徴が虎になった理由を自ら語る核心部分。","example":"李徴は、自分の心の弱さを臆病な自尊心と尊大な羞恥心という言葉で表した。"},{"term":"虎になるということ","reading":"とらになるということ","meaning":"人間としての理性や姿を失うことを象徴する出来事。","note":"自尊心の問題が姿を変える比喩として読む。","example":"李徴にとって、虎になるということは人間の心を失っていく恐怖でもあった。"},{"term":"中島敦","reading":"なかじまあつし","meaning":"『山月記』の作者。中国の古典を題材にした作品で知られる。","note":"作者と作品をセットで覚える。","example":"中島敦の『山月記』は、中国の古典をもとにした短編である。"},{"term":"一人称の告白","reading":"いちにんしょうのこくはく","meaning":"登場人物が「私」の立場で自らの内面を語る形式。","note":"李徴の独白が物語の中心をなす。","example":"『山月記』の中心は、李徴の一人称の告白によって物語が進む場面である。"},{"term":"人虎伝","reading":"じんこでん","meaning":"中国の唐の時代の伝奇小説で、人が虎になる物語。『山月記』の典拠（もとになった作品）とされる。","note":"『山月記』は中島敦がこの中国の物語をもとに書き直した作品。典拠の名前として覚える。","example":"『山月記』は、中国の『人虎伝』をもとにして書かれたと言われている。"},{"term":"古譚","reading":"こたん","meaning":"中島敦の第一作品集の題名。『山月記』と『文字禍』が収められ、1942年に発表された。","note":"『山月記』が収められた本の名前。中島敦のデビュー作集として覚える。","example":"『山月記』は、中島敦の作品集『古譚』に収められて発表された。"}]},{"topic":"こころ","cards":[{"term":"先生","reading":"せんせい","meaning":"『こころ』の語り手である「私」が慕う年上の人物。","note":"作品の中心人物で、遺書の書き手でもある。","example":"『こころ』の先生は、過去の秘密を抱えたまま「私」と向き合った。"},{"term":"K","reading":"けー","meaning":"先生の友人で、先生と同じ女性を愛したことから悲劇につながる人物。","note":"イニシャルで呼ばれることが人物関係の特徴。","example":"Kは、先生と同じ下宿に住み、お嬢さんへの思いを深めていった。"},{"term":"遺書","reading":"いしょ","meaning":"先生が「私」に宛てて残した長い手紙で、過去の秘密が明かされる部分。","note":"作品後半の中心をなす形式。","example":"先生の遺書には、誰にも話せなかった過去が詳しく書かれていた。"},{"term":"エゴイズム","reading":"えごいずむ","meaning":"自分の利益や気持ちを優先する自己中心的なあり方。","note":"先生の後悔を理解するキーワード。","example":"『こころ』では、人間のエゴイズムが人を傷つける様子が描かれる。"},{"term":"明治の精神","reading":"めいじのせいしん","meaning":"明治という時代を生きた人々の生き方や価値観を象徴する言葉。","note":"先生の死の意味を考える手がかり。","example":"先生は、明治の精神とともに生き、死のうとした人物として描かれる。"},{"term":"夏目漱石","reading":"なつめそうせき","meaning":"『こころ』の作者。近代日本を代表する小説家。","note":"明治の作家たちとも重なる重要人物。","example":"夏目漱石の『こころ』は、今も多くの人に読み継がれている。"},{"term":"殉死","reading":"じゅんし","meaning":"主君の死に際して、家臣などが後を追って自ら命を絶つこと。明治天皇の崩御の際、乃木大将が殉死したことが『こころ』の先生に影響を与えた。","note":"先生が「明治の精神」に殉じるという考えと結びつく言葉として覚える。","example":"乃木大将の殉死の知らせは、『こころ』の先生の心を大きく動かした。"},{"term":"静","reading":"しず","meaning":"『こころ』に登場する先生の妻の名前。先生はKとの過去を、静を守るために最後まで話さなかった。","note":"お嬢さんと呼ばれていた人物が、結婚後に静という名前で登場する点に注意する。","example":"静は、夫である先生の過去を知らないまま日々を送っていた。"}]},{"topic":"大正・昭和の文学","cards":[{"term":"志賀直哉","reading":"しがなおや","meaning":"白樺派の中心作家で、『城の崎にて』などの心境小説で知られる。","note":"大正文学を代表する一人。","example":"志賀直哉は、『城の崎にて』などの心境小説で知られる。"},{"term":"芥川龍之介","reading":"あくたがわりゅうのすけ","meaning":"『羅生門』『鼻』など短編の名手として知られる大正期の作家。","note":"古典を題材にした作品も多い。","example":"芥川龍之介は、『羅生門』などの短編小説を多く残した。"},{"term":"プロレタリア文学","reading":"ぷろれたりあぶんがく","meaning":"労働者の生活や社会問題を描き、社会変革を目指した文学の動き。","note":"昭和初期に広がった社会派の流れ。","example":"プロレタリア文学は、労働者の生活や社会の矛盾を描いた。"},{"term":"太宰治","reading":"だざいおさむ","meaning":"『人間失格』『走れメロス』で知られる昭和の作家。","note":"戦前戦後を通じて読まれる代表的作家。","example":"太宰治の『人間失格』は、戦後の若者に広く読まれた。"},{"term":"川端康成","reading":"かわばたやすなり","meaning":"『雪国』などで日本的な美を描き、ノーベル文学賞を受けた作家。","note":"新感覚派から出発した経歴も押さえる。","example":"川端康成は、日本人で初めてノーベル文学賞を受賞した。"},{"term":"三島由紀夫","reading":"みしまゆきお","meaning":"『金閣寺』などで知られ、美と行動を追求した昭和の作家。","note":"戦後文学を代表する一人。","example":"三島由紀夫の『金閣寺』は、美への執着を描いた小説である。"},{"term":"新思潮派","reading":"しんしちょうは","meaning":"大正時代に雑誌『新思潮』を中心に活動した作家たちの一派。芥川龍之介や菊池寛らが属し、理知的な作風で知られる。","note":"白樺派と同時代の別の流れ。芥川龍之介の所属として覚える。","example":"芥川龍之介は、新思潮派の作家として短編小説で活躍した。"},{"term":"大江健三郎","reading":"おおえけんざぶろう","meaning":"昭和から平成に活躍した小説家。『万延元年のフットボール』などの作品で知られ、1994年に日本人で2人目のノーベル文学賞を受賞した。","note":"日本人初のノーベル文学賞は川端康成、2人目が大江健三郎という順序で覚える。","example":"大江健三郎は、戦後の日本文学を代表する作家の一人である。"}]},{"topic":"檸檬","cards":[{"term":"梶井基次郎","reading":"かじいもとじろう","meaning":"『檸檬』の作者。感覚的な描写に優れた短編を残した作家。","note":"作者と作品を結び付けて覚える。","example":"梶井基次郎は、短い生涯の中で感覚の鋭い短編を残した。"},{"term":"えたいの知れない不快の塊","reading":"えたいのしれないふかいのかたまり","meaning":"主人公を苦しめる原因不明の憂鬱な気分を表す作中の表現。","note":"作品冒頭のキーワード。","example":"「私」は、えたいの知れない不快の塊を抱えて街を歩いていた。"},{"term":"檸檬","reading":"れもん","meaning":"主人公が果物店で買い、重みや冷たさに心を引かれる果物。","note":"作品の題名であり象徴的な品物。","example":"「私」は、果物屋で買った一つの檸檬に心を引かれた。"},{"term":"丸善","reading":"まるぜん","meaning":"主人公が訪れる書店で、画集の上に檸檬を置く場面の舞台。","note":"結末の場面と結び付けて覚える。","example":"「私」は、檸檬を手にして久しぶりに丸善の店内へ入った。"},{"term":"感覚の描写","reading":"かんかくのびょうしゃ","meaning":"色や重さ、冷たさなど五感を通した表現の仕方。","note":"梶井の作風を特徴づける要素。","example":"『檸檬』では、色や重さなどの感覚の描写が気持ちの変化を伝えている。"},{"term":"爆弾の比喩","reading":"ばくだんのひゆ","meaning":"置いた檸檬を爆弾に見立てて想像する主人公の空想。","note":"憂鬱を吹き飛ばしたい気持ちの表れと読む。","example":"「私」は、檸檬を爆弾の比喩でとらえ、棚に置いて店を出た。"},{"term":"私小説","reading":"わたくししょうせつ","meaning":"作者自身の体験や心情をもとにして書かれる小説の形式。日本の近代文学で多く書かれた。","note":"『檸檬』も、作者自身に重なる「私」の心情が中心になる点で、この形式と関わらせて読まれる。","example":"『檸檬』は、私小説のように「私」の気持ちの動きが中心に描かれている。"},{"term":"桜の樹の下には","reading":"さくらのきのしたには","meaning":"梶井基次郎の短編小説。満開の桜の美しさと、その下に死体が埋まっているという想像を重ねて描いた作品。","note":"『檸檬』と並ぶ梶井基次郎の代表作。作者とセットで覚える。","example":"『桜の樹の下には』では、桜の美しさへの不安な気持ちが描かれている。"}]},{"topic":"舞姫","cards":[{"term":"森鷗外","reading":"もりおうがい","meaning":"『舞姫』の作者。ドイツ留学の経験を持つ軍医・作家。","note":"作中では「鴎外」と表記される場合もある。","example":"森鷗外の『舞姫』は、ドイツ留学の体験をもとに書かれた。"},{"term":"太田豊太郎","reading":"おおたとよたろう","meaning":"『舞姫』の主人公で、ドイツへ留学した官僚。手記形式で物語を語る。","note":"エリスとの関係と帰国の決断が中心になる。","example":"太田豊太郎は、エリスへの愛と出世の道の間で苦しんだ。"},{"term":"エリス","reading":"えりす","meaning":"ベルリンで豊太郎と出会う踊り子の女性。","note":"豊太郎の生き方を揺るがす人物。","example":"エリスは、ベルリンの劇場で踊る踊り子だった。"},{"term":"相沢謙吉","reading":"あいざわけんきち","meaning":"豊太郎の友人で、帰国をめぐる決断に関わる人物。","note":"主人公の選択に影響を与える存在。","example":"相沢謙吉は、豊太郎に帰国して出世の道へ進むよう迫った。"},{"term":"文語体","reading":"ぶんごたい","meaning":"昔の書き言葉の文体で書かれていること。","note":"明治初期の作品の特徴として押さえる。","example":"『舞姫』は、格調のある文語体で書かれている。"},{"term":"近代の自我","reading":"きんだいのじが","meaning":"自分の意志で生き方を選ぼうとする近代的な意識。","note":"豊太郎の迷いを通して描かれる主題。","example":"『舞姫』には、近代の自我に目覚めた青年の苦悩が描かれている。"},{"term":"ベルリン","reading":"べるりん","meaning":"ドイツの首都。『舞姫』で太田豊太郎が留学し、エリスと出会った物語の舞台の都市。","note":"作品の舞台はドイツのベルリン。森鴎外自身の留学先でもあった。","example":"豊太郎は、ベルリンの下宿でエリスと出会った。"},{"term":"雅俗折衷","reading":"がぞくせっちゅう","meaning":"格調高い漢文調の表現と、日常的な話し言葉の要素を組み合わせた文体のこと。『舞姫』は雅俗折衷の文語体で書かれている。","note":"『舞姫』の文体を説明する言葉。文語体の一種として覚える。","example":"『舞姫』は、雅俗折衷の文語体で書かれた作品である。"}]},{"topic":"随筆を読む","cards":[{"term":"随筆（エッセイ）","reading":"ずいひつ（えっせい）","meaning":"体験や見聞をもとに、感想や考えを自由な形式で書いた文章。","note":"小説との違いを意識して読むジャンル。","example":"随筆（エッセイ）は、書き手の体験や感想を自由に書く文章である。"},{"term":"書き手の視点","reading":"かきてのしてん","meaning":"書き手が何に注目し、どう感じているかという見方の位置。","note":"随筆では書き手自身の感じ方が中心になる。","example":"随筆を読むときは、書き手の視点がどこに向けられているかに注目する。"},{"term":"体験と感想","reading":"たいけんとかんそう","meaning":"実際に経験した出来事と、それに対する気持ちや考えの組み合わせ。","note":"随筆の基本的な構成要素。","example":"随筆では、体験と感想が結びついて書き手の考えが伝わってくる。"},{"term":"国語から旅立って","reading":"こくごからたびたって","meaning":"教科書に収められた随筆作品の題名の一つ。","note":"随筆を読むテーマで扱う教材名として覚える。","example":"『国語から旅立って』では、言葉と自分の関係が見つめ直されている。"},{"term":"クレールという女","reading":"くれーるというおんな","meaning":"教科書に収められた随筆作品に登場する人物名を含む題材。","note":"教材の内容を区別するための目印。","example":"『クレールという女』では、イタリアで出会った女性との記憶が語られる。"},{"term":"光の窓","reading":"ひかりのまど","meaning":"教科書に収められた随筆作品の題名の一つ。","note":"随筆教材の一つとして位置づけられる。","example":"『光の窓』では、窓の景色を通して日常の見え方が変わっていく。"},{"term":"清少納言","reading":"せいしょうなごん","meaning":"平安時代の女流作家。中宮定子に仕え、随筆『枕草子』を書いた。鋭い観察と機知に富む文章で知られる。","note":"『枕草子』の作者。『源氏物語』の紫式部と同時代の人物として区別して覚える。","example":"清少納言は、宮中の生活を鋭い目で観察して『枕草子』に書いた。"},{"term":"吉田兼好","reading":"よしだけんこう","meaning":"鎌倉時代の歌人・随筆家。随筆『徒然草』の作者で、世の無常や日常の気づきを短い段にまとめた。","note":"『徒然草』の作者。兼好法師とも呼ばれる。『方丈記』の鴨長明とは別の人物。","example":"吉田兼好は、出家した後に『徒然草』を書いたと言われている。"}]},{"topic":"戯曲―父と暮せば","cards":[{"term":"戯曲","reading":"ぎきょく","meaning":"舞台で上演するために書かれた作品。台詞とト書きで構成される。","note":"小説と違い、演じられることを前提とする形式。","example":"戯曲は、舞台で演じられることを前提に書かれた作品である。"},{"term":"井上ひさし","reading":"いのうえひさし","meaning":"『父と暮せば』の作者。劇作家・小説家として知られる。","note":"原爆を題材にした作品群でも知られる。","example":"井上ひさしは、戯曲「父と暮せば」で広島の父と娘を描いた。"},{"term":"美津江","reading":"みつえ","meaning":"『父と暮せば』の主人公で、原爆で父を失いながら生きる女性。","note":"父との対話を通して心の変化が描かれる。","example":"美津江は、生き残ったことへの苦しみから恋に臆病になっていた。"},{"term":"竹造","reading":"たけぞう","meaning":"美津江の父で、亡霊として娘の前に現れる人物。","note":"娘を励ます役割を担う。","example":"竹造は、幽霊となって現れ、娘の美津江を励まし続けた。"},{"term":"ト書き","reading":"とがき","meaning":"台詞以外の、場面や動作、心理などを指示する地の文。","note":"戯曲特有の要素として小説の地の文と区別する。","example":"戯曲では、ト書きに登場人物の動作や場面の様子が書かれている。"},{"term":"原爆文学","reading":"げんばくぶんがく","meaning":"原爆の被害や体験を題材にした文学の総称。","note":"『父と暮せば』が分類される分野。","example":"「父と暮せば」は、原爆文学の一つとして読み継がれている。"},{"term":"二人芝居","reading":"ふたりしばい","meaning":"登場人物が二人だけで演じられる芝居のこと。「父と暮せば」は美津江と竹造の二人だけで物語が進む。","note":"登場人物の少なさが、二人の会話の濃さにつながる形式として覚える。","example":"「父と暮せば」は、父と娘の二人芝居として上演される。"},{"term":"被爆者","reading":"ひばくしゃ","meaning":"原子爆弾によって被害を受けた人のこと。「父と暮せば」の美津江は、広島で被爆し、生き残った苦しみを抱えている。","note":"作品の主題である「生き残った者の苦しみ」と結びつけて覚える。","example":"美津江は、被爆者として生き残ったことへの苦しみを抱えていた。"}]},{"topic":"詩・短歌・俳句","cards":[{"term":"短歌","reading":"たんか","meaning":"五・七・五・七・七の三十一音で作る日本の定型詩。","note":"俳句との音数の違いで区別する。","example":"短歌は、五七五七七の三十一音で気持ちを表現する。"},{"term":"俳句","reading":"はいく","meaning":"五・七・五の十七音で作り、原則として季語を含む短い詩。","note":"世界で最も短い詩型の一つとされる。","example":"俳句は、五七五の十七音で季節の景色や気持ちを詠む。"},{"term":"季語","reading":"きご","meaning":"季節を表す決まった言葉で、俳句に季節感を与える要素。","note":"歳時記にまとめられている。","example":"俳句に季語を入れることで、季節の雰囲気が伝わってくる。"},{"term":"与謝野晶子","reading":"よさのあきこ","meaning":"明治期の歌人で、情熱的な歌集『みだれ髪』で知られる。","note":"短歌革新の代表的人物。","example":"与謝野晶子は、歌集『みだれ髪』で若い情熱を歌った。"},{"term":"正岡子規","reading":"まさおかしき","meaning":"俳句や短歌の革新を進めた明治期の文学者。","note":"写生の考え方を広めた人物。","example":"正岡子規は、写生を重んじて俳句や短歌の改革を進めた。"},{"term":"口語詩","reading":"こうごし","meaning":"日常の話し言葉で書かれた近代以降の詩。","note":"文語詩との対比で理解する。","example":"口語詩は、日常の話し言葉で書かれるため、親しみやすく感じられる。"},{"term":"定型詩","reading":"ていけいし","meaning":"短歌の五七五七七や俳句の五七五のように、音数や形式の約束が決まっている詩のこと。","note":"約束のない自由詩と対比して覚える。短歌と俳句はどちらも定型詩である。","example":"短歌や俳句は、決まった音数で作る定型詩である。"},{"term":"自由詩","reading":"じゆうし","meaning":"音数や行数などの形式の約束にとらわれず、自由に書かれる詩のこと。近代以降の詩の多くがこの形式で書かれた。","note":"定型詩と対比して覚える。萩原朔太郎らの近代詩が代表例。","example":"現代の詩の多くは、形式に縛られない自由詩として書かれている。"}]},{"topic":"古典文学の基礎","cards":[{"term":"源氏物語","reading":"げんじものがたり","meaning":"平安時代に紫式部が書いた長編物語で、光源氏を中心に描く。","note":"王朝文学の代表作。","example":"『源氏物語』は、光源氏の生涯を描いた平安時代の長編物語である。"},{"term":"枕草子","reading":"まくらのそうし","meaning":"平安時代に清少納言が書いた随筆で、「をかし」の美意識で知られる。","note":"随筆文学の代表作として徒然草と比べられる。","example":"『枕草子』には、清少納言の鋭い観察による文章が集められている。"},{"term":"竹取物語","reading":"たけとりものがたり","meaning":"かぐや姫の物語で、現存する最古の物語文学とされる作品。","note":"物語の祖と呼ばれる位置づけ。","example":"『竹取物語』は、かぐや姫の物語として知られる最古の物語である。"},{"term":"平家物語","reading":"へいけものがたり","meaning":"平家の興亡を描いた軍記物語で、琵琶法師によって語り広められた。","note":"「無常」の主題で知られる。","example":"『平家物語』は、平家の栄華と滅亡を描いた軍記物語である。"},{"term":"徒然草","reading":"つれづれぐさ","meaning":"鎌倉時代に兼好法師が書いた随筆集。","note":"枕草子・方丈記と並ぶ三大随筆の一つ。","example":"『徒然草』には、吉田兼好の日常への気づきが短い段にまとめられている。"},{"term":"万葉集","reading":"まんようしゅう","meaning":"奈良時代に編まれた現存最古の歌集で、幅広い身分の歌が収められる。","note":"和歌の原点として位置づけられる。","example":"『万葉集』には、天皇から庶民まで幅広い人々の歌が収められている。"},{"term":"紫式部","reading":"むらさきしきぶ","meaning":"平安時代の女流作家。長編物語『源氏物語』の作者で、宮中に仕えながら作品を書いた。","note":"『源氏物語』の作者。『枕草子』の清少納言と取り違えないよう注意する。","example":"紫式部は、宮中に仕えながら『源氏物語』を書き進めた。"},{"term":"鴨長明","reading":"かものちょうめい","meaning":"鎌倉時代の歌人・随筆家。随筆『方丈記』の作者で、災害や飢饉の様子と世の無常を書き記した。","note":"『方丈記』の作者。『徒然草』の吉田兼好とは時代も作品も区別して覚える。","example":"鴨長明は、小さな庵に住みながら『方丈記』を書いた。"}]}]},{"subject":"日本史","topics":[{"topic":"縄文・弥生時代","cards":[{"term":"縄文土器","reading":"じょうもんどき","meaning":"表面に縄目の文様をつけた土器で、煮炊きや貯蔵に使われた。厚手で多様な形がある。","note":"約1万年続いた縄文時代を代表する道具で、狩猟・採集生活の定着を示す。","example":"縄文土器の表面には、縄を押しつけたような文様が見られる。"},{"term":"貝塚","reading":"かいづか","meaning":"食べた貝の殻や骨などを捨てた場所が積み重なった遺跡。生活の様子を知る手がかりになる。","note":"食生活や道具が分かるため、当時の暮らしを復元する手がかりになる。","example":"貝塚からは、当時の人々が食べた貝の殻が多く見つかる。"},{"term":"三内丸山遺跡","reading":"さんないまるやまいせき","meaning":"青森県にある縄文時代の大規模な集落跡。大きな建物の柱穴や多くの出土品が見つかった。","note":"縄文社会が想像以上に大規模で計画的だったことを示す遺跡。","example":"三内丸山遺跡では、大きな建物の跡が見つかっている。"},{"term":"弥生土器","reading":"やよいどき","meaning":"薄手で赤褐色の、縄文土器よりすっきりした形の土器。稲作とともに広がった。","note":"弥生時代の始まりを示し、高床倉庫などとともに農耕社会を表す。","example":"弥生土器は、縄文土器より薄くて硬いのが特徴だ。"},{"term":"稲作の伝来","reading":"いなさくのでんらい","meaning":"大陸から水田で米を作る技術が伝わり、日本列島に広がった出来事。","note":"定住と余剰生産を生み、ムラからクニへ社会が変わる出発点になった。","example":"稲作の伝来によって、人々の生活は大きく変わった。"},{"term":"吉野ヶ里遺跡","reading":"よしのがりいせき","meaning":"佐賀県にある弥生時代の環濠集落跡。物見やぐらや墳丘墓が復元されている。","note":"防御を備えた大集落として、弥生時代の争いと社会のまとまりを示す。","example":"吉野ヶ里遺跡は、弥生時代の大規模な集落の跡だ。"},{"term":"邪馬台国","reading":"やまたいこく","meaning":"3世紀ごろ、女王卑弥呼が治めたと中国の史書に記された国。所在地は論争が続く。","note":"魏に使いを送った記録があり、初期の国家形成を考える中心テーマ。","example":"邪馬台国の場所については、今も議論が続いている。"},{"term":"打製石器","reading":"だせいせっき","meaning":"石を打ち欠いて作った石器で、旧石器時代から縄文時代にかけて狩猟などに使われた。","note":"磨いて作る磨製石器と作り方で区別する。","example":"打製石器は、獲物をしとめるための道具として使われた。"},{"term":"磨製石器","reading":"ませいせっき","meaning":"石を磨いて形を整えた石器で、縄文時代に広く使われた。","note":"「磨く」点が打製石器との違い。石斧などがある。","example":"磨製石器の石斧は、木を切り倒すのに役立った。"},{"term":"環濠集落","reading":"かんごうしゅうらく","meaning":"周囲に濠をめぐらせた弥生時代の集落で、外敵への備えと考えられている。","note":"吉野ヶ里遺跡が代表例。争いの時代を表す。","example":"環濠集落は、むらを守るために濠で囲まれていた。"},{"term":"青銅器","reading":"せいどうき","meaning":"銅と錫の合金で作られた道具や祭器で、弥生時代に大陸から伝わった。","note":"銅剣・銅矛・銅鐸が代表。銅鐸は祭りに使われた。","example":"青銅器の銅鐸は、豊作を祈る祭りに使われたとされる。"},{"term":"登呂遺跡","reading":"とろいせき","meaning":"静岡県にある弥生時代の集落と水田の遺跡で、稲作の様子が分かる。","note":"水田跡や高床倉庫が見つかったことで有名。","example":"登呂遺跡では、弥生時代の水田の跡が見つかった。"}]},{"topic":"飛鳥・奈良時代と律令国家","cards":[{"term":"聖徳太子（厩戸皇子）","reading":"しょうとくたいし（うまやどのおうじ）","meaning":"推古天皇のもとで政治を行い、冠位十二階や十七条の憲法を定めたとされる皇族。","note":"天皇中心の国家づくりを進めた飛鳥時代の中心人物。","example":"聖徳太子（厩戸皇子）は、推古天皇のもとで政治の改革を進めた。"},{"term":"大化の改新","reading":"たいかのかいしん","meaning":"645年に中大兄皇子らが蘇我氏を倒し、公地公民などを掲げた一連の改革。","note":"律令国家への歩みが始まった転換点として扱われる。","example":"大化の改新をきっかけに、天皇中心の国家づくりが進んだ。"},{"term":"律令","reading":"りつりょう","meaning":"律は刑罰、令は行政などの決まりをまとめた法体系。中国の制度を手本にした。","note":"中央集権的な国家運営の土台となり、班田収授や税制を支えた。","example":"律令に基づいて、全国の土地と人々が治められた。"},{"term":"班田収授法","reading":"はんでんしゅうじゅほう","meaning":"戸籍に基づき6歳以上の人々に口分田を与え、死後に返させる制度。","note":"公地公民を具体化し、租を集めるための土地制度だった。","example":"班田収授法では、戸籍に登録された人に口分田が与えられた。"},{"term":"租・調・庸","reading":"そ・ちょう・よう","meaning":"租は稲、調は特産物、庸は労役の代わりの布などを納める税の組み合わせ。","note":"律令制の税制の柱で、農民の負担の重さを示す。","example":"租・調・庸は、律令国家の税の基本をなしていた。"},{"term":"天平文化","reading":"てんぴょうぶんか","meaning":"奈良時代、唐や西域の影響を受けた国際色豊かな文化。正倉院宝物にその姿が残る。","note":"仏教を中心に栄え、東大寺の大仏造立とも結びつく。","example":"天平文化では、東大寺の大仏など仏教の影響が強い作品が生まれた。"},{"term":"冠位十二階","reading":"かんいじゅうにかい","meaning":"聖徳太子が定めた、家柄でなく才能や功績で役人を位づける制度。","note":"色で位を区別した。「十二階」と数を覚える。","example":"冠位十二階によって、能力のある人が役人になれる道が開かれた。"},{"term":"十七条の憲法","reading":"じゅうしちじょうのけんぽう","meaning":"聖徳太子が定めた、役人の心構えを示した17条の決まり。","note":"近代の憲法とは違い、道徳的な心得が中心。","example":"十七条の憲法では、和を大切にすることが説かれた。"},{"term":"大宝律令","reading":"たいほうりつりょう","meaning":"701年に完成した律と令で、律令国家の基本法となった。","note":"「大宝」は当時の年号。律は刑法、令は行政法。","example":"大宝律令が完成し、律令国家の仕組みが整った。"},{"term":"平城京","reading":"へいじょうきょう","meaning":"710年に奈良に造られた律令国家の都で、中国の都をまねた碁盤目状の都だった。","note":"遷都は元明天皇。長安をモデルにした。","example":"平城京には、全国から多くの人や物が集まった。"},{"term":"遣唐使","reading":"けんとうし","meaning":"唐の進んだ制度や文化を取り入れるために日本から派遣された使節。","note":"危険な航海で、多くの留学生も渡った。","example":"遣唐使は、唐の都の様子を日本に伝えた。"},{"term":"正倉院","reading":"しょうそういん","meaning":"東大寺に置かれた宝物を収める倉庫で、聖武天皇の遺品などが残る。","note":"校倉造の建物で、シルクロード経由の品も伝わる。","example":"正倉院には、聖武天皇ゆかりの宝物が収められている。"}]},{"topic":"平安時代と摂関政治","cards":[{"term":"平安遷都","reading":"へいあんせんと","meaning":"794年に桓武天皇が都を平安京へ移したこと。","note":"奈良時代から平安時代へ移る区切りで、約400年続く都の始まり。","example":"平安遷都によって、京都が長く日本の都となった。"},{"term":"摂関政治","reading":"せっかんせいじ","meaning":"藤原氏が幼い天皇の摂政や成年の関白となり、実権を握った政治の形。","note":"藤原道長の時期に最盛期を迎えた貴族政治の特徴。","example":"摂関政治の時代には、藤原氏が政治の実権を握った。"},{"term":"藤原道長","reading":"ふじわらのみちなが","meaning":"摂関政治の全盛期を築いた藤原氏の人物。娘たちを天皇の后とした。","note":"『この世をば』で知られ、御堂関白と呼ばれた権力者。","example":"藤原道長の時代に、摂関政治は最も栄えた。"},{"term":"国風文化","reading":"こくふうぶんか","meaning":"唐との交流が弱まる中で、日本の風土に合った貴族文化が育った平安中期の文化。","note":"かな文字や和歌、寝殿造など日本的な表現が広がった時期。","example":"国風文化では、日本の風土に合った文化が生まれた。"},{"term":"かな文字","reading":"かなもじ","meaning":"漢字の音を借りたり崩したりして作られた、ひらがな・カタカナのもとになる文字。","note":"女性の文学を支え、国風文化の成立に大きく関わった。","example":"かな文字の発達で、日本語を書き表しやすくなった。"},{"term":"源氏物語と枕草子","reading":"げんじものがたりとまくらのそうし","meaning":"紫式部と清少納言による平安貴族社会を描いた代表的な文学作品。","note":"かな文学の頂点として、国風文化を象徴する組み合わせ。","example":"源氏物語と枕草子は、平安時代の女流文学を代表する作品だ。"},{"term":"菅原道真","reading":"すがわらのみちざね","meaning":"平安時代の学者・政治家で、遣唐使の停止を建言した人物。","note":"右大臣まで進んだが、のちに大宰府へ左遷された。","example":"菅原道真の建言により、遣唐使は停止された。"},{"term":"平等院鳳凰堂","reading":"びょうどういんほうおうどう","meaning":"藤原頼通が宇治に建てた阿弥陀堂で、浄土信仰を表す建築。","note":"10円硬貨の図柄としても知られる。","example":"平等院鳳凰堂は、極楽浄土をこの世に表そうと建てられた。"},{"term":"末法思想","reading":"まっぽうしそう","meaning":"仏教の教えがすたれる末法の世が来るという考えで、平安時代に広まった。","note":"1052年が末法の始まりとされ、浄土信仰が広がった。","example":"末法思想の広がりとともに、阿弥陀仏への信仰が深まった。"},{"term":"荘園","reading":"しょうえん","meaning":"貴族や寺社が私有した土地で、平安時代以降に増え、税が免除されることもあった。","note":"公地公民の原則がくずれていく原因の一つ。","example":"荘園が増えると、国の税収入は減っていった。"},{"term":"寝殿造","reading":"しんでんづくり","meaning":"平安時代の貴族の邸宅の建築様式で、寝殿を中心に庭園を配した。","note":"国風文化の建築を代表する様式。","example":"寝殿造の屋敷では、池のある庭で宴が開かれた。"},{"term":"今昔物語集","reading":"こんじゃくものがたりしゅう","meaning":"平安時代末に成立した説話集で、インド・中国・日本の説話を集めた。","note":"「今は昔」で始まる語り口が特徴。","example":"今昔物語集には、庶民の姿を描いた話も多く収められている。"}]},{"topic":"鎌倉幕府と武士の社会","cards":[{"term":"源頼朝","reading":"みなもとのよりとも","meaning":"平氏を倒し、鎌倉に幕府を開いて初代将軍となった武士の棟梁。","note":"武家政権を全国的な仕組みにした鎌倉時代の創始者。","example":"源頼朝は、鎌倉に幕府を開いて武士の政治を始めた。"},{"term":"守護・地頭","reading":"しゅご・じとう","meaning":"守護は国ごとの治安や軍事、地頭は荘園・公領の管理を担った幕府の役職。","note":"幕府が全国を支配するための両輪となった制度。","example":"守護・地頭は、幕府が地方を治めるために置いた役職だ。"},{"term":"御恩と奉公","reading":"ごおんとほうこう","meaning":"将軍が土地などを与え、御家人が軍役などで応える主従関係の結びつき。","note":"鎌倉武士社会の土台で、土地を通じた結びつきが特徴。","example":"御恩と奉公の関係が、将軍と御家人を結びつけていた。"},{"term":"執権政治","reading":"しっけんせいじ","meaning":"将軍を補佐する執権の北条氏が幕府の実権を握った政治。","note":"北条泰時らが御成敗式目を定め、武家法を整えた時期。","example":"執権政治では、北条氏が幕府の実権を握った。"},{"term":"元寇","reading":"げんこう","meaning":"13世紀後半、元が二度にわたり日本へ攻めてきた出来事。文永・弘安の役という。","note":"御家人の負担を増やし、幕府の力を弱める要因の一つになった。","example":"元寇のとき、幕府は九州の防備を固めた。"},{"term":"御成敗式目","reading":"ごせいばいしきもく","meaning":"1232年に定められた、武家社会の慣習をもとにした最初の武家法。","note":"裁判の基準を明らかにし、後の武家法の基礎になった。","example":"御成敗式目は、武士の裁判の基準となった。"},{"term":"北条泰時","reading":"ほうじょうやすとき","meaning":"鎌倉幕府の3代執権で、御成敗式目を制定した人物。","note":"御成敗式目は武士の法律の基準となった。","example":"北条泰時は、御成敗式目を定めて裁判の基準を示した。"},{"term":"承久の乱","reading":"じょうきゅうのらん","meaning":"1221年に後鳥羽上皇が幕府を倒そうとして敗れた乱。","note":"幕府の勝利で朝廷への支配が強まった。","example":"承久の乱の後、幕府は朝廷の監視を強めた。"},{"term":"六波羅探題","reading":"ろくはらたんだい","meaning":"承久の乱の後に京都に置かれた幕府の出先機関で、朝廷の監視などを行った。","note":"京都の六波羅に置かれたことが名前の由来。","example":"六波羅探題は、京都で朝廷の動きを見張った。"},{"term":"永仁の徳政令","reading":"えいにんのとくせいれい","meaning":"1297年に出された徳政令で、御家人の借金の帳消しなどを命じた。","note":"借金に苦しむ御家人を救うためだったが混乱も招いた。","example":"永仁の徳政令によって、御家人の借金は帳消しにされた。"},{"term":"日蓮","reading":"にちれん","meaning":"鎌倉時代の僧で、法華経を重んじる日蓮宗を開いた人物。","note":"『立正安国論』を著して幕府に訴えた。","example":"日蓮は、法華経こそが国を救う教えだと説いた。"},{"term":"親鸞","reading":"しんらん","meaning":"浄土真宗を開いた鎌倉時代の僧で、法然の弟子。","note":"阿弥陀仏の力に頼る他力本願を説いた。","example":"親鸞は、越後や関東で念仏の教えを広めた。"}]},{"topic":"室町時代と戦国への歩み","cards":[{"term":"足利尊氏と室町幕府","reading":"あしかがたかうじとむろまちばくふ","meaning":"尊氏が京都に開いた武家政権。幕府の所在地が室町に移ったことから名がついた。","note":"鎌倉幕府滅亡後の新たな武家政権として室町時代を開いた。","example":"足利尊氏と室町幕府の成立によって、武家政治は新しい段階に入った。"},{"term":"南北朝の動乱","reading":"なんぼくちょうのどうらん","meaning":"天皇家が南朝と北朝に分かれて争った14世紀の内乱状態。","note":"幕府と朝廷の関係を揺るがし、地方の武士の力を高めた。","example":"南北朝の動乱は、半世紀以上にわたって続いた。"},{"term":"足利義満と日明貿易","reading":"あしかがよしみつとにちみんぼうえき","meaning":"義満が明との正式な貿易を始め、勘合を用いて倭寇と区別した交易。","note":"金閣の北山文化を支える富をもたらした外交・貿易。","example":"足利義満と日明貿易の関係は、室町幕府の財政を支えた。"},{"term":"応仁の乱","reading":"おうにんのらん","meaning":"1467年に始まった、将軍家の継承と有力大名の対立が重なった内乱。","note":"幕府の権威を大きく落とし、戦国時代へ進むきっかけになった。","example":"応仁の乱の後、将軍の力は大きく衰えた。"},{"term":"下剋上","reading":"げこくじょう","meaning":"身分の低い者が実力で上の者を倒し、成り上がる風潮や出来事。","note":"戦国大名の登場を象徴する、室町後期の社会の動き。","example":"下剋上の風潮の中で、実力のある者が上の者を倒してのし上がった。"},{"term":"東山文化","reading":"ひがしやまぶんか","meaning":"足利義政のもと、銀閣や書院造、茶の湯など落ち着いた美意識が育った文化。","note":"現在の和室や侘びの感覚につながる室町後期の文化。","example":"東山文化には、わびやさびを重んじる落ち着いた美しさがある。"},{"term":"建武の新政","reading":"けんむのしんせい","meaning":"後醍醐天皇が鎌倉幕府を倒した後に行った天皇中心の政治。","note":"武士の不満を招き、短期間で終わった。","example":"建武の新政は、武士の反発を受けて崩れた。"},{"term":"後醍醐天皇","reading":"ごだいごてんのう","meaning":"鎌倉幕府を倒し建武の新政を行った天皇。","note":"のちに吉野へ移り、南朝を開いた。","example":"後醍醐天皇は、幕府を倒して自ら政治を行おうとした。"},{"term":"鹿苑寺金閣","reading":"ろくおんじきんかく","meaning":"足利義満が京都に建てた金箔を貼った楼閣で、北山文化を代表する。","note":"金閣は義満の別荘の一部だった。","example":"鹿苑寺金閣は、北山文化の豪華さを今に伝える。"},{"term":"慈照寺銀閣","reading":"じしょうじぎんかく","meaning":"足利義政が京都に建てた楼閣で、東山文化を代表する。","note":"銀箔は貼られていない。わび・さびの文化と結びつく。","example":"慈照寺銀閣の落ち着いた姿は、東山文化の特徴を示す。"},{"term":"勘合","reading":"かんごう","meaning":"日明貿易で正式な貿易船であることを証明するために使われた合札。","note":"倭寇と区別するために用いられた。","example":"勘合を持つ船だけが、明との貿易を許された。"},{"term":"雪舟","reading":"せっしゅう","meaning":"室町時代の画僧で、水墨画を大成した人物。","note":"明へ渡って絵を学んだ。国宝の水墨画が多い。","example":"雪舟の水墨画は、日本の風景を力強く描いている。"}]},{"topic":"戦国時代と織田・豊臣","cards":[{"term":"織田信長","reading":"おだのぶなが","meaning":"尾張から勢力を広げ、室町幕府を滅ぼして天下統一に近づいた戦国大名。","note":"革新的な政策で知られ、豊臣秀吉へ統一事業が引き継がれた。","example":"織田信長は、天下統一を目指して次々と戦いに勝った。"},{"term":"楽市・楽座","reading":"らくいち・らくざ","meaning":"市場の税を免じたり座の特権を廃したりして、商工業の自由を促した政策。","note":"信長が城下町の発展を狙って進めた経済政策。","example":"楽市・楽座によって、城下町の商工業は活発になった。"},{"term":"豊臣秀吉","reading":"とよとみひでよし","meaning":"信長の後を継ぎ、全国統一を果たした武将。農民出身から関白に上りつめた。","note":"太閤検地と刀狩で兵農分離を進めた統一政権の中心。","example":"豊臣秀吉は、信長の後を継いで全国統一を果たした。"},{"term":"太閤検地","reading":"たいこうけんち","meaning":"全国の田畑を測り、収穫量を石高で表して耕作者を登録した土地調査。","note":"石高制の基礎となり、年貢徴収と身分統制を強めた。","example":"太閤検地で、田畑の面積や収穫量が統一的に調べられた。"},{"term":"刀狩","reading":"かたながり","meaning":"農民から刀などの武器を取り上げ、農業に専念させた政策。","note":"一揆を防ぎ、武士と農民を分ける兵農分離を進めた。","example":"刀狩によって、農民から武器が取り上げられた。"},{"term":"長篠の戦い","reading":"ながしののたたかい","meaning":"1575年、織田・徳川連合軍が武田軍を破った合戦。鉄砲の活用で知られる。","note":"戦国時代の戦い方と勢力図を変えた出来事として扱われる。","example":"長篠の戦いでは、鉄砲隊の活躍が勝敗を分けた。"},{"term":"桶狭間の戦い","reading":"おけはざまのたたかい","meaning":"1560年に織田信長が今川義元を破った戦い。","note":"少数の軍で大軍を破ったことで信長の名が高まった。","example":"桶狭間の戦いで、信長は東海の大名今川義元を破った。"},{"term":"本能寺の変","reading":"ほんのうじのへん","meaning":"1582年に明智光秀が織田信長を襲い、信長が自害した事件。","note":"この後、秀吉が光秀を破って後継者となった。","example":"本能寺の変で信長が倒れ、天下統一は秀吉に引き継がれた。"},{"term":"明智光秀","reading":"あけちみつひで","meaning":"織田信長の家臣で、本能寺の変で信長を襲った武将。","note":"変の直後、山崎の戦いで秀吉に敗れた。","example":"明智光秀は、本能寺で信長を急襲した。"},{"term":"安土城","reading":"あづちじょう","meaning":"織田信長が琵琶湖のほとりに築いた豪華な城。","note":"天守を持つ城の代表例とされる。","example":"安土城は、信長の権威を示す壮大な城だった。"},{"term":"南蛮貿易","reading":"なんばんぼうえき","meaning":"ポルトガルやスペインとの貿易で、鉄砲やキリスト教などが伝わった。","note":"「南蛮」は南から来た人々への呼び名。","example":"南蛮貿易によって、新しい品物や文化が日本に入ってきた。"},{"term":"バテレン追放令","reading":"ばてれんついほうれい","meaning":"豊臣秀吉が出した、キリスト教の宣教師の国外追放を命じた法令。","note":"貿易は続けられたため、徹底されなかった面もある。","example":"バテレン追放令が出された後も、南蛮貿易は続けられた。"}]},{"topic":"江戸幕府の成立","cards":[{"term":"徳川家康","reading":"とくがわいえやす","meaning":"関ヶ原の戦いに勝ち、江戸に幕府を開いた初代将軍。","note":"約260年続く江戸幕府の仕組みの出発点を作った人物。","example":"徳川家康は、関ヶ原の戦いに勝って幕府を開いた。"},{"term":"関ヶ原の戦い","reading":"せきがはらのたたかい","meaning":"1600年、家康率いる東軍が石田三成らの西軍を破った天下分け目の合戦。","note":"徳川氏による支配が決定的になり、幕府成立へつながった。","example":"関ヶ原の戦いの勝利が、徳川氏の支配を決定づけた。"},{"term":"大坂の陣","reading":"おおさかのじん","meaning":"1614〜15年、幕府が豊臣氏を滅ぼした戦い。冬の陣と夏の陣がある。","note":"豊臣氏の滅亡で、徳川政権への大きな対抗勢力が消えた。","example":"大坂の陣で豊臣家が滅び、幕府の支配は固まった。"},{"term":"武家諸法度","reading":"ぶけしょはっと","meaning":"大名を統制するために幕府が出した法令。城の修理や婚姻などに制限をかけた。","note":"参勤交代の義務づけなど、幕藩体制を固める道具になった。","example":"武家諸法度によって、大名の行動は厳しく制限された。"},{"term":"参勤交代","reading":"さんきんこうたい","meaning":"大名が江戸と領地を1年おきに行き来し、妻子を江戸に住まわせた制度。","note":"大名の財政負担と江戸の発展を生んだ江戸時代の代表制度。","example":"参勤交代のため、大名は多くの費用を使うことになった。"},{"term":"鎖国","reading":"さこく","meaning":"対外関係を長崎など限られた窓口に絞り、キリスト教を厳しく取り締まった体制。","note":"近年は『鎖国』という言葉より、限定的な外交管理として理解される。","example":"鎖国の時代にも、長崎などでは限られた貿易が続けられた。"},{"term":"一国一城令","reading":"いっこくいちじょうれい","meaning":"大名に居城以外の城を取り壊すよう命じた幕府の法令。","note":"大名の軍事力を抑えることが目的だった。","example":"一国一城令により、大名は多くの城を失った。"},{"term":"禁中並公家諸法度","reading":"きんちゅうならびにくげしょはっと","meaning":"幕府が天皇や公家の行動を制限するために定めた法令。","note":"朝廷も幕府の統制下に置かれたことを示す。","example":"禁中並公家諸法度によって、朝廷は幕府の監視下に置かれた。"},{"term":"島原の乱","reading":"しまばらのらん","meaning":"1637年に九州の島原・天草で起きた、キリスト教徒らによる一揆。","note":"この乱の後、鎖国の体制がさらに固まった。","example":"島原の乱は、鎖国が完成するきっかけの一つとなった。"},{"term":"出島","reading":"でじま","meaning":"長崎に造られた人工島で、鎖国期にオランダ商館が置かれた。","note":"オランダとの貿易の窓口となった場所。","example":"出島では、オランダ人との貿易が行われた。"},{"term":"五街道","reading":"ごかいどう","meaning":"江戸を起点とする東海道など五つの主要な街道。","note":"参勤交代の通行で整備が進んだ。","example":"五街道沿いには、多くの宿場町が栄えた。"},{"term":"徳川家光","reading":"とくがわいえみつ","meaning":"江戸幕府の3代将軍で、参勤交代の制度化や鎖国の完成を進めた人物。","note":"武家諸法度の改定で参勤交代を定めた。","example":"徳川家光の時代に、幕藩体制の基礎が固まった。"}]},{"topic":"江戸時代の社会と改革","cards":[{"term":"身分制度","reading":"みぶんせいど","meaning":"武士・百姓・町人などに人々を分け、職業や暮らしを規制した江戸時代の秩序。","note":"幕藩体制を支えたが、実際には身分を越えた動きもあった。","example":"身分制度のもとで、人々の職業や暮らしは身分によって決められた。"},{"term":"村請制と五人組","reading":"むらうけせいとごにんぐみ","meaning":"村全体で年貢を請け負い、5戸ほどの組で互いに責任を持たせた仕組み。","note":"農村統制の基本で、年貢の確保と治安維持に使われた。","example":"村請制と五人組によって、村全体で年貢や治安に責任を持った。"},{"term":"享保の改革","reading":"きょうほうのかいかく","meaning":"8代将軍徳川吉宗が財政再建や目安箱の設置などを進めた改革。","note":"三大改革の最初で、質素倹約と新田開発が柱だった。","example":"享保の改革では、徳川吉宗が幕府の財政再建に取り組んだ。"},{"term":"田沼意次と寛政の改革","reading":"たぬまおきつぐとかんせいのかいかく","meaning":"商業を重視した田沼の政治の後、松平定信が厳しい引き締めを行った改革。","note":"経済政策の方向が正反対に振れた対比で覚えるテーマ。","example":"田沼意次と寛政の改革は、商業への態度が対照的な政策として比べられる。"},{"term":"天保の改革","reading":"てんぽうのかいかく","meaning":"水野忠邦が倹約令や人返し令などを出した、江戸幕府最後の大きな改革。","note":"三大改革の一つだが、効果は限られ幕府の衰えが目立った。","example":"天保の改革では、水野忠邦が幕府の引き締めを図った。"},{"term":"化政文化","reading":"かせいぶんか","meaning":"江戸を中心に町人の好みを反映した文学・浮世絵などが栄えた文化。","note":"元禄文化と並ぶ江戸文化の山で、庶民の広がりが特徴。","example":"化政文化は、江戸を中心に町人の文化として栄えた。"},{"term":"上げ米の制","reading":"あげまいのせい","meaning":"享保の改革で、大名に石高に応じた米を幕府へ納めさせる代わりに参勤交代を軽くした制度。","note":"財政難の幕府を助けるための一時的な対策だった。","example":"上げ米の制は、幕府の米不足を補うために行われた。"},{"term":"公事方御定書","reading":"くじかたおさだめがき","meaning":"享保の改革で作られた、裁判や刑罰の基準をまとめた法令集。","note":"徳川吉宗の時代に編さんされた。","example":"公事方御定書によって、裁判の基準が統一された。"},{"term":"株仲間","reading":"かぶなかま","meaning":"江戸時代に幕府から営業を認められた商人・職人の同業者組合。","note":"田沼意次は株仲間を奨励し、税を取ろうとした。","example":"株仲間は、営業の独占を認められていた。"},{"term":"人返しの法","reading":"ひとがえしのほう","meaning":"天保の改革で出された、江戸へ集まった農民を農村へ帰すよう命じた法令。","note":"農村の労働力を確保することが目的だった。","example":"人返しの法によって、農民の江戸への移住が制限された。"},{"term":"大塩平八郎の乱","reading":"おおしおへいはちろうのらん","meaning":"1837年に大坂で起きた、元役人の大塩平八郎らによる反乱。","note":"天保の飢饉への幕府の対応に不満が高まっていた。","example":"大塩平八郎の乱は、幕府に大きな衝撃を与えた。"},{"term":"打ちこわし","reading":"うちこわし","meaning":"江戸時代に都市の民衆が米屋などを襲った暴動。","note":"物価の高騰や飢饉のときに多く起きた。","example":"打ちこわしでは、米を買い占める商人の店が襲われた。"}]},{"topic":"明治維新","cards":[{"term":"ペリー来航","reading":"ぺりーらいこう","meaning":"1853年、アメリカのペリーが浦賀に来て開国を求めた出来事。","note":"幕末の動揺を決定的にし、開国と維新への流れを加速させた。","example":"ペリー来航は、日本が開国へ向かう大きなきっかけとなった。"},{"term":"日米和親条約","reading":"にちべいわしんじょうやく","meaning":"1854年に結ばれた、下田と箱館を開くなどした日本とアメリカの条約。","note":"鎖国体制が崩れる第一歩となった条約。","example":"日米和親条約によって、日本はアメリカ船への補給を認めた。"},{"term":"大政奉還","reading":"たいせいほうかん","meaning":"1867年、徳川慶喜が政権を朝廷へ返したこと。","note":"江戸幕府が終わり、明治政府樹立へ進む区切りになった。","example":"大政奉還によって、江戸幕府の時代は終わりを迎えた。"},{"term":"廃藩置県","reading":"はいはんちけん","meaning":"藩を廃して県を置き、知藩事を免じて中央から府知事・県令を送った改革。","note":"中央集権国家を作るための明治初期の大きな一歩。","example":"廃藩置県で、藩はなくなり県が置かれるようになった。"},{"term":"地租改正","reading":"ちそかいせい","meaning":"土地の価格の3％を現金で納めさせる税制改革。地券を発行した。","note":"政府の安定した収入源となり、近代的な土地所有を進めた。","example":"地租改正によって、税は米ではなく現金で納めるようになった。"},{"term":"殖産興業","reading":"しょくさんこうぎょう","meaning":"官営工場の設立などで産業を育て、国を富ませようとした政策。","note":"富国強兵と並ぶ明治政府の基本方針の一つ。","example":"殖産興業のもとで、官営工場が各地に作られた。"},{"term":"岩倉使節団","reading":"いわくらしせつだん","meaning":"岩倉具視を大使として欧米へ派遣された使節団で、欧米の制度や産業を調査した。","note":"条約改正の交渉も目的の一つだったが成果は限られた。","example":"岩倉使節団は、欧米諸国の進んだ仕組みを学んで帰国した。"},{"term":"徴兵令","reading":"ちょうへいれい","meaning":"満20歳以上の男子に兵役の義務を課した明治初期の法令。","note":"国民皆兵を目指し、武士だけの軍隊から変わった。","example":"徴兵令によって、身分によらない軍隊が作られた。"},{"term":"学制","reading":"がくせい","meaning":"1872年に公布された、全国に小学校を置く近代的な教育制度。","note":"国民皆学を目指した最初の教育制度。","example":"学制が公布され、全国に小学校が作られていった。"},{"term":"富岡製糸場","reading":"とみおかせいしじょう","meaning":"群馬県に作られた官営の製糸工場で、殖産興業のモデルとなった。","note":"フランスの技術を取り入れて建設された。","example":"富岡製糸場では、多くの女性工員が働いた。"},{"term":"西南戦争","reading":"せいなんせんそう","meaning":"1877年に西郷隆盛を中心とする士族が起こした、最大の士族の反乱。","note":"政府軍の勝利で士族の反乱は終わった。","example":"西南戦争の敗北で、西郷隆盛は命を落とした。"},{"term":"自由民権運動","reading":"じゆうみんけんうんどう","meaning":"国会の開設や憲法の制定を求めた明治時代の政治運動。","note":"板垣退助らが中心となり、全国へ広がった。","example":"自由民権運動の高まりが、国会開設を後押しした。"}]},{"topic":"立憲政治と日清・日露戦争","cards":[{"term":"大日本帝国憲法","reading":"だいにっぽんていこくけんぽう","meaning":"1889年発布の、天皇が定める欽定憲法。プロイセンの憲法を参考にした。","note":"帝国議会開設とともに立憲政治の枠組みを作った。","example":"大日本帝国憲法は、天皇が定めた欽定憲法だった。"},{"term":"帝国議会","reading":"ていこくぎかい","meaning":"貴族院と衆議院からなる議会。1890年に初めて開かれた。","note":"予算審議などを通じ、政党が力を伸ばす舞台になった。","example":"帝国議会は、衆議院と貴族院の二院から成っていた。"},{"term":"条約改正","reading":"じょうやくかいせい","meaning":"幕末に結んだ不平等条約を改め、関税自主権や領事裁判権の問題を解消する取り組み。","note":"陸奥宗光と小村寿太郎の時期に段階的に達成された外交課題。","example":"条約改正によって、日本は関税自主権などを取り戻していった。"},{"term":"日清戦争","reading":"にっしんせんそう","meaning":"1894〜95年、朝鮮をめぐり日本と清が戦った戦争。下関条約で決着した。","note":"遼東半島などを得たが三国干渉を受け、対露意識が高まった。","example":"日清戦争は、朝鮮をめぐる日本と清の対立から始まった。"},{"term":"日露戦争","reading":"にちろせんそう","meaning":"1904〜05年、満洲と朝鮮をめぐる日本とロシアの戦争。ポーツマス条約で終わった。","note":"日本の勝利はアジア諸国に影響を与えた一方、国民の負担も大きかった。","example":"日露戦争では、日本は大きな犠牲を払って勝利した。"},{"term":"産業革命の進展","reading":"さんぎょうかくめいのしんてん","meaning":"日清戦争前後から軽工業、日露戦争前後から重工業で機械制生産が広がった動き。","note":"紡績から製鉄へと広がり、日本の資本主義の土台ができた。","example":"産業革命の進展で、工場で働く人々が増えていった。"},{"term":"伊藤博文","reading":"いとうひろぶみ","meaning":"初代内閣総理大臣で、大日本帝国憲法の制定に中心的な役割を果たした人物。","note":"ドイツの憲法を参考に調査を行った。","example":"伊藤博文は、憲法の草案づくりを主導した。"},{"term":"下関条約","reading":"しものせきじょうやく","meaning":"日清戦争の講和条約で、清が遼東半島や台湾などを日本へ譲ることなどを決めた。","note":"賠償金も得て、日本の軍備拡張に使われた。","example":"下関条約で、日本は台湾などを獲得した。"},{"term":"三国干渉","reading":"さんごくかんしょう","meaning":"ロシア・ドイツ・フランスが日本に遼東半島を清へ返すよう求めた出来事。","note":"日本は要求を受け入れ、ロシアへの対抗心が強まった。","example":"三国干渉によって、日本は遼東半島を手放した。"},{"term":"ポーツマス条約","reading":"ぽーつますじょうやく","meaning":"日露戦争の講和条約で、アメリカ大統領の仲介で結ばれた。","note":"賠償金は得られず、国民の不満が高まった。","example":"ポーツマス条約で、日露戦争は終わった。"},{"term":"日英同盟","reading":"にちえいどうめい","meaning":"1902年に日本とイギリスが結んだ同盟で、ロシアへの対抗が目的だった。","note":"日露戦争を有利に進める背景となった。","example":"日英同盟の成立で、日本はロシアと対峙する体制を整えた。"},{"term":"八幡製鉄所","reading":"やはたせいてつしょ","meaning":"日清戦争の賠償金をもとに福岡県に作られた官営の製鉄所。","note":"日本の重工業の発展を支えた。","example":"八幡製鉄所の稼働は、日本の産業革命を進めた。"}]},{"topic":"大正デモクラシーと両大戦間期","cards":[{"term":"大正デモクラシー","reading":"たいしょうでもくらしー","meaning":"大正期に広がった民主主義や自由主義を求める風潮。吉野作造の民本主義が知られる。","note":"政党政治や普通選挙運動、社会運動の高まりと結びつく。","example":"大正デモクラシーの広がりで、普通選挙を求める声が高まった。"},{"term":"政党内閣","reading":"せいとうないかく","meaning":"衆議院の多数党をもとに内閣が作られる政治の形。原敬内閣が本格的な始まりとされる。","note":"大正から昭和初期に定着したが、1932年に途絶えた。","example":"政党内閣の時代には、政党の総裁が首相になることが続いた。"},{"term":"普通選挙法","reading":"ふつうせんきょほう","meaning":"1925年、25歳以上の男性すべてに選挙権を与えた法律。","note":"納税資格が外れた一方、同時に治安維持法も制定された。","example":"普通選挙法によって、25歳以上の男子が選挙権を得た。"},{"term":"治安維持法","reading":"ちあんいじほう","meaning":"社会主義運動などを取り締まるために1925年に制定された法律。","note":"言論や思想への統制を強める道具として拡大されていった。","example":"治安維持法は、社会主義運動などを取り締まるために使われた。"},{"term":"世界恐慌","reading":"せかいきょうこう","meaning":"1929年にアメリカから始まった世界的な経済不況。","note":"日本でも昭和恐慌が起こり、農村の困窮や軍部の台頭につながった。","example":"世界恐慌の影響で、日本の輸出は大きく落ち込んだ。"},{"term":"大衆文化の広がり","reading":"たいしゅうぶんかのひろがり","meaning":"ラジオや映画、雑誌などが都市の人々の日常に入り込んだ大正・昭和初期の変化。","note":"生活様式の近代化を示し、モダンな文化が広がった。","example":"大衆文化の広がりで、映画やラジオが人々の楽しみになった。"},{"term":"米騒動","reading":"こめそうどう","meaning":"1918年に米の値上がりに抗議して全国へ広がった騒動。","note":"シベリア出兵を見込んだ米の買い占めが背景にあった。","example":"米騒動は、富山県の女性たちの行動から全国へ広がった。"},{"term":"原敬","reading":"はらたかし","meaning":"立憲政友会の総裁で、本格的な政党内閣を組織した首相。","note":"爵位を持たないことから「平民宰相」と呼ばれた。","example":"原敬は、政党の力を背景に内閣を作った。"},{"term":"関東大震災","reading":"かんとうだいしんさい","meaning":"1923年に首都圏を襲った大地震で、大きな被害が出た。","note":"震災後の不況も社会を不安定にした。","example":"関東大震災では、東京や横浜で多くの建物が倒壊した。"},{"term":"吉野作造","reading":"よしのさくぞう","meaning":"民本主義を唱えた政治学者で、大正デモクラシーの理論を支えた人物。","note":"主権の所在でなく政治の目的を民衆の利益に置いた。","example":"吉野作造の民本主義は、大正デモクラシーを後押しした。"},{"term":"民本主義","reading":"みんぽんしゅぎ","meaning":"政治は民衆の利益のために行われるべきだとする吉野作造の考え。","note":"天皇主権と両立する形で説かれた点が特徴。","example":"民本主義の考えは、普通選挙を求める動きを支えた。"},{"term":"第一次世界大戦","reading":"だいいちじせかいたいせん","meaning":"1914年に始まった世界規模の戦争で、日本も連合国側で参戦した。","note":"戦時景気で日本の輸出が増えた時期でもある。","example":"第一次世界大戦の間、日本の工業生産は大きく伸びた。"}]},{"topic":"太平洋戦争と戦後","cards":[{"term":"太平洋戦争","reading":"たいへいようせんそう","meaning":"1941年の真珠湾攻撃に始まり、アジア・太平洋で広がった戦争。","note":"日中戦争から続く十五年戦争の後半として位置づけられる。","example":"太平洋戦争では、アジア・太平洋の広い地域が戦場となった。"},{"term":"ポツダム宣言","reading":"ぽつだむせんげん","meaning":"1945年、連合国が日本に降伏を求めて出した宣言。日本はこれを受諾した。","note":"戦争終結と占領政策の出発点になった文書。","example":"ポツダム宣言の受諾によって、日本の敗戦が決まった。"},{"term":"日本国憲法","reading":"にっぽんこくけんぽう","meaning":"国民主権・平和主義・基本的人権の尊重を柱とする戦後の憲法。1947年施行。","note":"戦後民主主義の土台となり、大日本帝国憲法と対比される。","example":"日本国憲法では、国民主権が基本原理の一つとされた。"},{"term":"農地改革","reading":"のうちかいかく","meaning":"地主の土地を政府が買い上げ、小作農に安く売り渡して自作農を増やした改革。","note":"戦後改革の一つで、農村の民主化を進めた。","example":"農地改革によって、多くの小作農が自作農となった。"},{"term":"サンフランシスコ平和条約","reading":"さんふらんしすこへいわじょうやく","meaning":"1951年に結ばれ、日本が独立を回復する根拠となった講和条約。","note":"同時に日米安全保障条約も結ばれ、戦後の国際関係の枠ができた。","example":"サンフランシスコ平和条約の発効で、日本は独立を回復した。"},{"term":"高度経済成長","reading":"こうどけいざいせいちょう","meaning":"1950年代半ばから1970年代初めまで、経済が急速に拡大した時期。","note":"生活水準が大きく変わり、公害問題も深刻化した時代。","example":"高度経済成長の時期に、人々の暮らしは大きく豊かになった。"},{"term":"日中戦争","reading":"にっちゅうせんそう","meaning":"1937年に始まった日本と中国の戦争で、長期化して戦線が拡大した。","note":"この長期戦が太平洋戦争への流れにもつながった。","example":"日中戦争の長期化で、日本の物資は不足していった。"},{"term":"国家総動員法","reading":"こっかそうどういんほう","meaning":"戦争のために人や物資を政府が統制できるようにした法律。","note":"議会の承認なしに統制を進められる面があった。","example":"国家総動員法によって、国民生活への統制が強まった。"},{"term":"学徒出陣","reading":"がくとしゅつじん","meaning":"戦争の激化に伴い、大学生などが軍へ動員されたこと。","note":"文科系学生の徴兵猶予が停止されて行われた。","example":"学徒出陣で、多くの学生が戦地へ送られた。"},{"term":"疎開","reading":"そかい","meaning":"空襲から逃れるため、都市の子どもなどが地方へ移されたこと。","note":"学童疎開では児童が親元を離れて生活した。","example":"疎開した子どもたちは、地方で集団生活を送った。"},{"term":"財閥解体","reading":"ざいばつかいたい","meaning":"戦後の占領改革の一つで、経済を独占していた財閥を解体したこと。","note":"GHQの民主化政策の一つ。","example":"財閥解体によって、経済の民主化が進められた。"},{"term":"東京裁判","reading":"とうきょうさいばん","meaning":"戦後、戦争指導者の責任を裁いた極東国際軍事裁判のこと。","note":"東京で開かれたことからこの名で呼ばれる。","example":"東京裁判では、戦争犯罪の責任が問われた。"}]},{"topic":"戦後の復興と高度経済成長","cards":[{"term":"朝鮮戦争と特需","reading":"ちょうせんせんそうととくじゅ","meaning":"朝鮮戦争の際に米軍などからの注文が増え、日本経済が活気づいたこと。","note":"占領期の日本が復興へ向かう追い風になった出来事。","example":"朝鮮戦争と特需によって、日本の景気は急速に回復した。"},{"term":"三種の神器と3C","reading":"さんしゅのじんぎとすりーしー","meaning":"高度成長期に憧れの品とされた電化製品や、カラーテレビ・クーラー・自動車の総称。","note":"豊かさの象徴として、生活の変化を表す言葉。","example":"三種の神器と3Cは、時代ごとに人々が憧れた品物を表す言葉だ。"},{"term":"公害問題","reading":"こうがいもんだい","meaning":"工場排水や排煙などが健康被害や環境破壊を引き起こした問題。水俣病などが知られる。","note":"成長の影の部分として、公害対策基本法などの対応を促した。","example":"公害問題の深刻化を受けて、公害対策が進められた。"},{"term":"石油危機（オイルショック）","reading":"せきゆきき（おいるしょっく）","meaning":"1973年などに石油価格が急騰し、物価上昇や混乱を招いた出来事。","note":"高度経済成長が終わるきっかけとなり、省エネが進んだ。","example":"石油危機（オイルショック）で、物価が大きく上がった。"},{"term":"日米安全保障条約","reading":"にちべいあんぜんほしょうじょうやく","meaning":"日本とアメリカの軍事的な協力関係を定めた条約。平和条約と同時に結ばれた。","note":"戦後日本の外交・安全保障の軸となった仕組み。","example":"日米安全保障条約のもとで、日本はアメリカと協力関係を続けた。"},{"term":"所得倍増計画","reading":"しょとくばいぞうけいかく","meaning":"池田勇人内閣が掲げた、国民の所得を10年で2倍にすることを目指した政策。","note":"高度経済成長を進める目標となった。","example":"所得倍増計画のもとで、日本の経済成長は加速した。"},{"term":"四大公害病","reading":"よんだいこうがいびょう","meaning":"水俣病など、高度経済成長期に深刻化した代表的な公害病の総称。","note":"工場排水などが原因となり、裁判も起きた。","example":"四大公害病は、公害対策の必要性を社会に知らせた。"},{"term":"沖縄返還","reading":"おきなわへんかん","meaning":"1972年に、戦後アメリカの施政下にあった沖縄が日本へ返還されたこと。","note":"佐藤栄作内閣の時代に実現した。","example":"沖縄返還によって、沖縄は日本の施政下に戻った。"},{"term":"日中国交正常化","reading":"にっちゅうこっこうせいじょうか","meaning":"1972年に日本と中国が国交を回復したこと。","note":"田中角栄首相の訪中によって実現した。","example":"日中国交正常化の後、両国の交流は大きく広がった。"},{"term":"東海道新幹線","reading":"とうかいどうしんかんせん","meaning":"1964年に東京と新大阪の間で開業した高速鉄道。","note":"東京オリンピックに合わせて開業した。","example":"東海道新幹線の開業で、東京と大阪の移動は速くなった。"},{"term":"大阪万博","reading":"おおさかばんぱく","meaning":"1970年に大阪で開かれた日本万国博覧会。","note":"高度経済成長を象徴する国際行事となった。","example":"大阪万博には、国内外から多くの人が訪れた。"},{"term":"公害対策基本法","reading":"こうがいたいさくきほんほう","meaning":"1967年に制定された、公害対策の基本を定めた法律。","note":"深刻化する公害への国の対応を示した。","example":"公害対策基本法の制定で、公害への取り組みが進んだ。"}]}]},{"subject":"世界史","topics":[{"topic":"古代文明の出現","cards":[{"term":"農耕の始まり","reading":"のうこうのはじまり","meaning":"西アジアなどで植物の栽培と動物の飼育が始まり、食料生産が可能になった変化。","note":"定住生活と人口増加を招き、文明が生まれる前提になった。","example":"農耕の始まりによって、人々は食料を自分で作り出す生活へ移っていった。"},{"term":"メソポタミア文明","reading":"めそぽたみあぶんめい","meaning":"ティグリス・ユーフラテス川の間で栄えた文明。楔形文字や法典で知られる。","note":"都市国家が争いながら発展した、最も古い文明の一つ。","example":"メソポタミア文明はティグリス川とユーフラテス川の流域で栄えた。"},{"term":"エジプト文明","reading":"えじぷとぶんめい","meaning":"ナイル川の定期的な氾濫を利用して栄えた文明。ピラミッドや神聖文字が残る。","note":"ファラオを中心とする統一国家が長く続いたことが特徴。","example":"エジプト文明ではナイル川の定期的な増水が農業を支えた。"},{"term":"インダス文明","reading":"いんだすぶんめい","meaning":"インダス川流域に計画的な都市が作られた文明。モヘンジョ＝ダロが代表的。","note":"排水設備を備えた都市設計の高さで知られる。","example":"インダス文明の都市には下水の設備まで整えられていた。"},{"term":"黄河文明と殷","reading":"こうがぶんめいといん","meaning":"黄河流域で生まれた中国最古級の文明と、甲骨文字を使った殷王朝。","note":"漢字のもとになる文字や青銅器文化が発達した。","example":"黄河文明と殷の時代には、青銅器や甲骨文字が使われた。"},{"term":"文明の共通点","reading":"ぶんめいのきょうつうてん","meaning":"大河の近くで農耕が進み、都市・文字・金属器・身分社会などが現れた点。","note":"各地の古代文明を比べるときの基本的な視点になる。","example":"文明の共通点として、大河の流域で農耕が発達したことが挙げられる。"},{"term":"ハンムラビ法典","reading":"はんむらびほうてん","meaning":"バビロニア王ハンムラビが定めた法典で、「目には目を」という同害復讐の原則で知られる。","note":"楔形文字で石柱に刻まれた古代メソポタミアの法として覚える。","example":"ハンムラビ法典は、古代メソポタミアの社会のきまりを示す史料である。"},{"term":"楔形文字","reading":"くさびがたもじ","meaning":"メソポタミアで使われた、くさび形の刻み目を組み合わせた文字。粘土板に記録された。","note":"シュメール人が使い始めたとされる文字で、ヒエログリフと区別する。","example":"楔形文字は粘土板に刻まれ、契約や法の記録に使われた。"},{"term":"ヒエログリフ","reading":"ひえろぐりふ","meaning":"古代エジプトで使われた象形文字。神聖文字とも呼ばれ、神殿や墓の壁などに刻まれた。","note":"エジプトの文字であり、メソポタミアの楔形文字とは別物である。","example":"ヒエログリフはピラミッドや神殿の壁に今も残っている。"},{"term":"モヘンジョ=ダロ","reading":"もへんじょだろ","meaning":"インダス文明を代表する計画都市の遺跡。碁盤目状の街路や大浴場の跡で知られる。","note":"インダス文明の都市といえばモヘンジョ=ダロとハラッパーが代表例である。","example":"モヘンジョ=ダロには整然とした街路と大浴場の跡が残る。"},{"term":"甲骨文字","reading":"こうこつもじ","meaning":"殷の時代に、亀の甲羅や獣の骨に占いの結果などを刻んだ漢字の祖型の文字。","note":"中国最古の漢字資料であり、黄河文明・殷と結びつけて覚える。","example":"甲骨文字によって、殷の王の名前や占いの内容が分かる。"},{"term":"ジッグラト","reading":"じっぐらと","meaning":"メソポタミアの都市に築かれた、日干し煉瓦を積み上げた聖塔。神殿として使われた。","note":"エジプトのピラミッドとは別の、メソポタミアの建造物である。","example":"ジッグラトは都市の中心にそびえる神殿の塔だった。"}]},{"topic":"古代ギリシャとローマ","cards":[{"term":"ポリス","reading":"ぽりす","meaning":"古代ギリシャの都市を中心とする独立した小さな国家の形。","note":"アテネやスパルタなど、それぞれ制度や文化が異なった。","example":"ポリスは城壁に囲まれた都市を中心とする小さな国家だった。"},{"term":"アテネの民主政","reading":"あてねのみんしゅせい","meaning":"成人男性市民が民会に参加して政治を決めたアテネの仕組み。","note":"女性や奴隷は除かれたが、民主政の起源として重要。","example":"アテネの民主政では、成人男性市民が民会で政治に参加した。"},{"term":"ペルシア戦争","reading":"ぺるしあせんそう","meaning":"ギリシャのポリス連合がアケメネス朝ペルシアの侵攻を退けた戦争。","note":"ポリスの結束を強めたが、その後の対立の背景にもなった。","example":"ペルシア戦争の勝利はギリシャのポリスに自信をもたらした。"},{"term":"アレクサンドロス大王","reading":"あれくさんどろすだいおう","meaning":"マケドニアの王としてペルシアを滅ぼし、インド西部まで遠征した人物。","note":"ヘレニズム文化が広がるきっかけを作った。","example":"アレクサンドロス大王は若くして広大な帝国を築き上げた。"},{"term":"ローマ帝国","reading":"ろーまていこく","meaning":"地中海世界を統一した大帝国。法や道路、都市施設を各地に広げた。","note":"共和政から帝政へ移り、長い支配の仕組みを残した。","example":"ローマ帝国は地中海を囲む広大な地域を支配した。"},{"term":"パクス・ロマーナ","reading":"ぱくす・ろまーな","meaning":"ローマの力によって地中海世界に平和が保たれたとされる時期。","note":"『ローマの平和』を意味し、交通や交易の発展と結びつく。","example":"パクス・ロマーナの時代、地中海世界の交易は安定して栄えた。"},{"term":"陶片追放","reading":"とうへんついほう","meaning":"アテネで、独裁者になるおそれのある人物を陶片に名前を書いて投票し、国外へ追放した制度。","note":"オストラシズムともいう。民主政を守るための制度として出題されやすい。","example":"陶片追放では、市民の投票によって有力者が10年間追放された。"},{"term":"スパルタ","reading":"すぱるた","meaning":"厳しい軍事訓練で知られるギリシャのポリス。アテネと並ぶ有力な都市国家だった。","note":"民主政のアテネと対比して、軍事中心のスパルタと覚える。","example":"スパルタの少年は幼いころから厳しい共同生活と訓練を受けた。"},{"term":"ソクラテス","reading":"そくらてす","meaning":"古代ギリシャの哲学者。問答を通じて無知の自覚を説き、プラトンの師としても知られる。","note":"ソクラテス、プラトン、アリストテレスの師弟の順序で覚える。","example":"ソクラテスは若者との問答を重ねて真理を探ろうとした。"},{"term":"ヘレニズム文化","reading":"へれにずむぶんか","meaning":"アレクサンドロス大王の遠征後に広がった、ギリシャ文化とオリエント文化が結びついた文化。","note":"ヘレニズムは時代や文化の名前であり、王の名前ではない。","example":"ヘレニズム文化のもとで、各地にギリシャ風の都市が築かれた。"},{"term":"コロッセウム","reading":"ころっせうむ","meaning":"ローマに築かれた巨大な円形闘技場。剣闘士の試合などが行われた。","note":"ローマ帝国の建築技術を示す代表的な遺跡として覚える。","example":"コロッセウムでは多くの観客が剣闘士の試合を見物した。"},{"term":"ローマ法","reading":"ろーまほう","meaning":"ローマで発達した法の体系。市民法や万民法を含み、後のヨーロッパの法に大きな影響を与えた。","note":"万民法はローマ法の一部であり、帝国全体に適用された法である。","example":"ローマ法は近代ヨーロッパの法律の土台の一つとなった。"}]},{"topic":"イスラーム世界の成立と拡大","cards":[{"term":"ムハンマド","reading":"むはんまど","meaning":"イスラーム教の預言者とされ、メッカからメディナへ移住して共同体を作った人物。","note":"622年のヒジュラがイスラーム暦の起点になった。","example":"ムハンマドはメッカの商人からイスラーム教の預言者となった。"},{"term":"コーランと六信五行","reading":"こーらんとろくしんごぎょう","meaning":"聖典コーランと、信じるべき事柄や実践すべき行いを示す教えの枠組み。","note":"イスラーム教徒の生活の基準として位置づけられる。","example":"コーランと六信五行は、ムスリムの信仰と実践の中心にある。"},{"term":"カリフ","reading":"かりふ","meaning":"預言者の後継者としてイスラーム共同体を率いた指導者の称号。","note":"政治と宗教の指導者を兼ねる存在として帝国を治めた。","example":"カリフはムハンマドの後継者として共同体を率いた。"},{"term":"ウマイヤ朝","reading":"うまいやちょう","meaning":"ダマスカスを都とし、イベリア半島まで勢力を広げたイスラーム王朝。","note":"急速な拡大の時期を担い、アラブ人の優位が特徴とされる。","example":"ウマイヤ朝の時代にイスラーム勢力はイベリア半島まで広がった。"},{"term":"アッバース朝","reading":"あっばーすちょう","meaning":"バグダードを都に、民族を越えたイスラーム帝国を築いた王朝。","note":"学問や交易が栄え、イスラーム文化の黄金期とされる。","example":"アッバース朝のバグダードは学問と交易の中心地となった。"},{"term":"拡大の背景","reading":"かくだいのはいけい","meaning":"交易路の掌握や周辺帝国の衰え、共同体のまとまりなどが重なった広がりの要因。","note":"短期間に広大な地域へ広がった理由を説明する視点。","example":"拡大の背景には、ビザンツ帝国とサーサーン朝の衰えもあった。"},{"term":"ヒジュラ","reading":"ひじゅら","meaning":"622年、ムハンマドがメッカからメディナへ移住した出来事。イスラーム暦の元年とされる。","note":"ヒジュラは移住そのものを指し、イスラーム共同体成立の転機である。","example":"ヒジュラの年がイスラーム暦の始まりとされた。"},{"term":"メッカ","reading":"めっか","meaning":"アラビア半島の都市で、イスラーム教最大の聖地。ムハンマドの生まれた地でもある。","note":"聖地メッカと、移住先のメディナを区別して覚える。","example":"世界中のムスリムはメッカの方向へ向かって礼拝する。"},{"term":"スンナ派","reading":"すんなは","meaning":"イスラーム教の多数派。ムハンマドの慣行（スンナ）を重んじ、共同体の合意でカリフを選ぶ立場をとる。","note":"多数派がスンナ派、少数派がシーア派という区別が基本である。","example":"現在のムスリムの多くはスンナ派に属している。"},{"term":"シーア派","reading":"しーあは","meaning":"イスラーム教の少数派。ムハンマドの血統に連なる指導者を重んじる立場をとる。","note":"イランで国教とされていることでも知られる派である。","example":"シーア派はムハンマドのいとこアリーとその子孫を重んじた。"},{"term":"バグダード","reading":"ばぐだーど","meaning":"アッバース朝の首都として建設された都市。学問や交易の中心として栄えた。","note":"ウマイヤ朝の首都ダマスカスと、アッバース朝のバグダードを区別する。","example":"バグダードには各地から学者や商人が集まった。"},{"term":"イブン=シーナー","reading":"いぶんしーなー","meaning":"イスラーム世界の医学者・哲学者。医学の著作はヨーロッパでも長く使われた。","note":"イスラーム世界で学問が栄えたことを示す人物として覚える。","example":"イブン=シーナーの医学書はヨーロッパの大学でも読まれた。"}]},{"topic":"南アジアと東南アジアの世界","cards":[{"term":"グプタ朝","reading":"ぐぷたちょう","meaning":"4〜6世紀に北インドを統一した王朝。サンスクリット文化が栄えた。","note":"ゼロの概念や古典文化の発展で知られる時期。","example":"グプタ朝の時代にインドの古典文化が花開いた。"},{"term":"ヒンドゥー教の形成","reading":"ひんどぅーきょうのけいせい","meaning":"バラモン教が民衆信仰と結びつき、カーストと結びついた宗教として整った過程。","note":"南アジア社会の土台となり、東南アジアへも伝わった。","example":"ヒンドゥー教の形成には、バラモン教と民間信仰の融合が関わった。"},{"term":"デリー＝スルタン朝","reading":"でりー＝するたんちょう","meaning":"13世紀初め、デリーを拠点に北インドを支配したイスラーム王朝の総称。","note":"インドにイスラーム政権が根づく転換点になった。","example":"デリー＝スルタン朝によって北インドにイスラーム政権が成立した。"},{"term":"シュリーヴィジャヤ","reading":"しゅりーゔぃじゃや","meaning":"スマトラ島を中心にマラッカ海峡の交易を押さえて栄えた港市国家。","note":"海の道の要衝を支配した東南アジアの代表例。","example":"シュリーヴィジャヤはマラッカ海峡の交易を押さえて栄えた。"},{"term":"アンコール朝","reading":"あんこーるちょう","meaning":"カンボジアでアンコール＝ワットなどを築いた王朝。","note":"灌漑を基盤に繁栄した内陸型国家の代表例。","example":"アンコール朝は巨大な寺院建築でその繁栄を今に伝える。"},{"term":"海の道と交易","reading":"うみのみちとこうえき","meaning":"インド洋や南シナ海を結ぶ海上交易路を通じた香辛料などの取引。","note":"東南アジアの国家形成と文化交流を促した仕組み。","example":"海の道と交易によって、インドの文化が東南アジアへ伝わった。"},{"term":"ヴァルナ","reading":"ゔぁるな","meaning":"古代インドで生まれた身分制度の枠組み。バラモン、クシャトリヤ、ヴァイシャ、シュードラの四つに分かれる。","note":"レポート頻出用語。四つのヴァルナの名前と順序まで押さえる。","example":"ヴァルナの最上位に位置づけられたのは司祭階級のバラモンだった。"},{"term":"カースト","reading":"かーすと","meaning":"インドでヴァルナをもとに細かく分かれた世襲的な身分・職業集団のしくみ。","note":"ヴァルナは大きな四区分、カーストはより細かい集団という違いに注意する。","example":"カーストによって人々の職業や結婚の相手は強く制限された。"},{"term":"アショーカ王","reading":"あしょーかおう","meaning":"マウリヤ朝の王。インドをほぼ統一し、仏教を保護して各地に石柱を建てた。","note":"マウリヤ朝と結びつく王であり、グプタ朝の王ではない。","example":"アショーカ王は戦いの反省から仏教に帰依したと伝えられる。"},{"term":"マウリヤ朝","reading":"まうりやちょう","meaning":"紀元前4世紀末に成立した、インド最初の統一的王朝。アショーカ王の時代に最大となった。","note":"インド最古の統一王朝であり、グプタ朝より前の王朝である。","example":"マウリヤ朝のもとでインドのほぼ全域が初めて統一された。"},{"term":"ボロブドゥール","reading":"ぼろぶどぅーる","meaning":"ジャワ島に築かれた大乗仏教の大寺院遺跡。シャイレンドラ朝の時代に建てられた。","note":"カンボジアのアンコール=ワットと並ぶ東南アジアの大遺跡である。","example":"ボロブドゥールの回廊には仏教の物語が彫刻で表されている。"},{"term":"アンコール=ワット","reading":"あんこーるわっと","meaning":"カンボジアのアンコール朝が築いた大寺院。当初はヒンドゥー教寺院として建てられた。","note":"アンコール朝の遺跡であり、ボロブドゥールとは国も宗教の出発点も異なる。","example":"アンコール=ワットは森の中から再発見された巨大な寺院である。"}]},{"topic":"中国の王朝","cards":[{"term":"始皇帝","reading":"しこうてい","meaning":"秦の王として中国を統一し、初めて皇帝の称号を用いた人物。","note":"郡県制や文字・度量衡の統一など中央集権を進めた。","example":"始皇帝は中国を統一し、文字や貨幣、度量衡を統一した。"},{"term":"漢","reading":"かん","meaning":"秦の後に中国を統一した王朝。前漢と後漢に分かれる。","note":"儒教の重視やシルクロード交易など、長期王朝の原型を作った。","example":"漢の時代にシルクロードを通じた東西交易が活発になった。"},{"term":"唐","reading":"とう","meaning":"隋の後に中国を統一し、東アジアに大きな影響を与えた王朝。","note":"律令制や長安の国際性が、日本の制度・文化にも影響した。","example":"唐の長安は各国の人々が集まる国際的な都だった。"},{"term":"科挙","reading":"かきょ","meaning":"試験で官僚を登用する制度。隋で始まり唐以降に整えられた。","note":"家柄より学識を問う仕組みとして中国政治の特徴になった。","example":"科挙に合格することが官僚になるための登竜門だった。"},{"term":"元","reading":"げん","meaning":"モンゴル系のフビライが建て、中国全土を支配した王朝。国号は大元。","note":"ユーラシア規模の交流の中で中国を治めた王朝。","example":"元はモンゴル系の王朝として中国全土を支配した。"},{"term":"清","reading":"しん","meaning":"満洲族が建て、中国を支配した最後の王朝。","note":"最大級の版図を持ったが、近代に欧米列強と向き合うことになった。","example":"清は中国の最後の王朝として約270年続いた。"},{"term":"郡県制","reading":"ぐんけんせい","meaning":"秦の始皇帝が採用した地方制度。全国を郡と県に分け、皇帝が任命した官吏に治めさせた。","note":"封建制と対になる用語で、中央集権のしくみとして覚える。","example":"郡県制によって、地方の役人は皇帝から任命されるようになった。"},{"term":"均田制","reading":"きんでんせい","meaning":"北魏から唐にかけて行われた土地制度。国家が農民に土地を分け与え、税や労役を課した。","note":"租庸調制や両税法など、唐の制度と一緒に整理すると覚えやすい。","example":"均田制のもとでは、農民は国家から土地を支給された。"},{"term":"冊封体制","reading":"さくほうたいせい","meaning":"中国の皇帝が周辺諸国の君主の地位を認め、相手は朝貢を行うことで成り立つ国際関係の秩序。","note":"朝貢とセットで覚える、東アジアの外交の枠組みである。","example":"周辺の国々は冊封体制のもとで中国と関係を結んだ。"},{"term":"朱子学","reading":"しゅしがく","meaning":"南宋の朱熹が大成した儒学。上下の秩序を重んじ、後の東アジア各地に広がった。","note":"科挙の基準ともなった学問であり、宋の時代に整えられた。","example":"朱子学は江戸時代の日本でも公式の学問とされた。"},{"term":"行省","reading":"こうしょう","meaning":"元が地方統治のために置いた行政機関。行中書省の略で、後の省の制度のもとになった。","note":"元はモンゴル系の王朝であり、行省はその地方制度である。","example":"元は全国を行省に分けて地方を治めた。"},{"term":"大運河","reading":"だいうんが","meaning":"隋の煬帝が整備した大運河。黄河と長江を結び、南北の物資輸送を大きく進めた。","note":"隋の事業であり、唐の繁栄を支えた交通路でもある。","example":"大運河を通って南の米が北の都へ運ばれた。"}]},{"topic":"モンゴル帝国とユーラシア","cards":[{"term":"チンギス＝ハン","reading":"ちんぎす＝はん","meaning":"モンゴル高原の諸部族を統一し、大帝国の基礎を築いた指導者。","note":"1206年の統一がモンゴル帝国拡大の出発点になった。","example":"チンギス＝ハンはモンゴルの遊牧民を統一した。"},{"term":"モンゴル帝国の拡大","reading":"もんごるていこくのかくだい","meaning":"騎馬軍団の機動力でユーラシア大陸の広い範囲を征服した動き。","note":"東西を結ぶ交通と交易が活発になる前提を作った。","example":"モンゴル帝国の拡大は騎馬軍団の機動力によって進んだ。"},{"term":"4ハン国","reading":"よんはんこく","meaning":"帝国が分かれて成立したキプチャクなど四つのハン国の総称。","note":"分裂後も緩やかにつながり、地域ごとに異なる道を歩んだ。","example":"4ハン国への分裂後も、各地のハン国はつながりを保った。"},{"term":"元（フビライ）","reading":"げん（ふびらい）","meaning":"チンギスの孫フビライが南宋を滅ぼし、中国を支配した政権。","note":"日本への遠征を行い、日本史の元寇と直接つながる。","example":"元（フビライ）は南宋を滅ぼして中国を統一した。"},{"term":"元の日本遠征","reading":"げんのにほんえんせい","meaning":"1274年と1281年に元が高麗軍などとともに日本へ攻めてきた出来事。","note":"モンゴルの拡大が東アジアの島国にまで及んだ例。","example":"元の日本遠征は二度にわたって行われ、いずれも失敗した。"},{"term":"ユーラシアの交流","reading":"ゆーらじあのこうりゅう","meaning":"モンゴルの支配下で駅伝制などが整い、人や物、技術が大陸を横断した動き。","note":"マルコ＝ポーロの旅行記などを通じヨーロッパにも伝わった。","example":"ユーラシアの交流によって、技術や文物が大陸を横断して伝わった。"},{"term":"駅伝制","reading":"えきでんせい","meaning":"モンゴル帝国が整えた交通・通信の制度。各地に駅を置き、人や物資、情報を速く運んだ。","note":"ジャムチとも呼ばれる。ユーラシア交流を支えた制度である。","example":"駅伝制のおかげで大陸を横断する旅がしやすくなった。"},{"term":"キプチャク=ハン国","reading":"きぷちゃくはんこく","meaning":"モンゴルの4ハン国の一つ。南ロシアを支配し、ロシアの諸侯に貢納を求めた。","note":"ロシアを支配したハン国といえばキプチャク=ハン国である。","example":"キプチャク=ハン国の支配はロシアに長い影響を残した。"},{"term":"イル=ハン国","reading":"いるはんこく","meaning":"モンゴルの4ハン国の一つ。西アジアを支配し、後にイスラーム教を国教とした。","note":"ペルシア（イラン）方面を治めたハン国として覚える。","example":"イル=ハン国ではイスラーム文化が取り入れられていった。"},{"term":"チャガタイ=ハン国","reading":"ちゃがたいはんこく","meaning":"モンゴルの4ハン国の一つ。中央アジアを支配した、チンギスの次男の名に由来する国。","note":"中央アジアのハン国であり、シルクロードの要地を含んだ。","example":"チャガタイ=ハン国は中央アジアの交易路を押さえた。"},{"term":"パクス=モンゴリカ","reading":"ぱくすもんごりか","meaning":"モンゴル帝国の支配によってユーラシアに広く平和と安定がもたらされた状態を指す言葉。","note":"ローマの平和を意味するパクス・ロマーナになぞらえた表現である。","example":"パクス=モンゴリカのもとで東西の商人の往来が活発になった。"},{"term":"マルコ=ポーロ","reading":"まるこぽーろ","meaning":"ヴェネツィアの商人。元に仕えたとされ、『世界の記述』で東方の様子をヨーロッパに伝えた。","note":"『世界の記述』（東方見聞録）の著者として覚える。","example":"マルコ=ポーロの記録はヨーロッパ人の東方への関心を高めた。"}]},{"topic":"ルネサンスと大航海時代","cards":[{"term":"ルネサンス","reading":"るねさんす","meaning":"古代ギリシャ・ローマの文化を見直し、人間らしい生き方を重んじた文化運動。","note":"イタリアから広がり、芸術や学問の新しい流れを作った。","example":"ルネサンスの芸術家たちは遠近法を使って絵画に奥行きを持たせた。"},{"term":"レオナルド・ダ・ヴィンチ","reading":"れおなるど・だ・ゔぃんち","meaning":"絵画だけでなく解剖や機械の研究も行ったルネサンスを代表する人物。","note":"『モナ＝リザ』などで知られる万能の天才とされる。","example":"レオナルド・ダ・ヴィンチは絵画だけでなく科学の研究にも優れた。"},{"term":"宗教改革","reading":"しゅうきょうかいかく","meaning":"カトリック教会のあり方を批判し、プロテスタント諸派が生まれた16世紀の運動。","note":"ルターの主張から広がり、ヨーロッパの政治にも影響した。","example":"宗教改革はヨーロッパのキリスト教世界を大きく二つに分けた。"},{"term":"コロンブス","reading":"ころんぶす","meaning":"1492年に大西洋を渡り、アメリカ大陸の島々に到達した航海者。","note":"ヨーロッパとアメリカ大陸の本格的な接触の始まりとされる。","example":"コロンブスは大西洋を渡ってアメリカ大陸に到達した。"},{"term":"マゼラン","reading":"まぜらん","meaning":"世界一周航海を始めた航海者。本人は途中で亡くなったが船隊が一周を果たした。","note":"地球規模の航海が可能になったことを示した航海。","example":"マゼランの艦隊は人類初の世界一周航海を成し遂げた。"},{"term":"バスコ・ダ・ガマ","reading":"ばすこ・だ・がま","meaning":"アフリカ南端を回ってインドへ至る航路を開いたポルトガルの航海者。","note":"香辛料貿易の主導権をヨーロッパ側が握る転機になった。","example":"バスコ・ダ・ガマは喜望峰を回ってインドへ到達した。"},{"term":"人文主義","reading":"じんぶんしゅぎ","meaning":"ルネサンスの基調となった考え方。古代ギリシャ・ローマの古典を学び、人間らしさを重んじた。","note":"ヒューマニズムともいう。神中心から人間中心への転換が要点である。","example":"人文主義の学者たちは古典の研究を通じて人間を見つめ直した。"},{"term":"メディチ家","reading":"めでぃちけ","meaning":"フィレンツェの富豪で、銀行業で栄え、ルネサンスの芸術家たちを保護した家柄。","note":"芸術家のパトロン（保護者）として出題されやすい。","example":"メディチ家の保護を受けて多くの芸術家が活躍した。"},{"term":"活版印刷術","reading":"かっぱんいんさつじゅつ","meaning":"グーテンベルクが実用化した印刷技術。書物が大量に作れるようになり、知識の普及を早めた。","note":"宗教改革の広がりにも印刷術が役立った点が重要である。","example":"活版印刷術によって聖書やパンフレットが広く出回った。"},{"term":"免罪符","reading":"めんざいふ","meaning":"カトリック教会が売り出した、罪のゆるしを約束するとされた証書。ルターが批判した対象である。","note":"インドゥルゲンティアともいう。宗教改革のきっかけと結びつける。","example":"免罪符の販売は教会への批判を強める原因となった。"},{"term":"トルデシリャス条約","reading":"とるでしりゃすじょうやく","meaning":"1494年、スペインとポルトガルが大西洋上の境界線を定め、海外領土の取り分を決めた条約。","note":"二国が世界を分け合おうとした条約として覚える。","example":"トルデシリャス条約で両国の植民地の範囲が分けられた。"},{"term":"ポトシ銀山","reading":"ぽとしぎんざん","meaning":"南米ボリビアのポトシで発見された大銀山。産出された銀は世界中に流れ込んだ。","note":"銀の流入がヨーロッパの価格革命の一因となった。","example":"ポトシ銀山の銀はヨーロッパやアジアへ運ばれた。"}]},{"topic":"主権国家体制と宗教改革","cards":[{"term":"ルターの宗教改革","reading":"るたーのしゅうきょうかいかく","meaning":"ルターが免罪符販売を批判し、聖書中心の信仰を訴えた改革の始まり。","note":"95か条の論題がきっかけとなり、プロテスタントが生まれた。","example":"ルターの宗教改革は免罪符への批判から始まった。"},{"term":"カルヴァンと予定説","reading":"かるゔぁんとよていせつ","meaning":"救われるかどうかはあらかじめ決まっているとするカルヴァンの教え。","note":"勤勉な職業生活を重んじる倫理と結びついて広がった。","example":"カルヴァンと予定説の教えは勤勉な生活を重んじる人々に広がった。"},{"term":"イギリス国教会","reading":"いぎりすこっきょうかい","meaning":"国王を首長としてローマ教皇から離れたイギリスの教会組織。","note":"ヘンリ8世の離婚問題を契機に成立した国教会。","example":"イギリス国教会は国王を長とする教会として成立した。"},{"term":"対抗宗教改革","reading":"たいこうしゅうきょうかいかく","meaning":"カトリック側が自己改革とプロテスタントへの反撃を進めた動き。","note":"トリエント公会議やイエズス会の活動が代表例。","example":"対抗宗教改革ではカトリック教会の立て直しが図られた。"},{"term":"三十年戦争","reading":"さんじゅうねんせんそう","meaning":"神聖ローマ帝国を舞台に宗教対立と諸国の利害が絡んだ大規模な戦争。","note":"ヨーロッパ秩序を大きく変え、主権国家体制へつながった。","example":"三十年戦争はドイツを主戦場として長く続いた。"},{"term":"ウェストファリア条約","reading":"うぇすとふぁりあじょうやく","meaning":"三十年戦争を終わらせ、各国の主権と領土を認め合った1648年の講和。","note":"近代的な国際秩序の出発点として扱われる。","example":"ウェストファリア条約で各国の主権が互いに認められた。"},{"term":"九十五か条の論題","reading":"きゅうじゅうごかじょうのろんたい","meaning":"1517年、ルターが免罪符販売を批判して発表した文書。宗教改革の始まりとされる。","note":"年号1517年とルターの名前をセットで覚える。","example":"九十五か条の論題は印刷されて各地に広まった。"},{"term":"アウクスブルク和議","reading":"あうくすぶるくわぎ","meaning":"1555年、ルター派が公認され、領邦君主に宗教の選択権が認められた講和。","note":"ルター派の公認といえばこの和議である。","example":"アウクスブルク和議でルター派は正式に認められた。"},{"term":"ナントの勅令","reading":"なんとのちょくれい","meaning":"1598年、フランス王アンリ4世が出した勅令。ユグノー（カルヴァン派）に信仰の自由を認めた。","note":"フランスの宗教対立を収めた勅令として覚える。","example":"ナントの勅令によってフランスの宗教戦争は終わりに近づいた。"},{"term":"イエズス会","reading":"いえずすかい","meaning":"対抗宗教改革の担い手となったカトリックの修道会。海外布教や教育に力を入れた。","note":"ザビエルが属し、日本にも布教に来た会である。","example":"イエズス会の宣教師はアジア各地で布教活動を行った。"},{"term":"トリエント公会議","reading":"とりえんとこうかいぎ","meaning":"カトリック教会が教義を再確認し、改革を進めるために開いた会議。対抗宗教改革の中心となった。","note":"教会の綱紀粛正と教義の明確化が目的だった。","example":"トリエント公会議でカトリックの教えが改めて示された。"},{"term":"絶対王政","reading":"ぜったいおうせい","meaning":"王が強い権力を集中させて治める政治のしくみ。主権国家の時代にヨーロッパ各地で見られた。","note":"フランスのルイ14世が代表例としてよく挙げられる。","example":"絶対王政のもとでは王の命令が国全体を動かした。"}]},{"topic":"産業革命","cards":[{"term":"蒸気機関","reading":"じょうききかん","meaning":"蒸気の力で機械を動かす動力装置。ワットによる改良で広く使われるようになった。","note":"工場や交通機関を変え、産業革命の象徴となった技術。","example":"蒸気機関は工場だけでなく機関車や蒸気船の動力にもなった。"},{"term":"工場制機械工業","reading":"こうじょうせいきかいこうぎょう","meaning":"工場に労働者を集め、機械で大量生産する仕組み。","note":"手工業や家内工業に代わる生産の中心になった。","example":"工場制機械工業では多くの労働者が一つの場所で働いた。"},{"term":"綿工業","reading":"めんこうぎょう","meaning":"綿織物の生産から機械化が進んだ、産業革命の先頭を切った産業。","note":"紡績と織布の発明が連鎖し、他の産業へ広がった。","example":"綿工業は産業革命の先頭を切って機械化が進んだ分野だった。"},{"term":"資本主義","reading":"しほんしゅぎ","meaning":"生産手段を持つ資本家が労働者を雇い、利潤を求めて生産する経済の仕組み。","note":"産業革命とともに確立し、社会問題も生んだ体制。","example":"資本主義のもとで企業同士の競争が経済を動かしていく。"},{"term":"労働問題","reading":"ろうどうもんだい","meaning":"長時間労働や低賃金、児童労働など工場労働者の厳しい条件をめぐる問題。","note":"労働組合や社会主義思想が広がる背景になった。","example":"労働問題として、低賃金や長時間労働が社会の課題となった。"},{"term":"都市化","reading":"としか","meaning":"産業の発展に伴い、人口が農村から都市へ集中する現象。","note":"スラムの形成や衛生問題など新しい社会課題を生んだ。","example":"都市化が進み、工場のある町に人口が集中した。"},{"term":"ワット","reading":"わっと","meaning":"蒸気機関を改良したイギリスの技術者。効率のよい蒸気機関が工場や交通機関に広がった。","note":"蒸気機関の発明者ではなく改良者である点に注意する。","example":"ワットの蒸気機関は工場の動力として広く使われた。"},{"term":"紡績機","reading":"ぼうせきき","meaning":"糸を紡ぐ作業を機械化した機械。綿工業の生産量を大きく高め、産業革命を進めた。","note":"織機とともに綿工業の機械化を示す用語である。","example":"紡績機の登場で綿糸が大量に作れるようになった。"},{"term":"囲い込み","reading":"かこいこみ","meaning":"イギリスで共有地などを囲って私有地化した動き。農業の効率化が進む一方、農民が都市へ流れた。","note":"エンクロージャーともいう。産業革命の労働力供給と結びつく。","example":"囲い込みで土地を失った農民の多くが都市へ移った。"},{"term":"ラダイト運動","reading":"らだいとうんどう","meaning":"産業革命期のイギリスで、失業を恐れた労働者が機械を打ち壊した運動。","note":"機械打ち壊し運動であり、指導者の名に由来すると伝えられる。","example":"ラダイト運動では怒った労働者が工場の機械を壊した。"},{"term":"チャーティスト運動","reading":"ちゃーてぃすとうんどう","meaning":"19世紀のイギリスで、労働者が人民憲章を掲げて普通選挙などを求めた運動。","note":"選挙権の拡大を求める政治運動であり、機械打ち壊しとは異なる。","example":"チャーティスト運動は労働者の政治参加を求める声を高めた。"},{"term":"社会主義","reading":"しゃかいしゅぎ","meaning":"生産手段を社会全体で所有し、平等な社会を目指す考え方。産業革命後の労働問題を背景に広がった。","note":"マルクスが科学的社会主義を唱えたことと結びつけて覚える。","example":"社会主義の思想は労働者の生活改善を求める運動に影響した。"}]},{"topic":"フランス革命","cards":[{"term":"旧体制（アンシャン・レジーム）","reading":"きゅうたいせい（あんしゃん・れじーむ）","meaning":"革命前のフランスで、聖職者と貴族が特権を持った身分秩序。","note":"第三身分の不満が高まり、革命の標的となった体制。","example":"旧体制（アンシャン・レジーム）のもとで第三身分への税の負担は重かった。"},{"term":"三部会","reading":"さんぶかい","meaning":"聖職者・貴族・平民の三身分からなる議会。1789年に久しぶりに召集された。","note":"採決方法をめぐる対立が国民議会の結成につながった。","example":"三部会の表決方法をめぐる対立が革命の引き金となった。"},{"term":"バスティーユ襲撃","reading":"ばすてぃーゆしゅうげき","meaning":"1789年7月14日、パリ民衆が王権の象徴とされた牢獄を襲った事件。","note":"フランス革命の始まりを象徴する出来事とされる。","example":"バスティーユ襲撃の知らせはフランス全土に広がった。"},{"term":"人権宣言","reading":"じんけんせんげん","meaning":"自由・平等・国民主権などをうたった1789年の宣言。正式名は人間と市民の権利の宣言。","note":"近代民主主義の原則を示し、後の憲法に影響を与えた。","example":"人権宣言は自由と平等の理念を世界に示した。"},{"term":"ロベスピエール","reading":"ろべすぴえーる","meaning":"革命政府を率い、恐怖政治を行ったジャコバン派の指導者。","note":"テルミドールの反動で失脚し、革命の急進期が終わった。","example":"ロベスピエールは公安委員会を率いて革命を指導した。"},{"term":"ナポレオン","reading":"なぽれおん","meaning":"革命の混乱を収めて権力を握り、皇帝となった軍人・政治家。","note":"ナポレオン法典を残し、ヨーロッパ各地へ革命の理念を広げた。","example":"ナポレオンはヨーロッパ各地を転戦して支配を広げた。"},{"term":"啓蒙思想","reading":"けいもうしそう","meaning":"理性によって社会や政治のあり方を見直そうとする18世紀の思想。人権や民主主義の考え方を広めた。","note":"モンテスキューやルソーなどの思想家と結びつけて覚える。","example":"啓蒙思想はフランス革命の思想的な支えとなった。"},{"term":"モンテスキュー","reading":"もんてすきゅー","meaning":"フランスの啓蒙思想家。『法の精神』で三権分立を説いた。","note":"三権分立といえばモンテスキュー、人民主権といえばルソーと区別する。","example":"モンテスキューは権力を分けることで自由が守られると考えた。"},{"term":"ルソー","reading":"るそー","meaning":"フランスの啓蒙思想家。『社会契約論』で人民主権を説き、革命に影響を与えた。","note":"人民主権と一般意思がキーワードである。","example":"ルソーの考え方は人権宣言の内容にも影響を与えた。"},{"term":"恐怖政治","reading":"きょうふせいじ","meaning":"ロベスピエールらが主導し、反革命とみなした人々を次々に処刑した革命期の政治。","note":"1793年から94年にかけての時期であり、革命の混乱を示す。","example":"恐怖政治のもとで多くの人々がギロチンで処刑された。"},{"term":"ナポレオン法典","reading":"なぽれおんほうてん","meaning":"ナポレオンが制定した法典。法の前の平等や私有財産の保護などを定めた。","note":"革命の成果を法としてまとめたものとして位置づける。","example":"ナポレオン法典はヨーロッパ各地の法律に影響を与えた。"},{"term":"ウィーン会議","reading":"うぃーんかいぎ","meaning":"ナポレオン戦争後にヨーロッパの秩序を再建するために開かれた国際会議。1814年から15年にかけて行われた。","note":"ウィーン体制の出発点であり、正統主義が原則とされた。","example":"ウィーン会議では革命前の秩序を取り戻すことが目指された。"}]},{"topic":"世界市場の形成と植民地化","cards":[{"term":"産業資本主義","reading":"さんぎょうしほんしゅぎ","meaning":"工場生産を担う産業資本が中心となった19世紀の資本主義の段階。","note":"自由貿易を求める動きと結びつき、世界市場が広がった。","example":"産業資本主義の発展は列強の海外進出を加速させた。"},{"term":"インド大反乱とイギリス領インド","reading":"いんどだいはんらんといぎりすりょういんど","meaning":"1857年の反乱を機に東インド会社が解散し、イギリスが直接支配した体制。","note":"ムガル帝国が正式に終わり、植民地支配が強まった。","example":"インド大反乱とイギリス領インドの成立は、インド支配の転換点となった。"},{"term":"アヘン戦争","reading":"あへんせんそう","meaning":"アヘン貿易をめぐりイギリスと清が戦った戦争。南京条約で香港などが割譲された。","note":"中国が欧米列強の圧力にさらされる転機になった。","example":"アヘン戦争の敗北は清の弱さを世界に知らせることになった。"},{"term":"オスマン帝国の改革","reading":"おすまんていこくの改革","meaning":"タンジマートなど、西欧を手本に軍制や法制度を改めようとした改革。","note":"帝国の衰退を食い止める試みだったが、列強の干渉も受けた。","example":"オスマン帝国の改革は西洋の制度を取り入れて進められた。"},{"term":"アフリカ分割","reading":"あふりかぶんかつ","meaning":"19世紀末、ヨーロッパ列強がアフリカ大陸を植民地として分け合った動き。","note":"ベルリン会議を経て短期間に進み、現在の国境問題の背景にもなった。","example":"アフリカ分割によって大陸のほとんどが列強の植民地となった。"},{"term":"民族運動の始まり","reading":"みんぞくうんどうのはじまり","meaning":"植民地支配に対して独立や権利を求める運動がアジア・アフリカで芽生えた動き。","note":"インド国民会議の結成などが初期の代表例。","example":"民族運動の始まりは、植民地支配への抵抗の広がりを示した。"},{"term":"南京条約","reading":"なんきんじょうやく","meaning":"1842年、アヘン戦争の結果として清とイギリスが結んだ条約。香港の割譲や開港を定めた。","note":"アヘン戦争の講和条約であり、中国の半植民地化の始まりとされる。","example":"南京条約で清は香港をイギリスに譲ることになった。"},{"term":"太平天国の乱","reading":"たいへいてんごくのらん","meaning":"19世紀半ば、洪秀全が清で起こした大規模な反乱。一時は南京を都とした。","note":"アヘン戦争後の清の混乱を示す出来事として覚える。","example":"太平天国の乱は清の国力を大きく弱らせた。"},{"term":"インド帝国","reading":"いんどていこく","meaning":"1877年、イギリス女王がインド皇帝を兼ねることで成立した、インドを直接支配する体制。","note":"インド大反乱の後に東インド会社による統治が終わり、直接統治となった。","example":"インド帝国の成立でインドはイギリスの直接支配下に入った。"},{"term":"スエズ運河","reading":"すえずうんが","meaning":"地中海と紅海を結ぶ運河。1869年に開通し、ヨーロッパとアジアを結ぶ航路を短くした。","note":"エジプトにあり、帝国主義時代の争奪の対象にもなった。","example":"スエズ運河の開通でアジアへの航海は大幅に短縮された。"},{"term":"ベルリン会議","reading":"べるりんかいぎ","meaning":"1884年から85年にかけて開かれ、ヨーロッパ列強がアフリカ分割の原則を話し合った会議。","note":"アフリカ分割の画期となった会議として覚える。","example":"ベルリン会議の後、アフリカの分割は急速に進んだ。"},{"term":"青年トルコ革命","reading":"せいねんとるこかくめい","meaning":"1908年、オスマン帝国で青年トルコ党が起こした革命。立憲政治の復活を目指した。","note":"オスマン帝国の近代化の試みの一つとして位置づける。","example":"青年トルコ革命によって憲法政治が復活した。"}]},{"topic":"第一次世界大戦","cards":[{"term":"三国同盟と三国協商","reading":"さんごくどうめいとさんごくきょうしょう","meaning":"ドイツ中心の同盟と英仏露の協商が対立した、開戦前の国際関係の枠組み。","note":"列強の対立が大戦へ拡大する土台になった。","example":"三国同盟と三国協商の対立がヨーロッパの緊張を高めた。"},{"term":"サラエボ事件","reading":"さらえぼじけん","meaning":"1914年、オーストリア皇位継承者が暗殺された事件。","note":"第一次世界大戦が始まる直接のきっかけになった。","example":"サラエボ事件は第一次世界大戦の引き金となった。"},{"term":"総力戦","reading":"そうりょくせん","meaning":"国民や経済全体を戦争に動員し、戦線と銃後が一体となった戦争の形。","note":"第一次世界大戦で本格化し、被害の規模を大きくした。","example":"総力戦では女性も工場で働き、戦争を支えた。"},{"term":"ヴェルサイユ条約","reading":"ゔぇるさいゆじょうやく","meaning":"第一次世界大戦後に連合国とドイツの間で結ばれた講和条約。","note":"ドイツに重い賠償などを課し、後の不満の種にもなった。","example":"ヴェルサイユ条約でドイツは巨額の賠償金を課された。"},{"term":"国際連盟","reading":"こくさいれんめい","meaning":"第一次世界大戦後に作られた、平和維持を目指す初の国際機関。","note":"アメリカが不参加だったことなどが限界として指摘される。","example":"国際連盟は平和を守るための初めての国際機関だった。"},{"term":"ロシア革命","reading":"ろしあかくめい","meaning":"1917年に帝政が倒れ、ソヴィエト政権が生まれた革命。","note":"大戦中の社会不安を背景に起こり、世界に大きな影響を与えた。","example":"ロシア革命によって帝政ロシアは崩壊した。"},{"term":"塹壕戦","reading":"ざんごうせん","meaning":"第一次世界大戦で、兵士が塹壕にこもって対峙し、戦線が動かなくなった戦い方。","note":"西部戦線の膠着を示す言葉であり、総力戦の様子と結びつく。","example":"塹壕戦では兵士たちは泥と寒さの中で長く戦い続けた。"},{"term":"十四か条","reading":"じゅうよんかじょう","meaning":"第一次世界大戦末期にアメリカ大統領ウィルソンが示した平和原則。国際連盟の設立も含まれていた。","note":"ウィルソンの名と国際連盟の提案をセットで覚える。","example":"十四か条は戦後の講和会議の土台の一つとなった。"},{"term":"レーニン","reading":"れーにん","meaning":"ロシア革命の指導者。ボリシェヴィキを率い、社会主義政権を樹立した。","note":"十月革命と結びつく人物であり、ソ連成立へつながる。","example":"レーニンは平和とパンを掲げて労働者の支持を集めた。"},{"term":"十月革命","reading":"じゅうがつかくめい","meaning":"1917年、レーニンらボリシェヴィキが臨時政府を倒したロシアの革命。社会主義政権が成立した。","note":"二月革命と区別し、十月革命で社会主義政権が生まれたと覚える。","example":"十月革命によって世界初の社会主義政権が誕生した。"},{"term":"パリ講和会議","reading":"ぱりこうわかいぎ","meaning":"第一次世界大戦後にパリで開かれた講和会議。ヴェルサイユ条約などが結ばれた。","note":"戦勝国中心に進められ、敗戦国の意見は反映されにくかった。","example":"パリ講和会議で戦後のヨーロッパの秩序が話し合われた。"},{"term":"民族自決","reading":"みんぞくじけつ","meaning":"各民族が自らの政治的なあり方を自分たちで決めるべきだという原則。十四か条にも含まれた。","note":"第一次世界大戦後に東ヨーロッパの独立を促した考え方である。","example":"民族自決の原則のもとで新しい国々が次々に独立した。"}]},{"topic":"第二次世界大戦","cards":[{"term":"ファシズムの台頭","reading":"ふぁしずむのたいとう","meaning":"イタリアのムッソリーニらが率いた全体主義的な運動や体制の広がり。","note":"恐慌後の不安を背景にし、ドイツのナチズムとも並べられる。","example":"ファシズムの台頭は世界恐慌による社会不安と結びついていた。"},{"term":"第二次世界大戦の開始","reading":"だいにじせかいたいせんのかいし","meaning":"1939年、ドイツのポーランド侵攻をきっかけに始まった世界規模の戦争。","note":"イギリスとフランスの宣戦布告でヨーロッパ全体へ広がった。","example":"第二次世界大戦の開始はドイツのポーランド侵攻だった。"},{"term":"日中戦争と太平洋戦争","reading":"にっちゅうせんそうとたいへいようせんそう","meaning":"1937年からの中国との戦争と、1941年からの対米英戦争を指す日本の戦争。","note":"アジア・太平洋地域に大きな被害をもたらした流れ。","example":"日中戦争と太平洋戦争によって日本の戦線は大きく広がった。"},{"term":"ミッドウェー海戦とスターリングラード","reading":"みっどうぇーかいせんとすたーりんぐらーど","meaning":"太平洋と独ソ戦で連合国側が反攻へ転じるきっかけとなった二つの戦い。","note":"1942〜43年ごろの大戦の転換点として並べて扱われる。","example":"ミッドウェー海戦とスターリングラードの戦いは戦争の転換点となった。"},{"term":"連合国の戦後構想","reading":"れんごうこくのせんごこうそう","meaning":"大西洋憲章やヤルタ会談などで話し合われた、戦後の国際秩序の設計。","note":"国際連合の設立や冷戦の始まりにもつながった構想。","example":"連合国の戦後構想は大戦のさなかから話し合われていた。"},{"term":"戦争の終結","reading":"せんそうのしゅうけつ","meaning":"1945年にドイツと日本が降伏し、第二次世界大戦が終わったこと。","note":"その後の占領や国際秩序の再編が始まる区切りになった。","example":"戦争の終結後、世界は米ソ二大国の対立する時代に入った。"},{"term":"ヒトラー","reading":"ひとらー","meaning":"ナチ党の指導者でドイツの独裁者。ポーランド侵攻で第二次世界大戦を引き起こした。","note":"ナチス=ドイツの指導者であり、ユダヤ人迫害とも結びつく。","example":"ヒトラーは1933年にドイツの首相となった。"},{"term":"ムッソリーニ","reading":"むっそりーに","meaning":"イタリアのファシスト党の指導者。1922年に政権を握り独裁体制を築いた。","note":"ファシズムの本家はイタリアであり、ムッソリーニが率いた。","example":"ムッソリーニはローマ進軍の後に首相となった。"},{"term":"世界恐慌","reading":"せかいきょうこう","meaning":"1929年、アメリカの株価暴落から始まった世界的な経済危機。失業者が急増した。","note":"第二次世界大戦への道の背景として重要な出来事である。","example":"世界恐慌で世界中の工場が止まり、失業者があふれた。"},{"term":"ニューディール政策","reading":"にゅーでぃーるせいさく","meaning":"アメリカ大統領ローズヴェルトが恐慌対策として行った政策。公共事業などで雇用を増やした。","note":"恐慌対策といえばニューディール政策とローズヴェルトである。","example":"ニューディール政策ではダムや道路の建設が進められた。"},{"term":"日独伊三国同盟","reading":"にちどくいさんごくどうめい","meaning":"1940年、日本・ドイツ・イタリアが結んだ軍事同盟。枢軸国の結びつきを強めた。","note":"三国協商とは別物であり、第二次世界大戦期の同盟である。","example":"日独伊三国同盟によって枢軸国の陣営が固まった。"},{"term":"ヤルタ会談","reading":"やるたかいだん","meaning":"1945年、米・英・ソの首脳が戦後処理を話し合った会談。ソ連の対日参戦も密約された。","note":"戦後秩序の構想を話し合った会談の一つとして覚える。","example":"ヤルタ会談ではドイツの戦後処理などが決められた。"}]},{"topic":"冷戦とその終結","cards":[{"term":"冷戦","reading":"れいせん","meaning":"アメリカとソ連が直接戦わずに対立し続けた第二次世界大戦後の状態。","note":"核兵器の存在が、正面衝突を避けさせる背景になった。","example":"冷戦では米ソが直接戦うことは避けられ続けた。"},{"term":"NATOとワルシャワ条約機構","reading":"なとーとわるしゃわじょうやくきこう","meaning":"西側と東側がそれぞれ作った軍事同盟の組織。","note":"冷戦下のヨーロッパを二分する対立の枠組みとなった。","example":"NATOとワルシャワ条約機構は東西両陣営の軍事的な柱だった。"},{"term":"朝鮮戦争","reading":"ちょうせんせんそう","meaning":"1950〜53年、南北に分かれた朝鮮半島で起きた戦争。米ソ中などが関与した。","note":"冷戦がアジアで熱い戦争になった代表例で、休戦のまま続く。","example":"朝鮮戦争によって朝鮮半島の分断は固定化した。"},{"term":"キューバ危機","reading":"きゅーばきき","meaning":"1962年、キューバへのソ連の核ミサイル配備をめぐり米ソが緊迫した事件。","note":"核戦争寸前とされ、その後の緊張緩和のきっかけにもなった。","example":"キューバ危機では核戦争の一歩手前まで緊張が高まった。"},{"term":"ベトナム戦争","reading":"べとなむせんそう","meaning":"南北ベトナムの対立にアメリカが深く介入した戦争。1975年に北側が勝利した。","note":"アメリカ社会に大きな傷を残し、冷戦の限界も示した。","example":"ベトナム戦争はアメリカ社会にも大きな傷を残した。"},{"term":"冷戦の終結","reading":"れいせんのしゅうけつ","meaning":"1989年のマルタ会談などで米ソ対立の終わりが確認され、ソ連も解体した流れ。","note":"東西対立の時代が終わり、国際秩序が組み替わった転換点。","example":"冷戦の終結によって世界の政治地図は大きく書き換わった。"},{"term":"マーシャル=プラン","reading":"まーしゃるぷらん","meaning":"アメリカが西ヨーロッパの復興を支援した経済援助計画。冷戦下の西側結束を強めた。","note":"アメリカ国務長官マーシャルの名に由来する援助計画である。","example":"マーシャル=プランの援助で西ヨーロッパの復興が進んだ。"},{"term":"トルーマン=ドクトリン","reading":"とるーまんどくとりん","meaning":"アメリカ大統領トルーマンが宣言した、共産主義の拡大を防ぐ方針。冷戦政策の出発点とされる。","note":"封じ込め政策の表明として覚える。","example":"トルーマン=ドクトリンは冷戦におけるアメリカの姿勢を示した。"},{"term":"ベルリン封鎖","reading":"べるりんふうさ","meaning":"1948年、ソ連が西ベルリンへの陸路を封鎖した事件。西側は空輸で物資を運び続けた。","note":"冷戦初期の緊張を示す事件であり、空輸作戦とセットで覚える。","example":"ベルリン封鎖に対して西側諸国は大規模な空輸を行った。"},{"term":"ゴルバチョフ","reading":"ごるばちょふ","meaning":"ソ連の指導者。ペレストロイカやグラスノスチを進め、冷戦終結へ導いた。","note":"冷戦の終結とソ連解体に至る改革の担い手である。","example":"ゴルバチョフの改革は東ヨーロッパにも大きな影響を与えた。"},{"term":"ペレストロイカ","reading":"ぺれすとろいか","meaning":"ゴルバチョフが進めたソ連の改革。ロシア語で「立て直し」を意味し、経済や政治の改革を目指した。","note":"情報公開を意味するグラスノスチとセットで覚える。","example":"ペレストロイカによってソ連の社会は大きく変わり始めた。"},{"term":"マルタ会談","reading":"まるたかいだん","meaning":"1989年、米ソ首脳が地中海のマルタ島で会談し、冷戦の終結が確認された会談。","note":"冷戦終結の象徴であり、ベルリンの壁崩壊の直後の出来事である。","example":"マルタ会談で米ソ両首脳は冷戦の終わりを宣言した。"}]},{"topic":"グローバル化と現代の課題","cards":[{"term":"グローバル化","reading":"ぐろーばるか","meaning":"人・物・お金・情報が国境を越えて結びつきを強める現代の動き。","note":"経済の効率を高める一方、格差や文化の摩擦も生んでいる。","example":"グローバル化によって世界の経済は互いに影響し合うようになった。"},{"term":"WTOと自由貿易","reading":"だぶりゅーてぃーおーとじゆうぼうえき","meaning":"世界貿易機関を中心に、関税などを下げて貿易を広げようとする仕組み。","note":"GATTの後継として1995年に発足した体制。","example":"WTOと自由貿易の広がりは各国の経済を結びつけた。"},{"term":"南北問題と格差","reading":"なんぼくもんだいとかくさ","meaning":"豊かな先進国と発展途上国の間の経済格差をめぐる問題。","note":"資源価格や貿易条件などが背景となり、現代も続く課題。","example":"南北問題と格差の解消は国際社会の大きな課題である。"},{"term":"地球環境問題","reading":"ちきゅうかんきょうもんだい","meaning":"地球温暖化や生物多様性の減少など、国境を越えて取り組むべき環境の課題。","note":"国際会議や条約による協力が必要とされる分野。","example":"地球環境問題への対応には国際的な協力が欠かせない。"},{"term":"地域紛争と難民","reading":"ちいきふんそうとなんみん","meaning":"民族や宗教、領土などをめぐる紛争と、それにより住まいを追われる人々の問題。","note":"冷戦後も各地で続き、人道支援の課題となっている。","example":"地域紛争と難民の問題は今も世界各地で続いている。"},{"term":"SDGs","reading":"えすでぃーじーず","meaning":"2030年までに達成を目指す持続可能な開発目標。17の目標からなる。","note":"貧困や環境など世界の課題をまとめた国連の枠組み。","example":"SDGsは2030年までに達成を目指す国際目標である。"},{"term":"EU","reading":"いーゆー","meaning":"ヨーロッパ連合。1993年、マーストリヒト条約によって発足したヨーロッパ諸国の地域統合の組織。","note":"欧州連合ともいう。共通通貨ユーロの導入でも知られる。","example":"EUの発足でヨーロッパの統合は新しい段階に入った。"},{"term":"京都議定書","reading":"きょうとぎていしょ","meaning":"1997年に採択された、先進国に温室効果ガスの削減目標を定めた国際的な取り決め。","note":"気候変動対策の初期の枠組みであり、パリ協定より前に作られた。","example":"京都議定書では先進国に排出削減の義務が課された。"},{"term":"パリ協定","reading":"ぱりきょうてい","meaning":"2015年に採択された気候変動対策の国際枠組み。すべての国が削減目標を掲げる仕組みをとる。","note":"京都議定書と違い、途上国を含むすべての国が参加する枠組みである。","example":"パリ協定のもとで各国は温室効果ガスの削減目標を提出した。"},{"term":"リーマン=ショック","reading":"りーまんしょっく","meaning":"2008年、アメリカの投資銀行の破綻をきっかけに起きた世界的な金融危機。","note":"グローバル化した金融の結びつきが危機を世界へ広げた例である。","example":"リーマン=ショックの影響は世界中の経済に及んだ。"},{"term":"BRICS","reading":"ぶりっくす","meaning":"ブラジル、ロシア、インド、中国、南アフリカの新興国をまとめた呼び名。経済成長で存在感を高めた。","note":"国名の頭文字を組み合わせた言葉である。","example":"BRICSの国々は世界経済の中で発言力を強めている。"},{"term":"NGO","reading":"えぬじーおー","meaning":"非政府組織。国境をこえて環境保護や人道支援などに取り組む民間の団体を指す。","note":"政府から独立した民間の国際協力の担い手である。","example":"NGOは難民支援や環境保護の現場で活動している。"}]}]},{"subject":"倫理","topics":[{"topic":"人間の心のあり方","cards":[{"term":"ホモ・サピエンス","reading":"ほも・さぴえんす","meaning":"ラテン語で「知恵のある人」を意味し、言葉や思考によって世界を理解しようとする人間の側面を表す呼び名。","note":"人間を考える出発点として、道具を作る存在という見方と並べて押さえる。","example":"ホモ・サピエンスという呼び名は、人間が知恵を持ち考える存在であることを表している。"},{"term":"ホモ・ファーベル","reading":"ほも・ふぁーべる","meaning":"「作る人」という意味で、道具を作り使い、環境を作り変えながら生きてきた人間の姿を表す。","note":"知るだけでなく作ることで生きるという、人間のもう一つの特徴を示す。","example":"ホモ・ファーベルという見方は、道具を作り使うことが人間の特質だと考える。"},{"term":"青年期","reading":"せいねんき","meaning":"子どもから大人へ移る時期で、身体の変化とともに自分や将来について深く考えるようになる段階。","note":"このテーマでは、悩みながら自分らしさを探す時期として扱われる。","example":"青年期には、自分はどんな人間かと悩みながら将来の進路を考えることが多くなる。"},{"term":"アイデンティティ","reading":"あいでんてぃてぃ","meaning":"「自分は自分である」という感覚や、自分らしさについてのまとまった意識のこと。","note":"青年期の中心的な課題であり、進路や価値観を考える土台になる。","example":"アイデンティティを確立することは、青年期の大切な発達課題である。"},{"term":"認知","reading":"にんち","meaning":"外の出来事を受け取り、理解し、判断する心のはたらきのこと。","note":"感情と並ぶ心の働きとして、物事の捉え方が行動に影響する点が重要。","example":"同じ出来事でも、認知のしかたが違えば受け止め方や感情も変わってくる。"},{"term":"感情","reading":"かんじょう","meaning":"喜びや不安など、出来事に対して心が動く状態のこと。","note":"理性だけで割り切れない人間の心を理解する手がかりになる。","example":"感情は、物事の価値を感じ取り、行動へと人を動かす原動力になる。"},{"term":"ホモ・ルーデンス","reading":"ほも・るーでんす","meaning":"人間を遊ぶ存在としてとらえる見方で、ホイジンガが唱えた。遊びが文化を生む原動力だと考える。","note":"「ルーデンス」は遊ぶという意味。ホモ・サピエンス（知恵）と対比して覚える。","example":"ホモ・ルーデンスの考えでは、祭りや競技などの遊びが文化の発展を支えてきた。"},{"term":"パーソナリティ","reading":"ぱーそなりてぃ","meaning":"その人らしい行動や感じ方の傾向のまとまりを指す性格のこと。生まれつきの気質と環境の影響で形作られる。","note":"類型論と特性論という二つの見方がある。ビッグ・ファイブは特性論の代表例。","example":"パーソナリティの違いを知ると、友人との感じ方の違いも理解しやすくなる。"},{"term":"古典的条件づけ","reading":"こてんてきじょうけんづけ","meaning":"パブロフの犬の実験で知られる学習の仕組み。本来関係のない刺激と反応が結びついて、新しい反応が生まれる。","note":"犬がベルの音でよだれを出す例が有名。オペラント条件づけと区別する。","example":"古典的条件づけでは、繰り返しの経験によって刺激と反応が結びつく。"},{"term":"内発的動機づけ","reading":"ないはつてきどうきづけ","meaning":"報酬のためではなく、活動そのものが楽しい・知りたいという気持ちから行動する動機づけ。","note":"外から与えられる賞や罰による外発的動機づけと対比される。","example":"内発的動機づけが高い人は、好きな勉強を自分から続けやすい。"},{"term":"エス","reading":"えす","meaning":"フロイトが考えた心の最も原始的な部分で、本能的な欲求の源。快楽を求める働きをする。","note":"イドとも呼ばれる。自我・超自我とあわせてフロイトの心の三区分を覚える。","example":"フロイトは、エスの欲求を自我が現実に合わせて調整すると考えた。"},{"term":"超自我","reading":"ちょうじが","meaning":"フロイトが考えた心の部分で、道徳や理想を担い、良心として働く。親や社会の規範を取り入れて形成される。","note":"エスが欲求、自我が調整役、超自我が道徳の声、と役割で区別する。","example":"超自我が強く働くと、人はルールを破ることに強い罪悪感を覚える。"}]},{"topic":"ギリシャの哲学者たち","cards":[{"term":"ソクラテス","reading":"そくらてす","meaning":"古代ギリシャの哲学者で、問答を重ねて相手に自らの無知に気づかせ、よく生きることを探った。","note":"対話を通じて真理を探る姿勢が、後の西洋哲学の出発点となった。","example":"ソクラテスは著書を残さず、対話によって人々に無知の自覚を促した。"},{"term":"無知の知","reading":"むちのち","meaning":"自分が本当は知らないことを自覚している状態のこと。ソクラテスが大切にした態度。","note":"知ったつもりにならず学び続ける姿勢として、このテーマの核になる。","example":"無知の知を自覚した人ほど、学ぼうとする姿勢を持ち続けることができる。"},{"term":"プラトン","reading":"ぷらとん","meaning":"ソクラテスの弟子で、目に見える世界の奥にある永遠の真実を考えた哲学者。","note":"イデア論を唱え、理想の国家のあり方も論じた。","example":"プラトンはアカデメイアという学園を開いて教育と研究を行った。"},{"term":"イデア","reading":"いであ","meaning":"個々の物事の原型となる、永遠で完全な本質のこと。プラトンの中心概念。","note":"目に見える物は不完全でも、その元となる姿があるという考え方を示す。","example":"プラトンは、美しい物の一つひとつではなく、美そのものであるイデアが真実在だと考えた。"},{"term":"アリストテレス","reading":"ありすとてれす","meaning":"プラトンの弟子で、現実の物事を観察し分類しながら、その目的や原因を考えた哲学者。","note":"イデアを現実から離さず、身近な世界の中で本質を探った点が対照的。","example":"アリストテレスは、経験を重んじながら多くの学問分野を体系化した。"},{"term":"ソフィスト","reading":"そふぃすと","meaning":"古代ギリシャで弁論や政治の技術を教えた人々の総称。","note":"相対的なものの見方を広めた一方、ソクラテスやプラトンから批判も受けた。","example":"ソフィストは、裁判や議会で役立つ弁論術を報酬を得て教えた。"},{"term":"プロタゴラス","reading":"ぷろたごらす","meaning":"ソフィストの代表的人物。「人間は万物の尺度である」と唱え、真理は人それぞれだとする相対主義を説いた。","note":"ソクラテスが批判した相手として登場する。名前と「万物の尺度」をセットで覚える。","example":"プロタゴラスは「人間は万物の尺度である」と述べて相対主義を示した。"},{"term":"哲人政治","reading":"てつじんせいじ","meaning":"プラトンが『国家』で説いた理想の政治。知恵を備えた哲学者が国を治めるべきだとする考え。","note":"哲人が王になるか王が哲学を学ぶべきだという主張。民主政への批判と結びつく。","example":"プラトンは哲人政治によって正義が実現する理想国家を描いた。"},{"term":"四元徳","reading":"しげんとく","meaning":"プラトンが理想国家と魂に共通する徳として挙げた、知恵・勇気・節制・正義の四つの徳。","note":"正義は他の三つを調和させる徳とされる。四つの名前を順に覚える。","example":"プラトンは四元徳がそろうことで魂と国家に正義が成り立つと考えた。"},{"term":"洞窟の比喩","reading":"どうくつのひゆ","meaning":"プラトンがイデア論を説明したたとえ。洞窟の壁の影しか見られない囚人が、真実の世界を知らない人間にたとえられる。","note":"影＝感覚の世界、外の太陽＝善のイデア、と対応させて覚える。","example":"洞窟の比喩は、私たちが見ているものが真実そのものではない可能性を示す。"},{"term":"エピクロス派","reading":"えぴくろすは","meaning":"ヘレニズム期の学派で、エピクロスが創始した。心の平静（アタラクシア）を得ることを幸福と考えた。","note":"快楽主義と呼ばれるが、求めたのは苦痛のない穏やかな快楽である点に注意。","example":"エピクロス派は、欲望を抑えて心の平静を保つ生き方を目指した。"},{"term":"ストア派","reading":"すとあは","meaning":"ヘレニズム期の学派で、ゼノンが創始した。感情に動かされず理性に従う生き方（アパテイア）を理想とした。","note":"ストイック（禁欲的）という言葉の語源。エピクロス派と対比される。","example":"ストア派は、運命を受け入れて理性に従う生き方を説いた。"}]},{"topic":"仏教の思想","cards":[{"term":"ゴータマ","reading":"ごーたま","meaning":"仏教を開いた人物の名で、釈迦とも呼ばれる。苦しみの原因を見つめ、悟りへの道を示した。","note":"仏教思想の中心人物として、生涯と教えの出発点を押さえる。","example":"ゴータマは王子として生まれたが、老いや病に苦しむ人々を見て出家したと伝えられる。"},{"term":"四苦八苦","reading":"しくはっく","meaning":"生まれること、老いること、病むこと、死ぬことなど、人生に避けがたい苦しみがあるという見方。","note":"仏教がなぜ苦しみからの解放を目指すのかを理解する入口になる。","example":"四苦八苦という見方は、人生から苦しみを完全には避けられないことを示している。"},{"term":"煩悩","reading":"ぼんのう","meaning":"欲や怒り、迷いなど、心を乱して苦しみを生む働きのこと。","note":"苦しみの原因とされ、これを滅することが修行の目標とされた。","example":"煩悩をなくすことが悟りへの道だと、仏教では説かれている。"},{"term":"解脱","reading":"げだつ","meaning":"煩悩による苦しみの束縛から解き放たれ、悟りの境地に達すること。","note":"ゴータマが目指し、仏教の実践の到達点とされる状態。","example":"解脱とは、煩悩による苦しみの束縛から解き放たれることである。"},{"term":"大乗仏教","reading":"だいじょうぶっきょう","meaning":"自分だけでなく、すべての人々の救いを目指す仏教の流れ。","note":"日本に伝わった仏教の多くがこの流れに属し、菩薩の考え方が特徴。","example":"大乗仏教は、多くの人々の救済を目指す点に大きな特徴がある。"},{"term":"縁起","reading":"えんぎ","meaning":"すべての物事は単独で存在せず、互いに関わり合いながら成り立っているという考え方。","note":"固定的な実体を否定する、仏教らしい世界観の土台になる。","example":"縁起の考えでは、自分の存在も他者や環境との関係の中で成り立っている。"},{"term":"四諦","reading":"したい","meaning":"ブッダの教えの基本で、苦諦・集諦・滅諦・道諦の四つの真理。人生は苦であり、その原因と克服の道を示す。","note":"苦・集・滅・道の順に「苦しみ、原因、克服、方法」と覚える。","example":"四諦は、苦しみの実態とそこから離れる道を順序立てて示している。"},{"term":"八正道","reading":"はっしょうどう","meaning":"悟りに至るための八つの正しい実践。正見・正思惟・正語・正業・正命・正精進・正念・正定からなる。","note":"四諦の道諦の具体的な内容。中道を実践する方法とされる。","example":"八正道を実践することは、日常生活の中で中道を歩むことにつながる。"},{"term":"無明","reading":"むみょう","meaning":"物事の真実を知らない無知のこと。煩悩の根本にあり、苦しみの連鎖の出発点とされる。","note":"「明るくない」状態という字面で覚える。渇愛とあわせて苦の原因として出る。","example":"仏教では、無明をなくすことが解脱への第一歩とされる。"},{"term":"渇愛","reading":"かつあい","meaning":"満たされることのない強い欲望や執着のこと。四諦の集諦で苦しみの原因とされる。","note":"「渇」は喉の渇きの字。乾きをいやすように求め続ける欲望を表す。","example":"渇愛を手放すことが、苦しみから離れる道だとブッダは説いた。"},{"term":"上座部仏教","reading":"じょうざぶぶっきょう","meaning":"出家者の修行による自己の悟りを重視する仏教の流れ。スリランカや東南アジアに広がった。","note":"大乗仏教と対比される。かつて小乗仏教と呼ばれたが、今はこの名称が使われる。","example":"上座部仏教は、ブッダの初期の教えを重んじて東南アジアに伝わった。"},{"term":"空","reading":"くう","meaning":"龍樹が深めた考えで、すべてのものには固定した実体（自性）がなく、縁起によって成り立つとする見方。","note":"「何もない」という意味ではない。実体がないからこそ関係で成り立つ、と理解する。","example":"空の思想は、物事への執着を離れる根拠として説かれた。"}]},{"topic":"キリスト教とイスラム教","cards":[{"term":"イエス","reading":"いえす","meaning":"キリスト教の中心人物で、神の愛と隣人への愛を説いたとされる。","note":"その生涯と教えが、キリスト教の信仰の核になっている。","example":"イエスは、敵をも愛しなさいと説いて隣人愛の範囲を広げた。"},{"term":"隣人愛","reading":"りんじんあい","meaning":"身近な人々だけでなく、困っている人や敵をも含めて大切にする愛の考え方。","note":"キリスト教倫理を代表する実践として、このテーマで中心的に扱われる。","example":"隣人愛は、身近な人だけでなく困っている人すべてに向けられるべきだとされる。"},{"term":"聖書","reading":"せいしょ","meaning":"キリスト教の聖典で、旧約と新約から成り、神と人間の関わりやイエスの教えが記される。","note":"信仰と生活の基準となる書物として位置づけられる。","example":"聖書は、旧約聖書と新約聖書の二つから構成されている。"},{"term":"ムハンマド","reading":"むはんまど","meaning":"イスラム教の預言者で、神の啓示を受けたとされ、その言葉が後にまとめられた。","note":"イスラム教の成立を理解するうえで欠かせない人物。","example":"ムハンマドは、メッカで迫害を受けた後、メディナへ移住した（ヒジュラ）。"},{"term":"コーラン","reading":"こーらん","meaning":"イスラム教の聖典で、ムハンマドが受けたとされる神の啓示を集めたもの。","note":"信仰だけでなく生活の指針としても読まれる点が特徴。","example":"コーランはアラビア語で書かれ、イスラム教徒の生活の規範となっている。"},{"term":"五行","reading":"ごぎょう","meaning":"イスラム教徒が日常で実践すべき信仰告白や礼拝、喜捨などの行いの柱のこと。","note":"信じるだけでなく、日々の実践を重んじるイスラム教の姿を示す。","example":"五行を実践することは、イスラム教徒の信仰生活の柱である。"},{"term":"旧約聖書","reading":"きゅうやくせいしょ","meaning":"キリスト教の聖書の前半で、ユダヤ教の聖典でもある。天地創造やモーセの十戒などが記される。","note":"「旧約」は神との古い契約の意味。新約聖書と対で覚える。","example":"旧約聖書には、モーセが神から十戒を授かる物語が記されている。"},{"term":"新約聖書","reading":"しんやくせいしょ","meaning":"キリスト教の聖書の後半で、イエスの生涯と教えを記した福音書などを含む。","note":"福音書はマタイ・マルコ・ルカ・ヨハネの四つがある。","example":"新約聖書の福音書には、イエスが説いた隣人愛の教えが記されている。"},{"term":"カトリック","reading":"かとりっく","meaning":"ローマ教皇を中心とするキリスト教最大の教派。宗教改革以前の西ヨーロッパの教会の伝統を受け継ぐ。","note":"プロテスタントと対比される。教会と聖職者の権威を重んじる点が特徴。","example":"カトリックでは、ローマ教皇が教会の最高指導者とされる。"},{"term":"ユダヤ教","reading":"ゆだやきょう","meaning":"唯一神ヤハウェを信じる古代イスラエルの民族宗教。キリスト教とイスラム教の源流となった。","note":"三つの一神教の共通のルーツ。聖典は旧約聖書と重なる部分が多い。","example":"ユダヤ教は、キリスト教とイスラム教が分かれる前の源流の宗教である。"},{"term":"メッカ","reading":"めっか","meaning":"イスラム教最大の聖地で、アラビア半島の都市。ムハンマドの生誕地であり、巡礼（ハッジ）の目的地。","note":"五行の一つである巡礼の行き先。礼拝もメッカの方角に向けて行う。","example":"世界中のイスラム教徒は、メッカの方角を向いて礼拝を行う。"},{"term":"ラマダーン","reading":"らまだーん","meaning":"イスラム暦の第9月で、断食を行う月の名前。この月、イスラム教徒は日の出から日没まで飲食を断つ。","note":"五行の断食が行われる月の名前。断食そのものはサウムとも呼ばれる。","example":"ラマダーンの期間中、イスラム教徒は日中の飲食を控えて祈りを深める。"}]},{"topic":"中国の思想","cards":[{"term":"孔子","reading":"こうし","meaning":"儒教の祖とされる思想家で、人としての道徳や社会の秩序のあり方を説いた。","note":"仁と礼を中心とする教えが、中国思想の大きな土台となった。","example":"孔子は、政治を行う者はまず自らの徳を高めるべきだと説いた。"},{"term":"仁","reading":"じん","meaning":"人を思いやり、大切にする心のこと。儒教で最も重んじられた徳。","note":"家族への愛情を出発点に、社会全体へ広げていくことが求められた。","example":"仁は、自分の親を大切にする心を、他の人へも広げていくことだとされる。"},{"term":"礼","reading":"れい","meaning":"人間関係や社会の秩序を保つための、具体的な振る舞いや決まりのこと。","note":"仁という内面の心を、実際の行動として表すものとされた。","example":"礼は、仁という内面の心を、社会で通用する形に表したものである。"},{"term":"孟子の性善説","reading":"もうしのせいぜんせつ","meaning":"人間には生まれつき善に向かう芽生えがあり、育てることで善くなれるという孟子の考え。","note":"四端の心を伸ばすことが、王道政治の基礎になるとされた。","example":"孟子の性善説では、子どもが井戸に落ちそうなのを見て助けたいと思う心が根拠に挙げられる。"},{"term":"荀子の性悪説","reading":"じゅんしのせいあくせつ","meaning":"人間の欲望を放置すると争いが生じるため、礼による教育や訓練が必要だとする荀子の考え。","note":"性善説と対比され、後天的な努力を重視する点が特徴。","example":"荀子の性悪説は、人を悲観する考えではなく、学びによる成長を重んじる考えである。"},{"term":"老子の無為自然","reading":"ろうしのむいしぜん","meaning":"人為的な作為を控え、自然の流れに任せて生きることをよしとする老子の考え。","note":"儒教の礼による秩序とは異なる、道家の生き方を示す。","example":"老子の無為自然は、何もしないことではなく、自然の流れに逆らわない生き方である。"},{"term":"荘子の万物斉同","reading":"そうしのばんぶつせいどう","meaning":"物事の価値や区別は相対的で、万物は本来等しく一つながりだとする荘子の見方。","note":"小さな価値判断にとらわれない、自由な精神を説く考え方。","example":"荘子の万物斉同では、夢の中で蝶になった体験（胡蝶の夢）がたとえとして語られる。"},{"term":"論語","reading":"ろんご","meaning":"孔子と弟子たちの言葉や問答を、弟子たちがまとめた書物。儒家の基本的な経典の一つ。","note":"孔子自身が書いた本ではない点がポイント。孔子の仁の出題とセットで出る。","example":"『論語』には、孔子が仁や礼について弟子に語った言葉が収められている。"},{"term":"四端","reading":"したん","meaning":"孟子が説いた、人間に生まれつき備わる善の芽生え。惻隠・羞悪・辞譲・是非の四つの心を指す。","note":"仁・義・礼・智の四徳のもとになる心。四つの名前の頭を押さえる。","example":"孟子は四端を育てることで、仁や義の徳が完成すると考えた。"},{"term":"化性起偽","reading":"けせいきぎ","meaning":"荀子の考えで、人間の悪に向かいやすい本性を、後天的な努力や礼の学習によって正しく変えること。","note":"「偽」は人の作為の意味で、うそではない。性悪説とセットで覚える。","example":"荀子は化性起偽によって、人は善い行いができるようになると説いた。"},{"term":"王道政治","reading":"おうどうせいじ","meaning":"孟子が理想とした、徳のある君主が仁政を行い、人々の心から従わせる政治。力による覇道政治と対比される。","note":"易姓革命の思想とも結びつく。天命を失った君主は替えられてよいとする考え。","example":"孟子は王道政治を行えば、人々は自然に君主に従うと考えた。"},{"term":"道徳経","reading":"どうとくきょう","meaning":"老子の思想をまとめたとされる書物で、『老子』とも呼ばれる。道（タオ）や無為自然が説かれる。","note":"道家の根本経典。儒家の『論語』と区別する。","example":"『道徳経』には、無為自然を理想とする老子の言葉が記されている。"}]},{"topic":"近代の哲学者","cards":[{"term":"デカルト","reading":"でかると","meaning":"「我思う、ゆえに我あり」で知られ、疑いを徹底して確実な知識の基礎を探った哲学者。","note":"近代哲学の出発点とされ、合理論の代表とされる。","example":"デカルトは、感覚のあやふやさに気づき、確実な知識の土台を探し求めた。"},{"term":"合理論","reading":"ごうりろん","meaning":"知識の確かさは感覚よりも理性による思考に由来すると考える立場。","note":"デカルトら大陸の哲学者に代表され、経験論と対比される。","example":"合理論の立場では、数学のような知識は理性によって確実に得られると考える。"},{"term":"経験論","reading":"けいけんろん","meaning":"知識は経験や感覚を通じて得られると考える立場。","note":"ロックやヒュームらが代表し、合理論との対比で理解する。","example":"経験論の立場では、生まれたときの心には知識はなく、経験が知識の源だと考える。"},{"term":"カント","reading":"かんと","meaning":"合理論と経験論を統合しようとし、人間が認識できる範囲と道徳の基礎を問い直した哲学者。","note":"義務に基づく道徳や、認識の仕組みの考察で知られる。","example":"カントは、人間の認識には限界があることを示しながら、道徳の根拠を理性に求めた。"},{"term":"ベンサム","reading":"べんさむ","meaning":"幸福を量として考え、社会全体の幸福を最大にすることを道徳の基準とした思想家。","note":"功利主義の創始者として、次の社会思想への橋渡しになる。","example":"ベンサムは、法律や制度も幸福の量をものさしに評価すべきだと考えた。"},{"term":"ニーチェ","reading":"にーちぇ","meaning":"既存の道徳や価値観を批判し、自ら価値を創造して生きることを説いた哲学者。","note":"「神は死んだ」という言葉で、近代の価値転換を象徴する存在。","example":"ニーチェは、弱さを肯定するだけの道徳を批判し、強く生きることを求めた。"},{"term":"方法的懐疑","reading":"ほうほうてきかいぎ","meaning":"デカルトが確実な知識を求めて行った方法。少しでも疑いうるものをいったんすべて疑い、疑いえないものを探した。","note":"疑うこと自体が目的ではなく、確実な土台を探す方法である点に注意。","example":"方法的懐疑の末に、デカルトは「我思う、ゆえに我あり」に到達した。"},{"term":"タブラ・ラサ","reading":"たぶら・らさ","meaning":"ロックが用いた言葉で、生まれたばかりの心は白紙（白い板）のような状態だとする考え。経験によって観念が書き込まれる。","note":"経験論を象徴する言葉。生得観念を否定する立場と結びつく。","example":"ロックは心をタブラ・ラサにたとえ、知識は経験から生まれると説いた。"},{"term":"物自体","reading":"ものじたい","meaning":"カントの言葉で、人間の認識の形式を通しては捉えられない、物そのもののあり方。認識できるのは現象だけだとされる。","note":"現象と対をなす言葉。カントの批判哲学の中心概念の一つ。","example":"カントは物自体は認識できないが、その存在を否定したわけではない。"},{"term":"批判哲学","reading":"ひはんてきてつがく","meaning":"カントの哲学の呼び名。理性の能力と限界そのものを検討（批判）し、認識が成り立つ条件を明らかにしようとした。","note":"「批判」は非難ではなく、能力を吟味する意味。『純粋理性批判』が代表作。","example":"批判哲学によって、カントは合理論と経験論の対立を乗り越えようとした。"},{"term":"ニヒリズム","reading":"にひりずむ","meaning":"最高の価値が力を失い、人生に意味がないと感じられる状態。ニーチェが近代ヨーロッパの危機として指摘した。","note":"虚無主義と訳される。ニーチェは超人による克服を目指した。","example":"ニヒリズムに陥ると、人は何のために生きるのかを見失いやすくなる。"},{"term":"永劫回帰","reading":"えいごうかいき","meaning":"ニーチェの思想で、今の人生が永遠に繰り返されるとする考え。その繰り返しを受け入れて生きる強さが問われる。","note":"同じ人生を何度でも望めるかが試金石になる。超人の生き方と結びつく。","example":"永劫回帰を受け入れるとは、今の自分の生き方を肯定することである。"}]},{"topic":"社会変革の思想と現代思想","cards":[{"term":"功利主義","reading":"こうりしゅぎ","meaning":"行為の正しさを、その結果として生じる幸福の大きさによって判断する考え方。","note":"ベンサムとミルが代表で、社会制度を評価する基準にもなった。","example":"功利主義では、一つの政策が多くの人の幸福を増やすかどうかが評価の基準になる。"},{"term":"ミルの功利主義","reading":"みるのこうりしゅぎ","meaning":"幸福の量だけでなく質も重視し、自由の大切さを守ろうとしたミルの功利主義。","note":"ベンサムの考えを発展させ、個人の自由との両立を図った点が特徴。","example":"ミルの功利主義は、快楽の量だけでなく質の違いも考慮する点に特徴がある。"},{"term":"社会主義思想","reading":"しゃかいしゅぎしそう","meaning":"生産手段を社会全体で所有・管理し、貧富の差をなくそうとする考え方の総称。","note":"資本主義が生んだ格差や労働問題への批判から広がった。","example":"社会主義思想は、資本主義のもとで生じる貧富の格差への批判から生まれた。"},{"term":"実証主義","reading":"じっしょうしゅぎ","meaning":"確かめられる事実や科学的な方法に基づく知識だけを信頼しようとする立場。","note":"コントが代表し、近代の科学重視の流れを表す思想。","example":"実証主義は、観察や経験で確かめられない形而上学的な議論を退ける立場である。"},{"term":"実存主義","reading":"じつぞんしゅぎ","meaning":"人間はあらかじめ決まった本質を持たず、自らの選択によって自分を作っていくとする考え方。","note":"サルトルらが代表し、自由と責任を重く見る点が特徴。","example":"実存主義では、人は自分の選択に責任を引き受けることで自分自身を作っていく。"},{"term":"構造主義","reading":"こうぞうしゅぎ","meaning":"個人の意識よりも、その背後にある社会や文化の仕組みに注目して人間を理解しようとする考え方。","note":"レヴィ＝ストロースらが代表し、現代思想に大きな影響を与えた。","example":"構造主義は、個々の文化の背後に共通する無意識の構造があると考える。"},{"term":"他者危害の原則","reading":"たしゃきがいのげんそく","meaning":"ミルが『自由論』で説いた考え。他人に危害を及ぼす場合にだけ、社会は個人の自由に介入できるとする。","note":"自由の制限を認める唯一の理由が「他者への危害」という点がポイント。","example":"他者危害の原則によれば、自分だけに影響する行為は自由が保障される。"},{"term":"空想的社会主義","reading":"くうそうてきしゃかいしゅぎ","meaning":"サン＝シモンやフーリエらが唱えた初期の社会主義。理想の共同社会を描いたが、実現の道筋は示さなかったとマルクスが批判した。","note":"マルクスの科学的社会主義と対比される名前で覚える。","example":"マルクスは空想的社会主義を批判し、自らの立場を科学的社会主義と位置づけた。"},{"term":"資本主義","reading":"しほんしゅぎ","meaning":"生産手段を資本家が私有し、利潤の追求を原動力として生産が行われる経済の仕組み。マルクスが分析の対象とした。","note":"社会主義はこの仕組みへの批判から生まれた。産業革命とあわせて押さえる。","example":"資本主義のもとでは、工場などの生産手段は資本家が所有する。"},{"term":"レヴィ＝ストロース","reading":"れゔぃ＝すとろーす","meaning":"フランスの人類学者で、構造主義を代表する思想家。『野生の思考』で未開社会の思考の論理を示した。","note":"構造主義といえばこの人物。文化の背後の無意識の構造を探った。","example":"レヴィ＝ストロースは、神話の分析から文化に共通する構造を見いだそうとした。"},{"term":"アンガージュマン","reading":"あんがーじゅまん","meaning":"サルトルが説いた、社会参加・社会関与のこと。知識人は社会の問題に積極的に関わるべきだとした。","note":"フランス語で「参加・拘束」の意味。実存主義と社会実践を結ぶ言葉。","example":"サルトルはアンガージュマンを唱え、自らも社会問題に発言を続けた。"},{"term":"三段階の法則","reading":"さんだんかいのほうそく","meaning":"コントが説いた、人間の知識や社会は神学的段階・形而上学的段階・実証的段階の順に進むとする法則。","note":"実証主義の説明として出る。最後が実証的段階である順序を覚える。","example":"コントは三段階の法則によって、社会の進歩を科学の発展と結びつけて説明した。"}]},{"topic":"日本の思想","cards":[{"term":"神道","reading":"しんとう","meaning":"自然や祖先などに宿る神を敬い、祭りを通じて共同体と結びついてきた日本固有の信仰。","note":"日本の思想の土台の一つとして、外来思想との関わりの中で捉える。","example":"神道には特定の開祖や経典がなく、自然や祖先への信仰が受け継がれてきた。"},{"term":"浄土信仰","reading":"じょうどしんこう","meaning":"阿弥陀仏の救いを信じ、極楽浄土への往生を願う信仰のこと。","note":"平安末期の不安な社会の中で広がり、鎌倉仏教へつながった。","example":"浄土信仰は、末法の世には自力の修行が難しいと考える人々の間で広がった。"},{"term":"法然","reading":"ほうねん","meaning":"念仏を唱えることで誰もが救われると説き、浄土宗を開いた僧。","note":"専修念仏を唱え、身分によらない救いの道を示した。","example":"法然は、貴族から庶民まで、念仏を唱えるすべての人の救いを説いた。"},{"term":"親鸞","reading":"しんらん","meaning":"法然の弟子で、阿弥陀仏の力にすべてを委ねる救いを説き、浄土真宗を開いた僧。","note":"悪人正機説で知られ、自分の力に頼らない信仰を深めた。","example":"親鸞は、法然の弟子として浄土真宗を開き、悪人正機を説いた。"},{"term":"朱子学","reading":"しゅしがく","meaning":"宇宙や社会の秩序を理によって説明し、身分秩序や道徳の根拠とした儒学の一派。","note":"江戸幕府に採用され、武士の学問や教育の中心となった。","example":"朱子学は江戸時代に幕府の学問として重んじられ、身分秩序を支えた。"},{"term":"本居宣長","reading":"もとおりのりなが","meaning":"『古事記』などの研究を通じて日本固有の精神を探り、国学を大成した学者。","note":"外来思想の影響を離れて古典を読み直そうとした点が特徴。","example":"本居宣長は、35年をかけて『古事記伝』を完成させた国学者である。"},{"term":"福沢諭吉","reading":"ふくざわゆきち","meaning":"学問の大切さと人の独立を説き、近代的な教育や社会のあり方を示した思想家。","note":"『学問のすゝめ』で知られ、明治の啓蒙思想を代表する。","example":"福沢諭吉は、慶應義塾を創設して教育による人材の育成にも力を注いだ。"},{"term":"古事記伝","reading":"こじきでん","meaning":"本居宣長が『古事記』を研究して著した注釈書。全44巻の大著で、国学を大成した著作とされる。","note":"宣長といえば『古事記伝』と「もののあはれ」。漢意（からごころ）批判と結びつく。","example":"宣長は『古事記伝』の研究を通して、日本古来の心を明らかにしようとした。"},{"term":"国学","reading":"こくがく","meaning":"江戸時代に興った学問で、儒教や仏教の影響を受ける前の日本古来の精神や文化を、古典の研究から明らかにしようとした。","note":"本居宣長が大成者。漢学と対比される名前で覚える。","example":"国学は、『古事記』や『万葉集』の研究を通して日本人の心を探った。"},{"term":"専修念仏","reading":"せんじゅねんぶつ","meaning":"法然が説いた、他の修行をせず念仏だけに専念することで救われるとする教え。南無阿弥陀仏を唱えることを重んじた。","note":"「専修」は一つに専念する意味。浄土宗の中心の教えである。","example":"法然は専修念仏を説き、誰もが念仏によって救われるとした。"},{"term":"独立自尊","reading":"どくりつじそん","meaning":"福沢諭吉が重んじた精神。自ら学び、他に頼らず自分の判断で生き、自分の尊厳を守ること。","note":"『学問のすゝめ』の平等論とあわせて出る。福沢のキーワードとして覚える。","example":"福沢は独立自尊の精神を持つことが、国の独立にもつながると考えた。"},{"term":"西田幾多郎","reading":"にしだきたろう","meaning":"明治から昭和に活躍した哲学者。主著『善の研究』で純粋経験を説き、京都学派の中心となった。","note":"純粋経験の出題と必ずセットになる人物名。日本近代哲学の代表者。","example":"西田幾多郎は『善の研究』で、日本独自の哲学を築こうとした。"}]},{"topic":"現代の諸課題と倫理","cards":[{"term":"生命倫理","reading":"せいめいりんり","meaning":"医療や科学技術の進歩に伴い、生命の始まりや終わり、人間の尊厳をどう扱うか考える分野。","note":"臓器移植や生殖医療など、答えが一つでない問題を扱う。","example":"生命倫理では、医療技術の進歩が人の生と死に与える影響が問われる。"},{"term":"環境倫理","reading":"かんきょうりんり","meaning":"自然や将来世代に対して人間がどのような責任を持つかを考える分野。","note":"人間中心の見方を見直し、持続可能な社会を目指す土台になる。","example":"環境倫理では、将来世代や自然そのものへの責任が重要な論点になる。"},{"term":"科学技術と倫理","reading":"かがくぎじゅつとりんり","meaning":"便利さを生む技術の利用に伴う危険や責任を、倫理の面から考える視点のこと。","note":"AIや遺伝子技術など、新しい技術ほど問われやすいテーマ。","example":"科学技術と倫理の問題では、技術的に可能でも行ってよいとは限らない点が問われる。"},{"term":"正義","reading":"せいぎ","meaning":"人々の権利や利益、負担を公平に配分するための基準や考え方のこと。","note":"福祉や格差の問題を考えるときの中心概念になる。","example":"正義をめぐっては、結果の平等と機会の平等のどちらを重んじるかで意見が分かれる。"},{"term":"多文化共生","reading":"たぶんかきょうせい","meaning":"文化や価値観の異なる人々が、違いを認め合いながら共に暮らすこと。","note":"グローバル化が進む社会で、互いの尊厳を守る姿勢が求められる。","example":"多文化共生の社会では、互いの文化や宗教の違いを認め合う姿勢が求められる。"},{"term":"平和の実現","reading":"へいわのじつげん","meaning":"戦争や暴力をなくすだけでなく、貧困や差別などの構造的な問題も解くことを含む目標。","note":"国際協力や人権尊重と結びつけて考えられる現代的課題。","example":"平和の実現には、戦争を防ぐだけでなく貧困や差別をなくす努力も欠かせない。"},{"term":"ロールズ","reading":"ろーるず","meaning":"アメリカの哲学者。『正義論』で「公正としての正義」を説き、現代の正義論に大きな影響を与えた。","note":"無知のヴェールと原初状態がセットのキーワード。福祉と正義の単元で出る。","example":"ロールズは、公正な社会の原理を考える方法として原初状態を設定した。"},{"term":"無知のヴェール","reading":"むちのゔぇーる","meaning":"ロールズの考えで、自分の社会的地位や能力を知らない状態のこと。その状態で選ばれる原理こそ公正だとされる。","note":"原初状態とあわせて覚える。格差原理を導くための設定である。","example":"無知のヴェールの下では、誰もが最も不利な人の立場を考えて原理を選ぶ。"},{"term":"積極的平和","reading":"せっきょくてきへいわ","meaning":"ガルトゥングの考えで、戦争がないだけでなく、貧困や差別などの構造的暴力もない状態をいう平和。","note":"戦争がないだけの「消極的平和」と対比される。","example":"積極的平和の実現には、貧困や差別をなくす取り組みも必要である。"},{"term":"構造的暴力","reading":"こうぞうてきぼうりょく","meaning":"ガルトゥングの概念で、貧困や差別など、社会の仕組み自体が人々を苦しめる形の暴力。","note":"直接的な暴力と区別される。積極的平和とセットで覚える。","example":"構造的暴力は、特定の加害者がいなくても人々の命や生活を脅かす。"},{"term":"脳死","reading":"のうし","meaning":"脳幹を含む脳全体の機能が回復不能に停止した状態。臓器移植との関係で、人の死とするかどうかが論点になる。","note":"心臓死（従来の死の基準）と対比される。日本では臓器提供の場合に限る扱いも論点。","example":"脳死を人の死と認めるかどうかは、国や立場によって考えが分かれる。"},{"term":"安楽死","reading":"あんらくし","meaning":"耐えがたい苦痛にある患者の死期を、医師の行為によって早めること。積極的安楽死の是非が生命倫理で論じられる。","note":"尊厳死（延命治療の中止）とは区別される。本人の意思が大前提となる。","example":"安楽死については、本人の自己決定と生命の尊重の両面から議論が続いている。"}]}]},{"subject":"政治・経済","topics":[{"topic":"民主政治の基本原理","cards":[{"term":"国民主権","reading":"こくみんしゅけん","meaning":"国の政治の最終的な決定権は国民全体にあるという原理。","note":"民主政治の根幹であり、日本国憲法の基本原則の一つでもある。","example":"国民主権のもとでは、選挙を通じて国民の意思が政治に反映される。"},{"term":"社会契約説","reading":"しゃかいけいやくせつ","meaning":"国家は人々が互いに約束を結んで作ったものだと説明する考え方。","note":"ホッブズ、ロック、ルソーがそれぞれ異なる形で論じ、国民主権の土台となった。","example":"社会契約説では、人々が合意によって国家を作ると考えられている。"},{"term":"権力分立","reading":"けんりょくぶんりつ","meaning":"国家の権力を複数の機関に分け、互いに抑制させることで権力の集中を防ぐ仕組み。","note":"モンテスキューが説いた三権分立が代表例として扱われる。","example":"権力分立によって、立法・行政・司法が互いに抑制し合っている。"},{"term":"法の支配","reading":"ほうのしはい","meaning":"権力者も法に従わなければならず、人の恣意的な支配を認めないという考え方。","note":"立憲主義と結びつき、人権保障の基礎になる原理。","example":"法の支配のもとでは、権力者であっても法に従わなければならない。"},{"term":"基本的人権","reading":"きほんてきじんけん","meaning":"人間が生まれながらに持つとされる、侵すことのできない基本的な権利の総称。","note":"自由権や平等権、社会権などが含まれ、民主政治の目的とされる。","example":"基本的人権は、すべての人が生まれながらに持つ権利である。"},{"term":"立憲主義","reading":"りっけんしゅぎ","meaning":"憲法によって国家権力を制限し、国民の権利を守ろうとする考え方。","note":"法の支配と並んで、近代民主政治の前提となる原理。","example":"立憲主義に基づき、政治権力は憲法によって制限される。"},{"term":"王権神授説","reading":"おうけんしんじゅせつ","meaning":"王の権力は神から与えられたものであるため、王は絶対的な権力を持つとする考え方。","note":"社会契約説と対比される、市民革命以前の支配を正当化する考え方として覚える。","example":"王権神授説のもとでは、王に逆らうことは神に逆らうこととされた。"},{"term":"ホッブズ","reading":"ほっぶず","meaning":"イギリスの思想家。著書『リヴァイアサン』で、自然状態を「万人の万人に対する闘争」と捉え、平和のために人々が契約で強大な権力を国家に委ねると説いた。","note":"社会契約説の思想家の一人。ロックやルソーとセットで、それぞれの結論の違いを押さえる。","example":"ホッブズは、争いを避けるために強大な国家権力が必要だと考えた。"},{"term":"ロック","reading":"ろっく","meaning":"イギリスの思想家。著書『統治二論』で社会契約説を説き、政府が人々の生命・自由・財産を守らない場合、人々には抵抗権があるとした。","note":"名誉革命を理論的に支えた思想家。抵抗権がキーワード。","example":"ロックの考えは、後のアメリカ独立宣言にも影響を与えた。"},{"term":"ルソー","reading":"るそー","meaning":"フランスの思想家。著書『社会契約論』で、主権は人民にあり、政治は人々全体の利益を目指す一般意志に基づいて行われるべきだと説いた。","note":"一般意志と結びつけて覚える。フランス革命に影響を与えた。","example":"ルソーは、主権は人民から離れることのないものだと説いた。"},{"term":"モンテスキュー","reading":"もんてすきゅー","meaning":"フランスの思想家。著書『法の精神』で、権力の集中を防ぐため、立法・行政・司法の三権に分ける権力分立を説いた。","note":"三権分立といえばモンテスキュー。著書名も一緒に覚える。","example":"モンテスキューの権力分立の考えは、各国の憲法に取り入れられた。"},{"term":"間接民主制","reading":"かんせつみんしゅせい","meaning":"国民が選挙で選んだ代表者を通じて政治を行う仕組み。議会制民主主義ともいう。","note":"国民が直接政治を行う直接民主制と対比して覚える。現代の多くの国で採用されている。","example":"日本は間接民主制をとり、国会議員が国民の代表として法律を作る。"}]},{"topic":"日本国憲法の基本原則","cards":[{"term":"国民主権","reading":"こくみんしゅけん","meaning":"国の政治のあり方を最終的に決める力は国民にあるという原則。","note":"日本国憲法の三つの基本原則の一つとして、前文と第1条に示される。","example":"国民主権のもとでは、選挙を通じて国民の意思が政治に反映される。"},{"term":"平和主義","reading":"へいわしゅぎ","meaning":"戦争や武力による争いを否定し、平和を守ろうとする原則。","note":"憲法第9条の戦争放棄と結びつき、日本国憲法を特徴づける原則。","example":"平和主義の考えから、日本は国際紛争を武力で解決しない立場をとる。"},{"term":"基本的人権の尊重","reading":"きほんてきじんけんのそんちょう","meaning":"すべての人の基本的人権を、侵すことのできない永久の権利として大切にする原則。","note":"三つの基本原則の一つで、憲法の多くの条文に具体化されている。","example":"基本的人権の尊重は、日本国憲法の基本原則の一つである。"},{"term":"象徴天皇制","reading":"しょうちょうてんのうせい","meaning":"天皇が日本国と国民統合の象徴とされ、国政に関する権能を持たない制度。","note":"国民主権と両立する形で憲法第1条に定められた仕組み。","example":"象徴天皇制のもとで、天皇は国事行為のみを行い、国政に関する権能を持たない。"},{"term":"立憲主義","reading":"りっけんしゅぎ","meaning":"憲法を最高の基準として権力を縛り、国民の権利を保障しようとする考え方。","note":"日本国憲法の基本原則を支える考えとして、法の支配と合わせて理解する。","example":"立憲主義に基づき、政治権力は憲法によって制限される。"},{"term":"最高法規","reading":"さいこうほうき","meaning":"憲法が国の法秩序の中で最も強い効力を持ち、他の法令は憲法に反してはならないこと。","note":"憲法第98条に定められ、違憲審査制の根拠にもなる。","example":"最高法規である憲法に反する法律は、効力を持たない。"},{"term":"プログラム規定説","reading":"ぷろぐらむきていせつ","meaning":"生存権について定めた憲法第25条は、国に努力目標を示したプログラム的な規定であり、国民が国に具体的な給付を直接請求する権利までは保障していないとする学説。","note":"生存権の法的性格をめぐる学説。学校レポートでも問われやすい用語。","example":"プログラム規定説に立つと、第25条だけを根拠に生活保護の給付額を争うことは難しいとされる。"},{"term":"公共の福祉","reading":"こうきょうのふくし","meaning":"社会全体の利益のこと。基本的人権も、他者の人権と衝突する場合などには、公共の福祉によって制約を受けることがある。","note":"憲法第12条・第13条などに登場する。人権の制約の根拠として押さえる。","example":"表現の自由も、公共の福祉に反する形で無制限に認められるわけではない。"},{"term":"硬性憲法","reading":"こうせいけんぽう","meaning":"改正に通常の法律よりも厳しい手続きを必要とする憲法。日本国憲法がその例である。","note":"通常の法律と同じ手続きで改正できる軟性憲法と対比して覚える。","example":"日本国憲法は硬性憲法であり、改正には国会の発議と国民投票が必要である。"},{"term":"政教分離","reading":"せいきょうぶんり","meaning":"国家と宗教を分離し、国が特定の宗教を優遇したり、宗教活動を行ったりすることを禁じる原則。","note":"憲法第20条の信教の自由とセットで覚える。","example":"政教分離の原則により、国は特定の宗教団体に特権を与えることができない。"},{"term":"生存権","reading":"せいぞんけん","meaning":"国民が健康で文化的な最低限度の生活を営む権利。憲法第25条に定められている社会権の一つ。","note":"プログラム規定説と関連づけて覚える。社会権の代表例。","example":"生存権を具体化する法律として、生活保護法が定められている。"},{"term":"文民統制","reading":"ぶんみんとうせい","meaning":"文民である政治家が軍隊や自衛隊を統制し、軍事が政治に優先することのないようにする仕組み。シビリアン・コントロールともいう。","note":"内閣総理大臣や防衛大臣が文民であることと結びつけて覚える。","example":"文民統制により、自衛隊は国民の代表である政治家のもとで運営される。"}]},{"topic":"国会・内閣・裁判所","cards":[{"term":"三権分立","reading":"さんけんぶんりつ","meaning":"立法・行政・司法の三つの権力を別々の機関に担わせ、互いにチェックさせる仕組み。","note":"国会・内閣・裁判所の関係を理解する全体の枠組みになる。","example":"三権分立により、国会・内閣・裁判所がそれぞれの役割を分担している。"},{"term":"国会","reading":"こっかい","meaning":"国民の代表である議員から成り、法律を作る国の唯一の立法機関。","note":"衆議院と参議院の二院制をとり、国権の最高機関とされる。","example":"国会は、国民の代表が集まって法律を作る機関である。"},{"term":"衆議院の優越","reading":"しゅうぎいんのゆうえつ","meaning":"衆参両院の意見が異なる場合に、一定の条件で衆議院の議決を優先する仕組み。","note":"任期が短く解散もある衆議院が、民意をより反映すると考えられるため認められる。","example":"衆議院の優越により、予算の先議権は衆議院にある。"},{"term":"内閣","reading":"ないかく","meaning":"行政権を担う機関で、内閣総理大臣と国務大臣から構成される。","note":"国会に対して連帯して責任を負う、議院内閣制の中心機関。","example":"内閣は、国会で作られた法律に基づいて行政を行う。"},{"term":"裁判所","reading":"さいばんしょ","meaning":"司法権を担い、法に基づいて紛争を解決し、法令の合憲性を審査する機関。","note":"最高裁判所と下級裁判所があり、司法権の独立が保障される。","example":"裁判所は、争いが起きたときに法に基づいて判断を下す。"},{"term":"議院内閣制","reading":"ぎいんないかくせい","meaning":"内閣が議会の信任に基づいて成立し、議会に責任を負う政治制度。","note":"日本やイギリスで採用され、大統領制と対比される。","example":"議院内閣制では、内閣は議会の信任に基づいて成立する。"},{"term":"二院制","reading":"にいんせい","meaning":"議会が二つの議院から構成される制度。日本では衆議院と参議院からなる国会がこれにあたる。","note":"慎重な審議や多様な意見の反映が利点。一院制と対比して覚える。","example":"日本が二院制をとるのは、法律の制定をより慎重に行うためでもある。"},{"term":"国政調査権","reading":"こくせいちょうさけん","meaning":"国会の各議院が、国政全般について調査を行うことができる権能。証人の出頭や記録の提出を求めることができる。","note":"憲法第62条に定められている。各議院が持つ点に注意。","example":"国会は国政調査権を使って、行政の問題を調べることができる。"},{"term":"弾劾裁判","reading":"だんがいさいばん","meaning":"国会に設けられる弾劾裁判所が、ふさわしくない行為をした裁判官を罷免するかどうかを判断する裁判。","note":"裁判官の独立を守るため、罷免には特別な手続きがとられる。","example":"弾劾裁判によって罷免された裁判官は、法曹資格を失う場合がある。"},{"term":"違憲審査制","reading":"いけんしんさせい","meaning":"裁判所が、法律や命令などが憲法に違反していないかを審査する制度。","note":"最高裁判所は「憲法の番人」と呼ばれる。付随的審査制という点も押さえる。","example":"違憲審査制のもとで、裁判所は憲法に反する法律を無効と判断できる。"},{"term":"衆議院の解散","reading":"しゅうぎいんのかいさん","meaning":"衆議院議員の任期が満了する前に、全議員の資格を失わせること。内閣の助言と承認により天皇が行う。","note":"解散後は40日以内に総選挙、選挙後は30日以内に国会召集という数字とセットで覚える。","example":"衆議院の解散が行われると、国民は選挙を通じて政治への意思を示す。"},{"term":"行政権","reading":"ぎょうせいけん","meaning":"法律に基づいて政治を行う権力で、日本では内閣に属する。三権分立の一つ。","note":"立法権は国会、司法権は裁判所に対応する。","example":"行政権を担う内閣は、国会に対して連帯して責任を負う。"}]},{"topic":"選挙と政党","cards":[{"term":"選挙の四原則","reading":"せんきょのよんげんそく","meaning":"普通・平等・直接・秘密の四つから成る、民主的な選挙の基本原則。","note":"誰が、どのように投票するかを定める土台として押さえる。","example":"選挙の四原則には、普通・平等・直接・秘密選挙がある。"},{"term":"小選挙区制","reading":"しょうせんきょくせい","meaning":"一つの選挙区から一人の当選者を出す選挙制度。","note":"大きな政党に有利で政権交代が起こりやすい一方、死票が多くなりやすい。","example":"小選挙区制では、各選挙区で最も多くの票を得た候補者が当選する。"},{"term":"比例代表制","reading":"ひれいだいひょうせい","meaning":"政党の得票率に応じて議席を配分する選挙制度。","note":"少数意見が反映されやすい反面、小党が乱立しやすい面がある。","example":"比例代表制では、政党の得票率に応じて議席が配分される。"},{"term":"小選挙区比例代表並立制","reading":"しょうせんきょくひれいだいひょうへいりつせい","meaning":"小選挙区制と比例代表制を組み合わせ、別々に投票して議席を決める日本の衆議院の制度。","note":"二つの制度の長所を取り入れようとする仕組みとして理解する。","example":"小選挙区比例代表並立制により、衆議院議員は二つの方法で選ばれる。"},{"term":"一票の格差","reading":"いっぴょうのかくさ","meaning":"選挙区によって一票の価値に差が生じる問題のこと。","note":"議員定数の配分が見直されないと広がり、法の下の平等との関係で問題になる。","example":"一票の格差が大きいと、選挙の平等が損なわれると指摘される。"},{"term":"与党と野党","reading":"よとうとやとう","meaning":"政権を担う政党を与党、政権の外から政府を監視・批判する政党を野党という。","note":"政党政治の中で、政権担当とチェック機能という役割の違いを示す。","example":"与党と野党は、国会で議論を重ねながら政策を決めていく。"},{"term":"ドント方式","reading":"どんとほうしき","meaning":"比例代表制で各政党の議席を配分する計算方法。各政党の得票数を1、2、3…と割っていき、商の大きい順に議席を配分する。","note":"日本の衆議院・参議院の比例代表制で採用されている。","example":"ドント方式によって、小政党にも得票に応じた議席が配分される。"},{"term":"死票","reading":"しひょう","meaning":"選挙で当選に結びつかなかった票のこと。落選した候補者への票などがこれにあたる。","note":"小選挙区制では死票が多くなりやすい点が課題とされる。","example":"小選挙区制では、2位以下の候補者への票がすべて死票となる。"},{"term":"重複立候補制度","reading":"ちょうふくりっこうほせいど","meaning":"衆議院選挙で、一人の候補者が小選挙区と比例代表の両方に同時に立候補できる制度。","note":"小選挙区で落選しても、比例代表で復活当選する場合がある。","example":"重複立候補制度により、小選挙区で敗れた候補者が比例代表で当選した。"},{"term":"マニフェスト","reading":"まにふぇすと","meaning":"政党が選挙の際に示す、具体的な数値目標や実施期限を明記した政策公約。政権公約ともいう。","note":"達成度を後から検証できる点が、従来の抽象的な公約との違い。","example":"有権者はマニフェストを比べて、どの政党に投票するか判断した。"},{"term":"政党交付金","reading":"せいとうこうふきん","meaning":"政党の活動を支えるため、国が政党に対して交付する資金。所属議員数や得票数に応じて配分される。","note":"企業・団体献金の問題と関連づけて覚える。政党助成制度ともいう。","example":"政党交付金は、政治資金の透明化を進める目的でも導入された。"},{"term":"世論","reading":"せろん","meaning":"政治や社会の問題について、多くの人々に共通する意見のこと。選挙や政治の動きに影響を与える。","note":"マスメディアやSNSが世論の形成に影響する点も押さえる。","example":"世論の動向を受けて、内閣の政策が見直されることがある。"}]},{"topic":"需要と供給","cards":[{"term":"需要","reading":"じゅよう","meaning":"ある価格のもとで、消費者が買おうとする財やサービスの量のこと。","note":"価格が下がると増える傾向があり、需要曲線で表される。","example":"価格が下がったことで、その商品への需要が増えた。"},{"term":"供給","reading":"きょうきゅう","meaning":"ある価格のもとで、生産者が売ろうとする財やサービスの量のこと。","note":"価格が上がると増える傾向があり、供給曲線で表される。","example":"豊作によって、野菜の供給が増えて価格が下がった。"},{"term":"均衡価格","reading":"きんこうかかく","meaning":"需要量と供給量がちょうど一致する価格のこと。","note":"市場で価格が落ち着く目安となり、需要・供給曲線の交点で決まる。","example":"市場では、需要と供給が一致する均衡価格で取引が行われる。"},{"term":"需要曲線","reading":"じゅようきょくせん","meaning":"価格と需要量の関係を表した曲線で、通常は右下がりになる。","note":"価格以外の条件が変わると曲線そのものが左右に移動する。","example":"需要曲線を描くと、価格と需要量の関係が一目で分かる。"},{"term":"供給曲線","reading":"きょうきゅうきょくせん","meaning":"価格と供給量の関係を表した曲線で、通常は右上がりになる。","note":"生産費用などの条件が変わると曲線そのものが移動する。","example":"供給曲線は、価格が上がるほど供給量が増える関係を示している。"},{"term":"価格の自動調節機能","reading":"かかくのじどうちょうせつきのう","meaning":"余りや不足が生じたときに価格が変動し、需要と供給を一致へ導く市場の働き。","note":"市場機構の基本として、均衡価格が決まる仕組みと結びつく。","example":"価格の自動調節機能が働き、品不足は価格の上昇によって解消された。"},{"term":"市場の失敗","reading":"しじょうのしっぱい","meaning":"市場メカニズムに任せるだけでは、資源が効率的に配分されなかったり、望ましくない結果が生じたりすること。","note":"独占、公共財、外部性などが原因となる。政府の介入の根拠として覚える。","example":"市場の失敗が起きる分野では、政府の政策による調整が必要になる。"},{"term":"独占","reading":"どくせん","meaning":"一つの企業だけが市場に商品を供給している状態。競争が働かないため、企業が価格を決める力を持つ。","note":"寡占と対比して覚える。供給する企業の数に注目する。","example":"独占状態では、企業が価格を引き上げても消費者は他の商品を選べない。"},{"term":"寡占","reading":"かせん","meaning":"少数の企業が市場の大部分を供給している状態。企業同士が互いの動きを意識して競争する。","note":"独占との違いは、供給する企業が少数か一つかという点。","example":"寡占市場では、一社の値下げが他社の値下げ競争を引き起こすことがある。"},{"term":"公共財","reading":"こうきょうざい","meaning":"料金を払わない人を排除することが難しく、多くの人が共同で利用できる財やサービス。道路や防衛などが例である。","note":"対価を払わずに利用する「ただ乗り（フリーライダー）」の問題とセットで覚える。","example":"公共財は市場では十分に供給されにくいため、政府が税金で提供する。"},{"term":"外部性","reading":"がいぶせい","meaning":"ある経済活動が、市場を通さずに第三者へ良い影響や悪い影響を与えること。良い影響を外部経済、悪い影響を外部不経済という。","note":"公害は外部不経済の代表例。市場の失敗の原因の一つ。","example":"工場の排煙による健康被害は、外部不経済の例である。"},{"term":"独占禁止法","reading":"どくせんきんしほう","meaning":"私的独占やカルテルなどの不当な取引制限を禁止し、公正で自由な競争を守るための法律。","note":"運用する機関は公正取引委員会。市場の失敗への対応策として覚える。","example":"企業同士が価格を取り決めるカルテルは、独占禁止法で禁止されている。"}]},{"topic":"金融のしくみ","cards":[{"term":"直接金融","reading":"ちょくせつきんゆう","meaning":"資金を必要とする者が、株式や債券を発行して投資家から直接資金を集める方法。","note":"証券市場を通じる方法で、間接金融と対比される。","example":"企業が株式を発行して資金を集めるのは、直接金融の例である。"},{"term":"間接金融","reading":"かんせつきんゆう","meaning":"銀行などの金融機関が預金を集め、それを企業などへ貸し出す形の資金の流れ。","note":"日本で中心的な役割を果たしてきた金融の仕組み。","example":"銀行が預金を集めて企業に貸し出すのは、間接金融の仕組みである。"},{"term":"日本銀行","reading":"にっぽんぎんこう","meaning":"日本の中央銀行で、紙幣の発行や物価の安定、金融システムの安定を担う機関。","note":"金融政策の実施主体として、このテーマの中心に置かれる。","example":"日本銀行は、物価の安定を目指して金融政策を行っている。"},{"term":"金融政策","reading":"きんゆうせいさく","meaning":"中央銀行が金利や資金量を調整して、景気や物価を安定させようとする政策。","note":"政策金利の操作が代表的な手段となる。","example":"金融政策によって、景気や物価の動きを調整する。"},{"term":"政策金利","reading":"せいさくきんり","meaning":"中央銀行が金融政策の目安として誘導する短期金利のこと。","note":"市中の金利全体に影響し、景気を冷やす・温める調整に使われる。","example":"政策金利の引き上げは、過熱した景気を抑える狙いがある。"},{"term":"株式","reading":"かぶしき","meaning":"株式会社が資金を集めるために発行する証券で、保有者は出資者として議決権などを持つ。","note":"直接金融の代表例であり、価格変動のリスクも伴う。","example":"株式を買った人は、その企業の株主として配当を受け取ることがある。"},{"term":"預金保険制度","reading":"よきんほけんせいど","meaning":"金融機関が破綻したときに、一定額までの預金を保護する仕組み。","note":"預金者の不安を抑え、金融システムの安定を守る役割を持つ。","example":"預金保険制度があるため、銀行が破たんしても一定額までの預金は保護される。"},{"term":"信用創造","reading":"しんようそうぞう","meaning":"銀行が貸し付けを行う過程で、預金通貨の総量がもとの預金よりも大きく増えていく仕組み。","note":"銀行の貸出が再び預金となる繰り返しで生じる。金融の重要概念。","example":"信用創造によって、銀行は経済全体の資金量を増やす役割を果たす。"},{"term":"公開市場操作","reading":"こうかいしじょうそうさ","meaning":"中央銀行が金融市場で国債などを売買し、市場の資金量や金利を調整する金融政策の手段。オペレーション（オペ）ともいう。","note":"売りオペは資金を吸収し、買いオペは資金を供給する。向きに注意。","example":"日本銀行は公開市場操作によって、政策金利の誘導を図っている。"},{"term":"債券","reading":"さいけん","meaning":"国や企業が資金を集めるために発行する借用証書のような有価証券。国が発行するものを国債、企業が発行するものを社債という。","note":"株式と違い、元本と利子が約束されている点が特徴。","example":"企業は債券を発行して、工場建設の資金を集めた。"},{"term":"金融機関","reading":"きんゆうきかん","meaning":"資金の貸し借りを仲介する機関の総称。銀行や信用金庫、保険会社、証券会社などが含まれる。","note":"日本銀行は中央銀行であり、一般の金融機関とは役割が異なる。","example":"金融機関は、預金者から集めた資金を企業への貸出に回している。"},{"term":"証券会社","reading":"しょうけんがいしゃ","meaning":"株式や債券などの売買を仲介する金融機関。投資家と証券市場をつなぐ役割を持つ。","note":"直接金融を支える機関として覚える。","example":"投資家は証券会社を通じて株式を売買する。"}]},{"topic":"財政のしくみ","cards":[{"term":"財政","reading":"ざいせい","meaning":"政府が税金などで収入を得て、公共サービスなどに支出する活動のこと。","note":"資源配分や所得再分配、景気安定という三つの役割が知られる。","example":"財政を通じて、政府は公共サービスを提供している。"},{"term":"直接税","reading":"ちょくせつぜい","meaning":"税を負担する人と納める人が同じ税で、所得税や法人税が代表例。","note":"所得に応じて負担を調整しやすく、累進課税と結びつきやすい。","example":"所得税は、税を負担する人が直接納める直接税である。"},{"term":"間接税","reading":"かんせつぜい","meaning":"税を負担する人と納める人が異なる税で、消費税が代表例。","note":"広く集めやすい一方、所得の低い人ほど負担感が重くなる面がある。","example":"消費税は、負担する人と納める人が異なる間接税である。"},{"term":"累進課税","reading":"るいしんかぜい","meaning":"所得が高くなるほど高い税率が適用される課税の仕方。","note":"所得の再分配を進める仕組みとして、所得税に採用されている。","example":"累進課税では、所得が多い人ほど高い税率が適用される。"},{"term":"予算","reading":"よさん","meaning":"政府の一年間の収入と支出の計画で、国会の議決を経て成立するもの。","note":"財政を民主的にコントロールするための重要な手続き。","example":"予算は、内閣が作成し、国会の議決を経て成立する。"},{"term":"公債","reading":"こうさい","meaning":"政府が資金不足を補うために発行する借金の証書で、国が発行するものは国債と呼ばれる。","note":"将来世代への負担の問題と合わせて、財政健全化の文脈で扱われる。","example":"政府は財源不足を補うため、公債を発行することがある。"},{"term":"歳入","reading":"さいにゅう","meaning":"国や地方公共団体の1年間の収入のこと。租税収入や公債金収入などからなる。","note":"支出を表す歳出と対で覚える。","example":"国の歳入の中心は、所得税や法人税、消費税などの租税である。"},{"term":"歳出","reading":"さいしゅつ","meaning":"国や地方公共団体の1年間の支出のこと。社会保障関係費や公共事業関係費などからなる。","note":"収入を表す歳入と対で覚える。","example":"歳出の中で最も大きな割合を占めるのは社会保障関係費である。"},{"term":"租税法律主義","reading":"そぜいほうりつしゅぎ","meaning":"税は法律に基づいてのみ課すことができるという原則。憲法第84条に定められている。","note":"国民の代表である国会が法律で決める点がポイント。","example":"租税法律主義により、政府が勝手に新しい税を作ることはできない。"},{"term":"財政投融資","reading":"ざいせいとうゆうし","meaning":"郵便貯金や年金積立金などを原資として、政府が政策目的のために行う投融資活動。「第二の予算」とも呼ばれる。","note":"一般会計の予算と区別して覚える。","example":"財政投融資は、道路や住宅などの社会資本の整備に使われてきた。"},{"term":"地方交付税","reading":"ちほうこうふぜい","meaning":"地方公共団体間の財政力の格差を調整し、どの地域でも一定の行政サービスが提供できるよう、国が使い道を定めずに交付する資金。","note":"使い道が指定される国庫支出金と対比して覚える。","example":"地方交付税によって、税収の少ない自治体でも行政サービスを維持できる。"},{"term":"国債費","reading":"こくさいひ","meaning":"国の歳出のうち、発行した国債の元本の返済や利子の支払いに充てられる費用。","note":"公債（国債）の発行が増えると国債費も増え、財政を圧迫する。","example":"国債費の増加により、政策に使える財源が限られてきている。"}]},{"topic":"日本経済の発展と課題","cards":[{"term":"高度経済成長","reading":"こうどけいざいせいちょう","meaning":"1950年代半ばから1970年代初めにかけて、日本経済が急速に拡大した時期のこと。","note":"所得の増加と生活の変化をもたらした、日本経済の転機として扱われる。","example":"高度経済成長の時期、日本の工業生産は急速に拡大した。"},{"term":"バブル経済","reading":"ばぶるけいざい","meaning":"地価や株価が実体以上に膨らみ、その後急激に崩れた1980年代末前後の経済状況。","note":"その崩壊後の長期停滞が、その後の日本経済の課題につながった。","example":"バブル経済の時期には、地価や株価が実態以上に上昇した。"},{"term":"中小企業","reading":"ちゅうしょうきぎょう","meaning":"規模の小さい企業の総称で、日本の企業数の大半を占める。","note":"大企業との格差や人手不足などが課題として取り上げられる。","example":"中小企業は、地域の雇用を支える大切な存在である。"},{"term":"雇用と労働問題","reading":"こようとろうどうもんだい","meaning":"非正規雇用の増加や長時間労働、賃金の伸び悩みなど、働く人をめぐる課題の総称。","note":"少子高齢化や働き方改革の議論と結びつけて理解する。","example":"雇用と労働問題の解決には、働き方の見直しが求められている。"},{"term":"社会保障制度","reading":"しゃかいほしょうせいど","meaning":"病気や老齢、失業などのリスクに備え、国が生活を支える仕組みの総称。","note":"年金・医療・介護・生活保護などが柱となり、財政との関係も重要。","example":"社会保障制度は、病気や失業などの際の生活を支えている。"},{"term":"少子高齢化","reading":"しょうしこうれいか","meaning":"出生数が減り、高齢者の割合が高まる人口構造の変化のこと。","note":"社会保障の担い手不足という課題を通じて、日本経済全体に影響する。","example":"少子高齢化が進み、社会保障の負担のあり方が課題となっている。"},{"term":"石油危機","reading":"せきゆきき","meaning":"1970年代に、第四次中東戦争などをきっかけに原油価格が急騰し、世界経済が混乱した出来事。オイルショックともいう。","note":"1973年の第一次石油危機で日本の高度経済成長が終わった流れを押さえる。","example":"石油危機の後、日本では省エネルギーの技術開発が進んだ。"},{"term":"四大公害病","reading":"よんだいこうがいびょう","meaning":"高度経済成長期に発生した、水俣病、新潟水俣病、イタイイタイ病、四日市ぜんそくの四つの公害病の総称。","note":"それぞれの発生地と原因物質を組み合わせて覚える。","example":"四大公害病の裁判では、被害者である住民側が勝訴した。"},{"term":"労働基準法","reading":"ろうどうきじゅんほう","meaning":"労働時間や休日、賃金など、労働条件の最低基準を定めた法律。労働三法の一つ。","note":"労働組合法、労働関係調整法と合わせて労働三法と呼ばれる。","example":"労働基準法により、労働時間は原則として1日8時間までと定められている。"},{"term":"非正規雇用","reading":"ひせいきこよう","meaning":"パート、アルバイト、派遣社員、契約社員など、正社員以外の雇用形態で働くこと。","note":"雇用の不安定さや賃金の低さが課題。ワーキングプアとも関連する。","example":"非正規雇用で働く人の割合は、近年増加傾向にある。"},{"term":"公的年金","reading":"こうてきねんきん","meaning":"国が運営する年金制度。現役世代が納めた保険料で高齢者の年金を支える賦課方式を基本としている。","note":"国民年金と厚生年金の二階建ての仕組みを押さえる。","example":"公的年金は、高齢者の生活を支える社会保障の柱である。"},{"term":"介護保険","reading":"かいごほけん","meaning":"40歳以上の人が保険料を負担し、介護が必要になったときに介護サービスを受けられる社会保険制度。2000年に始まった。","note":"医療保険や年金と並ぶ社会保険の一つ。運営主体は市町村。","example":"介護保険を利用して、訪問介護のサービスを受ける高齢者が増えている。"}]},{"topic":"国際政治と国際連合","cards":[{"term":"国際法","reading":"こくさいほう","meaning":"国家間の関係を規律する法で、条約や国際慣習法などから成る。","note":"国内法と違い強制力に限界がある点が、国際政治の特質と関わる。","example":"国際法は、国家同士の関係を規律する法である。"},{"term":"国際連合","reading":"こくさいれんごう","meaning":"第二次世界大戦後に設立された、世界の平和と安全、国際協力を目的とする国際機関。","note":"総会や安全保障理事会などの機関から成り、国際政治の中心舞台となる。","example":"国際連合は、世界の平和と安全の維持を目的とする機関である。"},{"term":"安全保障理事会","reading":"あんぜんほしょうりじかい","meaning":"国際の平和と安全の維持に主要な責任を持つ、国連の機関の一つ。","note":"常任理事国に拒否権があることが、大きな特徴であり課題でもある。","example":"安全保障理事会は、国際の平和と安全の維持に主要な責任を負う。"},{"term":"常任理事国","reading":"じょうにんりじこく","meaning":"安全保障理事会に常時加わる五つの国で、決議への拒否権を持つ。","note":"国連が大国の協力なしには機能しにくい仕組みを示す存在。","example":"常任理事国には、アメリカや中国など五つの国がある。"},{"term":"PKO","reading":"ぴーけーおー","meaning":"停戦の監視や治安維持などを担う国連平和維持活動の略称。","note":"紛争地域で中立的に活動する仕組みとして、国連の役割を具体化する。","example":"PKOに参加する自衛隊は、現地で道路の整備などを行った。"},{"term":"拒否権","reading":"きょひけん","meaning":"安全保障理事会の常任理事国が、決議案に反対して成立を止められる権利。","note":"大国同士の対立があると国連が動けなくなる原因として議論される。","example":"常任理事国が拒否権を行使すると、決議案は成立しない。"},{"term":"集団安全保障","reading":"しゅうだんあんぜんほしょう","meaning":"加盟国が共同で平和を守る仕組み。平和を破壊する国があれば、他の加盟国が協力して制裁や軍事的措置をとる。","note":"国際連合の基本的な考え方。集団的自衛権とは区別する。","example":"国際連合は集団安全保障の考え方に基づいて設立された。"},{"term":"国際連盟","reading":"こくさいれんめい","meaning":"第一次世界大戦後に設立された、世界平和を目指す最初の国際機関。大国の不参加や全会一致の原則などに課題があり、第二次世界大戦を防げなかった。","note":"国際連合の前身。設立は1920年、本部はジュネーブ。","example":"国際連盟にはアメリカが参加せず、その影響力には限界があった。"},{"term":"国連総会","reading":"こくれんそうかい","meaning":"すべての加盟国が参加し、各国1票の投票権を持つ国際連合の主要機関。決議は原則として勧告的な性質を持つ。","note":"安全保障理事会と違い、全加盟国が参加する点が特徴。","example":"国連総会では、環境問題や人権問題など幅広い議題が話し合われる。"},{"term":"国際司法裁判所","reading":"こくさいしほうさいばんしょ","meaning":"国家間の紛争を国際法に基づいて裁判で解決する国際連合の司法機関。オランダのハーグに置かれている。","note":"所在地のハーグとセットで覚える。裁判を受け入れるかどうかは国の同意が原則。","example":"国際司法裁判所は、国境をめぐる国家間の争いを裁定した。"},{"term":"事務総長","reading":"じむそうちょう","meaning":"国際連合の事務局の代表者。安全保障理事会の勧告に基づき、総会が任命する。","note":"国連の行政の長であり、国際会議などで国連を代表する。","example":"事務総長は、紛争の平和的解決のために各国へ働きかけを行った。"},{"term":"主権","reading":"しゅけん","meaning":"国家が自国の領土や国民を統治する最高の権力。国際社会では、すべての国家が主権を持つ平等な存在とされる。","note":"国内政治の国民主権とは文脈が異なる。主権平等が国際社会の原則。","example":"国際社会では、各国の主権を尊重し合うことが基本原則となっている。"}]},{"topic":"国際経済とグローバル化","cards":[{"term":"比較優位","reading":"ひかくゆうい","meaning":"各国が相対的に得意な財の生産に特化し貿易することで、全体の利益が増えるという考え方。","note":"貿易がなぜ利益を生むのかを説明する、国際経済の基本理論。","example":"比較優位の考え方によれば、各国が得意な財の生産に特化すると利益が増える。"},{"term":"国際収支","reading":"こくさいしゅうし","meaning":"一定期間に一国と外国との間で行われた経済取引をまとめた記録のこと。","note":"経常収支や資本収支などから、国の対外的な経済関係が分かる。","example":"国際収支の統計を見ると、その国の対外取引の様子が分かる。"},{"term":"為替相場","reading":"かわせそうば","meaning":"異なる通貨を交換するときの比率のこと。","note":"円高・円安の変動を通じて、輸出入や物価に影響を与える。","example":"為替相場の変動は、輸出企業の業績に影響を与える。"},{"term":"IMF","reading":"あいえむえふ","meaning":"国際通貨基金の略称で、為替の安定や国際収支に困る国への融資を行う国際機関。","note":"世界銀行とともに、戦後の国際経済体制を支える機関の一つ。","example":"IMFは、国際収支が悪化した国への融資などを行っている。"},{"term":"世界銀行","reading":"せかいぎんこう","meaning":"発展途上国への長期の融資や技術支援を行い、開発を助ける国際機関。","note":"貧困削減を目的とし、IMFとは役割の重点が異なる。","example":"世界銀行は、発展途上国の開発事業に長期の融資を行っている。"},{"term":"WTO","reading":"だぶりゅーてぃーおー","meaning":"世界貿易機関の略称で、自由貿易のルール作りと貿易紛争の解決を担う機関。","note":"GATTを引き継いで設立され、グローバル化のルール面を支える。","example":"WTOでは、貿易をめぐる国同士の争いを解決する手続きが定められている。"},{"term":"GATT","reading":"がっと","meaning":"関税と貿易に関する一般協定の略称で、関税引き下げなどを進めた戦後の貿易の枠組み。","note":"後にWTOへ発展した経緯を押さえることで、自由貿易の流れが分かる。","example":"GATTのもとで関税の引き下げ交渉が重ねられ、世界貿易が拡大した。"},{"term":"経常収支","reading":"けいじょうしゅうし","meaning":"国際収支のうち、貿易・サービス収支や第一次所得収支などを合計した、モノやサービス、投資収益の取引による収支。","note":"貿易収支を含む広い概念である点に注意。","example":"日本の経常収支は、第一次所得収支の黒字に支えられて黒字が続いている。"},{"term":"貿易収支","reading":"ぼうえきしゅうし","meaning":"財（モノ）の輸出額から輸入額を差し引いた収支。経常収支を構成する項目の一つ。","note":"サービスは含まない点が経常収支との違い。","example":"エネルギー資源の輸入が増えると、貿易収支は赤字になりやすい。"},{"term":"FTA","reading":"えふてぃーえー","meaning":"自由貿易協定。特定の国や地域との間で、関税の撤廃や削減などを取り決めた協定。","note":"EPA（経済連携協定）より範囲が狭く、貿易の自由化が中心。","example":"FTAの発効により、相手国への輸出品にかかる関税が下がった。"},{"term":"EPA","reading":"いーぴーえー","meaning":"経済連携協定。関税の撤廃・削減に加え、投資や人の移動、知的財産など幅広い分野での連携を取り決めた協定。","note":"FTAを含む、より広い協定として覚える。","example":"EPAに基づいて、外国人材が看護や介護の分野で受け入れられている。"},{"term":"ブレトンウッズ体制","reading":"ぶれとんうっずたいせい","meaning":"第二次世界大戦後に作られた国際経済体制。ドルを中心とする固定相場制をとり、IMFと世界銀行が設立された。","note":"1971年のドルショックで崩壊し、変動相場制へ移行した流れを押さえる。","example":"ブレトンウッズ体制のもとで、戦後の世界貿易は大きく拡大した。"}]}]},{"subject":"情報","topics":[{"topic":"情報社会と法律","cards":[{"term":"個人情報","reading":"こじんじょうほう","meaning":"氏名や住所、生年月日など、特定の個人を識別できる情報のこと。生きている個人に関する情報が対象になる。","note":"このテーマでは、本人の同意なく集めたり他人に渡したりしないことが大切な情報として扱う。","example":"個人情報である氏名と住所を、本人の同意なく公開してはいけない。"},{"term":"著作権","reading":"ちょさくけん","meaning":"小説や音楽、写真、プログラムなどの創作物を創った人に認められる権利。許可なくコピーや公開をされないよう守る仕組みである。","note":"知的財産権の一つで、ネット上の文章や画像を使うときのルールの中心になる。","example":"自分で描いたイラストには著作権があり、無断で転載されないよう守られている。"},{"term":"知的財産権","reading":"ちてきざいさんけん","meaning":"人の創作や発明など、形のない知的成果を財産として守る権利の総称。著作権のほか特許権や商標権などが含まれる。","note":"情報社会で創作活動を支える大きな枠組みとして、著作権の上位の考え方に位置づく。","example":"発明や作品などの知的創作を守る知的財産権には、著作権や特許権が含まれる。"},{"term":"情報モラル","reading":"じょうほうもらる","meaning":"情報社会で安全に、相手を傷つけずに行動するために必要な判断力や心構えのこと。法律以前のマナーや配慮も含む。","note":"SNSの投稿や転送の場面で、法律とあわせて行動を考える基準になる。","example":"情報モラルを守り、SNSでは相手を傷つける言葉を使わないようにした。"},{"term":"フェイクニュース","reading":"ふぇいくにゅーす","meaning":"事実でないのに本当の報道のように見せかけた、うその情報のこと。注目を集めたり人をだましたりする目的で広まることがある。","note":"出典や他の報道と比べるなど、情報の確かさを確かめる姿勢が求められる例である。","example":"フェイクニュースかどうかを、他の信頼できる情報源でも確認してから判断した。"},{"term":"デジタルデバイド","reading":"でじたるでばいど","meaning":"パソコンやインターネットを使える人と使えない人の間に生じる、情報や機会の格差のこと。","note":"情報社会の便利さが一部の人に偏らないようにするための課題として取り上げる。","example":"高齢者と若者の間で生じるデジタルデバイドを解消するため、使い方の講習会が開かれた。"},{"term":"肖像権","reading":"しょうぞうけん","meaning":"自分の顔や姿を無断で撮影されたり公開されたりしない権利のこと。","note":"プライバシーの権利と混同しやすいが、こちらは容姿そのものに注目する。","example":"許可なく撮った写真をSNSに載せると、肖像権の侵害になることがある。"},{"term":"プライバシー権","reading":"ぷらいばしーけん","meaning":"私生活をみだりに公開されない権利のこと。","note":"個人情報保護とは重なる部分が大きいが、より広く私生活全体を守る考え方。","example":"他人の日記の内容を勝手に公開することは、プライバシー権の侵害になりうる。"},{"term":"産業財産権","reading":"さんぎょうざいさんけん","meaning":"特許権・実用新案権・意匠権・商標権の総称で、産業分野の創作や標識を保護する権利。","note":"著作権と合わせて知的財産権を構成する。特許は発明、商標はマークと結びつける。","example":"新しく開発した技術について特許権を取得し、産業財産権として保護した。"},{"term":"著作者人格権","reading":"ちょさくしゃじんかくけん","meaning":"著作者の人格的な利益を守る権利で、公表権・氏名表示権・同一性保持権からなる。","note":"財産権である著作権と違い、他人に譲渡できない点が重要。","example":"著作者人格権があるため、作品を勝手に改変して公開することはできない。"},{"term":"フィッシング","reading":"ふぃっしんぐ","meaning":"実在の企業などを装った偽のメールやサイトで、パスワードやカード番号などをだまし取る手口。","note":"釣り（フィッシング）のようにだますイメージで覚える。送信元を必ず確認する。","example":"銀行を名乗るメールで暗証番号を入力させるのは、典型的なフィッシングである。"},{"term":"ソーシャルエンジニアリング","reading":"そーしゃるえんじにありんぐ","meaning":"人の心理的な隙やミスにつけ込み、パスワードなどの情報を聞き出す手口。","note":"技術的な攻撃ではなく、人をだます点が特徴。肩越しに画面をのぞく行為も含まれる。","example":"電話で管理者を装ってパスワードを聞き出すのは、ソーシャルエンジニアリングの一例である。"}]},{"topic":"2進数と情報量","cards":[{"term":"2進数","reading":"にしんすう","meaning":"0と1の2種類の数字だけを使って数を表す方法。コンピュータ内部の計算や記録はこの表し方を基本にしている。","note":"ふだん使う10進数と変換し合うことが、このテーマの計算の中心になる。","example":"コンピュータは、すべてのデータを0と1だけを使う2進数で処理している。"},{"term":"ビット","reading":"びっと","meaning":"情報量の最小の単位。0か1かのどちらか一方を表すことができ、データの大きさを数える土台になる。","note":"バイトを構成する小さな単位で、2進数の1桁と対応している。","example":"1ビットでは、0か1かの2通りの情報を表すことができる。"},{"term":"バイト","reading":"ばいと","meaning":"8ビットをひとまとめにした情報量の単位。英数字1文字分程度のデータを表す目安として使われる。","note":"ファイルの大きさはキロバイトやメガバイトなど、バイトを基準に表すことが多い。","example":"この画像ファイルの大きさは、約500キロバイトだった。"},{"term":"16進数","reading":"じゅうろくしんすう","meaning":"0から9とAからFまでの16種類の記号で数を表す方法。長い2進数を短く分かりやすく書き換えるために使う。","note":"2進数の4桁が16進数の1桁に対応するため、色の指定やアドレス表示でよく見かける。","example":"2進数の長い並びを短く表すために、16進数が使われることがある。"},{"term":"文字コード","reading":"もじこーど","meaning":"文字と数値の対応を決めた取り決めのこと。コンピュータは決められた数値に置き換えて文字を処理している。","note":"同じ数値でも規格が違うと別の文字になるため、文字化けの原因を考える手がかりになる。","example":"文字コードによって、文字と数値の対応が決められている。"},{"term":"デジタル化","reading":"でじたるか","meaning":"音や画像、文字などの情報を数値に変換してコンピュータで扱える形にすること。","note":"情報を正確に複製したり加工したりしやすくなる、この単元全体の出発点になる考え方である。","example":"紙のアンケート結果をデジタル化して、コンピュータで集計できるようにした。"},{"term":"アナログ","reading":"あなろぐ","meaning":"連続的に変化する量で情報を表す方法。温度計の水銀の伸びなどが例である。","note":"デジタルは段階的に区切られた値で表す方法。対比して覚える。","example":"アナログ時計は、針の位置が連続的に動いて時刻を示す。"},{"term":"標本化","reading":"ひょうほんか","meaning":"アナログ信号を一定の時間間隔で測定し、その値を取り出す処理。サンプリングともいう。","note":"デジタル化の3ステップの最初。間隔が短いほど元の音に近づく。","example":"音を標本化するとき、1秒間に何回測定するかを決める。"},{"term":"量子化","reading":"りょうしか","meaning":"標本化で得た値を、決められた段階の数値に近づける処理。","note":"デジタル化の2番目のステップ。段階が多いほど細かく表せる。","example":"量子化の段階を増やすと、音の大きさをより細かく記録できる。"},{"term":"符号化","reading":"ふごうか","meaning":"量子化で得た数値を2進数に変換する処理。","note":"デジタル化の最後のステップ。標本化→量子化→符号化の順序を覚える。","example":"符号化された音声データは、0と1の並びとして保存される。"},{"term":"キロバイト","reading":"きろばいと","meaning":"情報量の単位で、1キロバイトは1024バイトである。","note":"1バイトは8ビット。キロは本来1000だが情報量では1024で計算する。","example":"このテキストファイルの大きさは約10キロバイトだった。"},{"term":"解像度","reading":"かいぞうど","meaning":"画像を構成する点（画素）の細かさを表す度合い。画素数が多いほどきめ細かい画像になる。","note":"解像度が高いほどデータ量も大きくなる点に注意する。","example":"解像度の高い写真は、拡大しても細部がはっきり見える。"}]},{"topic":"情報デザインとメディア","cards":[{"term":"情報デザイン","reading":"じょうほうでざいん","meaning":"伝えたい内容を受け手に分かりやすく届くよう、情報の内容や見せ方、流れを工夫して設計すること。","note":"見た目の飾りだけでなく、何をどの順で伝えるかまで含めた全体の設計を指す。","example":"情報デザインを工夫して、案内板の文字を大きく分かりやすくした。"},{"term":"ユニバーサルデザイン","reading":"ゆにばーさるでざいん","meaning":"年齢や障がいの有無などにかかわらず、できるだけ多くの人が使いやすいように製品や情報を設計する考え方。","note":"情報デザインでは、誰もが内容を受け取れるようにする視点として位置づく。","example":"ユニバーサルデザインの考え方で、誰でも押しやすいボタンを採用した。"},{"term":"配色","reading":"はいしょく","meaning":"使う色の組み合わせや使い方のこと。色の対比や明るさの差によって、読みやすさや印象が大きく変わる。","note":"背景と文字の色の組み合わせは、可読性を左右する具体的な工夫の一つである。","example":"ポスターの配色を青と白に統一すると、すっきりした印象になった。"},{"term":"可読性","reading":"かどくせい","meaning":"文字や文章がどれだけ読みやすいかを表す性質。文字の大きさや行間、色の対比などが影響する。","note":"受け手が無理なく内容を読み取れるかどうかを判断する物差しになる。","example":"文字の大きさと行間を調整して、資料の可読性を高めた。"},{"term":"メディアの特性","reading":"めでぃあのとくせい","meaning":"新聞、テレビ、ウェブなど、情報を伝える手段ごとに異なる届き方や得意・不得意のこと。","note":"伝えたい内容に合った手段を選ぶために、比較して考える対象になる。","example":"メディアの特性を考え、速報にはインターネット、記録には紙を選んだ。"},{"term":"情報の流れの設計","reading":"じょうほうのながれのせっけい","meaning":"受け手がどの順番で情報に触れ、どう理解していくかを考えて、画面や資料の構成を組み立てること。","note":"見出しやボタンの配置など、迷わず目的にたどり着くための工夫に結びつく。","example":"情報の流れの設計として、まず概要を示してから詳しい説明に入る順序にした。"},{"term":"ピクトグラム","reading":"ぴくとぐらむ","meaning":"言葉を使わず、絵や図で意味を伝える視覚記号。非常口のマークなどが例である。","note":"国や言葉が違っても伝わる点が強み。レポートでも頻出の用語。","example":"駅のピクトグラムを見れば、トイレの場所がすぐに分かる。"},{"term":"アクセシビリティ","reading":"あくせしびりてぃ","meaning":"年齢や障がいの有無にかかわらず、情報やサービスを利用しやすい度合いのこと。","note":"ユニバーサルデザインと関連が深い。音声読み上げへの対応などが例。","example":"アクセシビリティに配慮し、Webページに音声読み上げ対応の文字情報を付けた。"},{"term":"コントラスト","reading":"こんとらすと","meaning":"文字と背景など、色の明暗や色相の差のこと。差が大きいほど文字が読みやすくなる。","note":"可読性を高める工夫の一つ。差が小さすぎると読みにくい。","example":"白い背景に薄い灰色の文字ではコントラストが低く、読みにくい。"},{"term":"フォント","reading":"ふぉんと","meaning":"文字の形のデザイン（書体）と大きさなどの組み合わせを指す言葉。","note":"明朝体は横線が細く、ゴシック体は線の太さがほぼ均一という違いがある。","example":"見出しには太いフォントを使い、本文と区別した。"},{"term":"レイアウト","reading":"れいあうと","meaning":"文字や画像などの要素を、紙面や画面上に配置すること。","note":"配置の工夫で情報の伝わりやすさが大きく変わる。余白も大切な要素。","example":"レイアウトを整えたことで、ポスターの情報が読みやすくなった。"},{"term":"階層構造","reading":"かいそうこうぞう","meaning":"情報を大見出し・中見出しのように段階に分けて整理する構造。","note":"木のようなツリー構造でイメージすると分かりやすい。","example":"レポートを階層構造で整理すると、読み手が全体の流れをつかみやすい。"}]},{"topic":"アルゴリズムとプログラミング","cards":[{"term":"アルゴリズム","reading":"あるごりずむ","meaning":"問題を解くための手順を、順序立てて明確に表したもの。同じ手順をたどれば誰でも同じ結果にたどり着く。","note":"プログラムを作る前に考える、処理の設計図にあたる中心的な考え方である。","example":"料理のレシピも、手順が決まっているという点ではアルゴリズムの一例といえる。"},{"term":"順次・分岐・反復","reading":"じゅんじ・ぶんき・はんぷく","meaning":"処理を上から順に行う順次、条件で進み方を変える分岐、同じ処理を繰り返す反復のこと。この3つで基本的な処理を組み立てられる。","note":"フローチャートの記号と対応し、アルゴリズムを表す基本の3構造として学ぶ。","example":"プログラムは、順次・分岐・反復の組み合わせで処理の流れを作る。"},{"term":"フローチャート","reading":"ふろーちゃーと","meaning":"処理の流れを、決められた形の記号と矢印で図に表したもの。分岐や繰り返しも視覚的に追える。","note":"アルゴリズムを他の人に伝えたり、間違いを見つけたりするときに使う表現方法である。","example":"処理の流れをフローチャートに描くと、手順の抜けに気づきやすくなった。"},{"term":"変数","reading":"へんすう","meaning":"プログラムの中で数値や文字などのデータを一時的に入れておく、名前の付いた箱のようなもの。","note":"計算の途中結果を保持し、繰り返しや分岐の処理で使い回す役割を持つ。","example":"変数に途中までの合計を入れておき、最後に平均を計算した。"},{"term":"探索","reading":"たんさく","meaning":"たくさんのデータの中から、目的のデータを見つけ出す処理のこと。端から順に調べる方法や、半分ずつ絞る方法がある。","note":"整列と並んで、データ処理の代表的なアルゴリズムとして効率の違いを比べる。","example":"名簿の中から目的の名前を探す探索を、プログラムで自動化した。"},{"term":"整列（ソート）","reading":"せいれつ（そーと）","meaning":"データを小さい順や大きい順など、決めた順番に並べ替える処理のこと。ソートとも呼ばれる。","note":"並べ替え方によって処理の速さが変わるため、アルゴリズムの効率を考える題材になる。","example":"整列（ソート）を行うと、成績データを点数の高い順に並べ替えることができる。"},{"term":"線形探索","reading":"せんけいたんさく","meaning":"データの先頭から順番に1つずつ調べて目的のデータを探す方法。","note":"単純だがデータが多いと時間がかかる。二分探索と対比される。","example":"線形探索では、名簿の先頭から順に名前を確認していく。"},{"term":"二分探索","reading":"にぶんたんさく","meaning":"整列済みのデータの中央と比べて範囲を半分ずつ狭めながら探す方法。","note":"あらかじめデータが順番に並んでいることが条件。線形探索より速い。","example":"二分探索を使うと、辞書から目的の単語を素早く見つけられる。"},{"term":"バブルソート","reading":"ばぶるそーと","meaning":"隣り合うデータを比べて順序が逆なら入れ替える操作を繰り返す整列方法。","note":"泡が浮かび上がるように大きな値が端へ移動するイメージ。","example":"バブルソートでテストの点数を小さい順に並べ替えた。"},{"term":"配列","reading":"はいれつ","meaning":"同じ種類のデータを順番に並べてまとめて扱う仕組み。番号（添字）で各要素を指定する。","note":"変数が1つの箱なら、配列は仕切り付きの箱の列と考える。","example":"配列に1週間分の気温を入れて、平均を計算した。"},{"term":"代入","reading":"だいにゅう","meaning":"変数に値を入れる操作。新しい値を入れると、もとの値は上書きされる。","note":"数学の等号とは意味が違い、「入れる」向きがある点に注意する。","example":"変数xに5を代入すると、xの中身は5になる。"},{"term":"デバッグ","reading":"でばっぐ","meaning":"プログラムの誤り（バグ）を見つけて修正する作業。","note":"バグは虫の意味。実行結果がおかしいときは原因を順に確かめる。","example":"デバッグを繰り返して、計算結果の誤りを直した。"}]},{"topic":"モデル化とシミュレーション","cards":[{"term":"モデル化","reading":"もでるか","meaning":"現実の物事から必要な要素だけを取り出し、単純化して表すこと。複雑な現象を扱いやすくするための工夫である。","note":"シミュレーションを行う前提として、最初に行う作業に位置づく。","example":"現実の渋滞をモデル化して、信号の間隔を変えた場合の影響を調べた。"},{"term":"シミュレーション","reading":"しみゅれーしょん","meaning":"モデルを使って、現実の現象をコンピュータ上などで再現し、試しに動かしてみること。模擬実験ともいえる。","note":"実際には試しにくい条件を変えて結果を比べられる点が、このテーマの強みである。","example":"シミュレーションによって、実際に試す前に結果の予測ができた。"},{"term":"乱数","reading":"らんすう","meaning":"規則性なく現れる数の列のこと。くじ引きや確率的な現象をモデルで再現するときに使う。","note":"確率的なモデルで、偶然に左右される現象を扱うための道具になる。","example":"サイコロの代わりに乱数を使って、確率の実験をコンピュータで行った。"},{"term":"モデルの仮定","reading":"もでるのかてい","meaning":"モデルを作るときに置く前提や割り切りのこと。何を省略し、何を単純化したかを示すものである。","note":"結果が現実とずれる理由を考えるとき、まず見直すべき点として扱う。","example":"モデルの仮定として、歩く速さは全員同じであると決めて計算した。"},{"term":"結果の検証","reading":"けっかのけんしょう","meaning":"シミュレーションで得られた結果が、現実のデータや予想と合っているかを確かめること。","note":"モデルや仮定を見直すきっかけになり、シミュレーションの最後の大事な手順である。","example":"結果の検証では、シミュレーションの値と実際の測定値を比べた。"},{"term":"確率的なモデル","reading":"かくりつてきなもでる","meaning":"偶然の要素を取り入れて、結果が確率で変わる現象を表したモデルのこと。行列の待ち時間などの再現に使われる。","note":"乱数を使って何度も試し、傾向をつかむ使い方と結びついて学ぶ。","example":"くじ引きのような偶然を含む現象は、確率的なモデルで表すことができる。"},{"term":"抽象化","reading":"ちゅうしょうか","meaning":"物事の大切な要素だけを取り出し、細部を省略して単純化すること。","note":"モデル化の中心となる考え方。地図は現実を抽象化した例。","example":"抽象化によって、複雑な交通の流れを扱いやすいモデルにした。"},{"term":"モンテカルロ法","reading":"もんてかろほう","meaning":"乱数をたくさん使って試行を繰り返し、確率や面積などを近似的に求める方法。","note":"サイコロを何度も振るイメージ。回数が多いほど精度が上がる。","example":"モンテカルロ法で、円の面積を乱数を使って近似した。"},{"term":"決定論的モデル","reading":"けっていろんてきもでる","meaning":"同じ条件なら毎回同じ結果になるモデル。乱数を使わない。","note":"乱数を使う確率的なモデルと対比して覚える。","example":"決定論的モデルでは、初期条件が同じなら結果も毎回同じになる。"},{"term":"パラメータ","reading":"ぱらめーた","meaning":"モデルの動きを決める設定値のこと。値を変えると結果も変わる。","note":"媒介変数とも呼ばれる。シミュレーションでは色々な値を試す対象。","example":"パラメータを変えて、感染の広がり方の違いを比べた。"},{"term":"初期条件","reading":"しょきじょうけん","meaning":"シミュレーションを始める時点での状態や条件のこと。","note":"初期条件が少し違うだけで、結果が大きく変わる場合がある。","example":"初期条件として、最初の感染者数を10人に設定した。"},{"term":"誤差","reading":"ごさ","meaning":"モデルや計算で得た値と、実際の値とのずれのこと。","note":"モデルは現実を単純化しているため、誤差が生じるのは避けられない。","example":"予測値と実際の値の誤差を確認して、モデルを改善した。"}]},{"topic":"ネットワークとセキュリティ","cards":[{"term":"プロトコル","reading":"ぷろとこる","meaning":"コンピュータ同士が通信するときの手順や約束事のこと。互いに同じ決まりに従うことでデータをやり取りできる。","note":"ネットワークの土台となる決まりで、IPやウェブ閲覧の決まりもこの一種である。","example":"通信のプロトコルが決まっているため、異なるメーカーの機器でも通信できる。"},{"term":"IPアドレス","reading":"あいぴーあどれす","meaning":"ネットワークにつながる機器を識別するために割り当てられる番号。通信の宛先や送り元を示す住所のような役割を持つ。","note":"パケットを届ける場面で、宛先を指定するために使われる情報である。","example":"ネットワーク上の機器は、IPアドレスによって識別されている。"},{"term":"パケット","reading":"ぱけっと","meaning":"ネットワークで送るデータを小さく分割した単位のこと。宛先などの情報を付けて送られ、受け手側で元に戻される。","note":"大きなデータでも回線を効率よく使って送れるようにする仕組みの中心である。","example":"大きなデータはパケットに分割されて送られ、届いた先で組み立てられる。"},{"term":"暗号化","reading":"あんごうか","meaning":"データを決まった方法で読みにくい形に変換し、鍵を持つ人だけが元に戻せるようにすること。","note":"通信を途中で見られても内容が分からないようにする、セキュリティの基本技術である。","example":"送信前にデータを暗号化しておけば、途中で見られても内容は分からない。"},{"term":"認証","reading":"にんしょう","meaning":"利用者や機器が本当に本人・本物であるかを確かめる仕組み。パスワードや指紋などを使って行う。","note":"なりすましを防ぐ役割があり、暗号化と並ぶセキュリティの柱の一つである。","example":"パスワードによる認証で、本人であることを確認してからログインした。"},{"term":"コンピュータウイルス","reading":"こんぴゅーたういるす","meaning":"コンピュータに侵入してデータを壊したり情報を盗んだりする、不正なプログラムの総称。","note":"感染を防ぐ対策や、怪しいファイルを開かない注意と結びつけて学ぶ対象である。","example":"コンピュータウイルスに感染しないよう、出所の分からないファイルは開かない。"},{"term":"マルウェア","reading":"まるうぇあ","meaning":"コンピュータに害を与える悪意のあるソフトウェアの総称。ウイルスもその一種。","note":"ウイルスはマルウェアに含まれる関係を押さえる。","example":"マルウェアに感染すると、個人情報が盗まれる危険がある。"},{"term":"ファイアウォール","reading":"ふぁいあうぉーる","meaning":"外部からの不正な通信を遮断し、内部のネットワークを守る仕組み。","note":"防火壁の意味。許可した通信だけを通す門番と考える。","example":"ファイアウォールを設定して、不正なアクセスを防いだ。"},{"term":"サーバ","reading":"さーば","meaning":"ネットワーク上でサービスやデータを提供するコンピュータ。","note":"要求する側のクライアントと対になる言葉。","example":"Webサーバから、ブラウザにページのデータが送られる。"},{"term":"クライアント","reading":"くらいあんと","meaning":"サーバに要求を送り、サービスを受ける側のコンピュータやソフトウェア。","note":"利用者側がクライアント、提供側がサーバと覚える。","example":"クライアントであるスマホが、サーバにデータの送信を求めた。"},{"term":"ドメイン名","reading":"どめいんめい","meaning":"IPアドレスを人が読みやすい文字列で表したもの。住所に付けた名前のようなもの。","note":"DNSによってIPアドレスに変換される仕組みとセットで覚える。","example":"ドメイン名を入力すると、対応するサーバに接続される。"},{"term":"公開鍵暗号","reading":"こうかいかぎあんごう","meaning":"公開鍵で暗号化し、対になる秘密鍵で復号する方式。鍵を安全に渡せる利点がある。","note":"共通鍵暗号との違いは、暗号化と復号で異なる鍵を使う点。","example":"公開鍵暗号では、公開鍵は誰に知られてもかまわない。"}]},{"topic":"データの活用","cards":[{"term":"代表値","reading":"だいひょうち","meaning":"データ全体の傾向を一つの数で表した値。平均値や中央値、最頻値などが代表例である。","note":"散らばったデータを要約して比べるための、最初の整理の道具になる。","example":"データ全体の傾向をつかむために、代表値として中央値を求めた。"},{"term":"散布図","reading":"さんぷず","meaning":"二つの数量の関係を点の集まりで表したグラフ。各データの二つの値を縦軸と横軸に置いて打つ。","note":"相関があるかどうかを目で確かめるために使うグラフである。","example":"身長と体重の関係を散布図に表すと、点の分布から傾向が見えてきた。"},{"term":"相関関係","reading":"そうかんかんけい","meaning":"一方の値が変わると、もう一方の値も一定の傾向で変わるような、二つの事柄の結びつきのこと。","note":"原因と結果の関係とは別物であり、混同しないことがこのテーマの注意点になる。","example":"勉強時間とテストの点数の間には、相関関係が見られた。"},{"term":"ビッグデータ","reading":"びっぐでーた","meaning":"従来の方法では扱いきれないほど大量で多様なデータの集まり。集めて分析することで新たな傾向が見えることがある。","note":"データ活用の広がりを示す例で、収集と分析の両面から考える対象である。","example":"ビッグデータを分析することで、買い物の傾向を把握できるようになった。"},{"term":"データベース","reading":"でーたべーす","meaning":"データを決まった形式で整理して蓄え、必要なときに検索や取り出しができるようにした仕組み。","note":"大量のデータを効率よく活用するための土台として位置づく。","example":"顧客の情報をデータベースに整理しておくと、必要なときに素早く検索できる。"},{"term":"オープンデータ","reading":"おーぷんでーた","meaning":"国や自治体などが公開し、誰でも自由に利用や再配布ができるようにしたデータのこと。","note":"社会でデータを役立てる取り組みの例として、出典を示して使う点も含めて学ぶ。","example":"自治体が公開するオープンデータを使って、地域の人口の変化を調べた。"},{"term":"平均値","reading":"へいきんち","meaning":"データの合計をデータの個数で割った値。代表値の一つ。","note":"外れ値があると大きく影響を受ける点が注意点。","example":"5人のテストの平均値は、合計を5で割って求めた。"},{"term":"最頻値","reading":"さいひんち","meaning":"データの中で最も多く現れる値。モードとも呼ばれる。","note":"最も小さい値ではない。出現回数が一番多い値と覚える。","example":"靴のサイズの最頻値は、在庫を決める目安になる。"},{"term":"相関係数","reading":"そうかんけいすう","meaning":"2つのデータの相関の強さを-1から1の数値で表したもの。1に近いほど強い正の相関。","note":"0に近いと相関は弱い。符号で正・負の相関を区別する。","example":"相関係数が0.9なら、2つのデータには強い正の相関があるといえる。"},{"term":"因果関係","reading":"いんがかんけい","meaning":"一方の事柄が原因となり、もう一方がその結果として起こる関係。","note":"相関関係があっても因果関係があるとは限らない点が最重要。","example":"気温の上昇が原因でアイスの売り上げが増えたなら、因果関係があるといえる。"},{"term":"外れ値","reading":"はずれち","meaning":"他のデータから大きく離れた値。入力ミスなどが原因の場合もある。","note":"平均値を大きくずらすことがあるため、中央値と合わせて確認する。","example":"1つだけ極端に大きい外れ値があり、平均値が実態より高くなった。"},{"term":"質的データ","reading":"しつてきでーた","meaning":"性別や血液型のように、数値ではなく分類で表されるデータ。","note":"量を表す量的データと対比される。平均は計算できない。","example":"血液型は質的データなので、平均値を求めることはできない。"}]}]},{"subject":"体育","topics":[{"topic":"安全の確保","cards":[{"term":"危険の予測と回避","reading":"きけんのよそくと かいひ","meaning":"運動やスポーツの場面で起こりうる事故やけがをあらかじめ考え、危ない状況を避ける行動を取ること。","note":"安全の確保の出発点であり、用具や天候、体調の確認と結びつく考え方である。","example":""},{"term":"熱中症","reading":"ねっちゅうしょう","meaning":"暑さで体の水分や塩分のバランスが崩れ、体温調節がうまくいかなくなった状態。重くなると命に関わる。","note":"水分補給や休憩、気温への注意など、予防の具体策とセットで学ぶ。","example":""},{"term":"RICE処置","reading":"らいすしょち","meaning":"打撲や捻挫などの急性のけがへの応急処置で、安静・冷却・圧迫・挙上の頭文字を取ったもの。","note":"けがをした直後の対応として、安全の確保の実践的な内容に位置づく。","example":""},{"term":"ウォーミングアップ","reading":"うぉーみんぐあっぷ","meaning":"運動の前に体を徐々に動かして体温や心拍を上げ、筋肉や関節を運動に備えさせる準備運動。","note":"けがの予防と運動の効果を高める両面から、運動前の基本として扱う。","example":""},{"term":"落雷への対応","reading":"らくらいへのたいおう","meaning":"雷が近づいたときに屋外の活動を中断し、安全な建物などに避難するなどの行動のこと。","note":"天候の急変に備える危険回避の具体例として取り上げる。","example":""},{"term":"AED","reading":"えーいーでぃー","meaning":"心臓が正常に動かなくなった人に電気ショックを与え、正常な動きに戻すことを助ける医療機器。自動体外式除細動器の略。","note":"緊急時の救命処置の流れの中で、心肺蘇生とあわせて場所や使い方を知っておく機器である。","example":""}]},{"topic":"スポーツ外傷・障害","cards":[{"term":"スポーツ外傷","reading":"すぽーつがいしょう","meaning":"一度の大きな力で急に起こるけがのこと。転倒や衝突による骨折、捻挫、打撲などが当てはまる。","note":"スポーツ障害と区別する基本用語で、発生のしかたが急である点が特徴である。","example":""},{"term":"スポーツ障害","reading":"すぽーつしょうがい","meaning":"同じ動作の繰り返しなどで小さな負担が積み重なり、徐々に生じる痛みや故障のこと。","note":"スポーツ外傷と対になる用語で、使いすぎが主な原因として位置づく。","example":""},{"term":"オーバーユース","reading":"おーばーゆーす","meaning":"筋肉や関節などを休ませずに使いすぎること。スポーツ障害の代表的な原因とされる。","note":"練習量の調整や休息の大切さを考える手がかりになる言葉である。","example":""},{"term":"疲労骨折","reading":"ひろうこっせつ","meaning":"同じ部位に小さな力が繰り返し加わり、骨にひびが入るように折れる状態。スポーツ障害の一つである。","note":"一度の衝撃で折れる通常の骨折と違い、負担の積み重ねで起こる例として学ぶ。","example":""},{"term":"シンスプリント","reading":"しんすぷりんと","meaning":"走る動作の繰り返しなどで、すねの内側に痛みが出るスポーツ障害。初心者や練習量が急に増えた人に起こりやすい。","note":"オーバーユースによる障害の具体例として取り上げる。","example":""},{"term":"障害の予防","reading":"しょうがいのよぼう","meaning":"練習量の調整や正しいフォーム、筋力づくり、休息などで、スポーツ障害を未然に防ぐ取り組み。","note":"外傷・障害の知識を自分の運動生活に生かす、まとめの視点になる。","example":""}]},{"topic":"健康づくりのための運動","cards":[{"term":"有酸素運動","reading":"ゆうさんそうんどう","meaning":"酸素を取り込みながら長時間続けられる、比較的軽めの運動。ウォーキングやジョギングなどが当てはまる。","note":"健康づくりの中心的な運動として、強さや時間の目安とあわせて学ぶ。","example":""},{"term":"身体活動基準","reading":"しんたいかつどうきじゅん","meaning":"健康を保つために望ましい運動や生活活動の量を示した、国の目安のこと。年齢層ごとに示される。","note":"自分に必要な運動量を考えるときの物差しとして位置づく。","example":""},{"term":"メッツ","reading":"めっつ","meaning":"運動の強さを表す単位。安静にしているときを1として、その何倍のエネルギーを消費するかで示す。","note":"種類の違う運動の強さを同じ物差しで比べるために使う。","example":""},{"term":"ロコモティブシンドローム","reading":"ろこもてぃぶしんどろーむ","meaning":"骨や関節、筋肉などの運動器の衰えにより、立つ・歩くといった移動機能が低下した状態。略してロコモともいう。","note":"将来の要介護を防ぐために、若いうちからの運動習慣と結びつけて学ぶ。","example":""},{"term":"サルコペニア","reading":"さるこぺにあ","meaning":"加齢などによって筋肉の量が減り、筋力や身体機能が低下した状態のこと。","note":"ロコモの要因の一つでもあり、筋肉を保つ運動の大切さを示す言葉である。","example":""},{"term":"メタボリックシンドローム","reading":"めたぼりっくしんどろーむ","meaning":"内臓脂肪がたまった状態に加え、高血圧や高血糖などが重なり、生活習慣病の危険が高まった状態。","note":"有酸素運動や生活習慣の見直しで改善を目指す対象として取り上げる。","example":""}]},{"topic":"生涯スポーツ","cards":[{"term":"生涯スポーツ","reading":"しょうがいすぽーつ","meaning":"年齢や体力に応じて、生涯を通じて楽しみながら続けるスポーツのあり方や、その活動自体のこと。","note":"このテーマ全体の中心概念で、競技としてだけでなく楽しむ視点が大切にされる。","example":""},{"term":"する・みる・ささえる","reading":"する・みる・ささえる","meaning":"スポーツへの関わり方を表す三つの言葉。自ら行う、観戦する、運営や指導などで支える関わり方を指す。","note":"生涯スポーツでは、競技者以外にも多様な関わり方が認められることを示す。","example":""},{"term":"総合型地域スポーツクラブ","reading":"そうごうがたちいきすぽーつくらぶ","meaning":"地域の人々が主体となり、複数の種目を、子どもから高齢者までがそれぞれのレベルで楽しめる地域のスポーツクラブ。","note":"身近な地域で生涯スポーツを支える仕組みの代表例として位置づく。","example":""},{"term":"ライフステージ","reading":"らいふすてーじ","meaning":"子どもの頃、青年期、壮年期、高齢期など、人生の段階のこと。各段階で体力や生活が異なる。","note":"各段階に合ったスポーツの選び方を考えるための枠組みになる。","example":""},{"term":"スポーツ基本法","reading":"すぽーつきほんほう","meaning":"スポーツに関する基本的な理念や、国や自治体の役割などを定めた法律。2011年に制定された。","note":"生涯スポーツを社会として推進する法的な土台として扱う。","example":""},{"term":"スポーツ庁","reading":"すぽーつちょう","meaning":"スポーツの振興に関する国の政策を担う行政機関。文部科学省の外局として設置されている。","note":"国の立場からスポーツ推進を進める中心機関として位置づく。","example":""}]},{"topic":"ライフスタイルに応じたスポーツ","cards":[{"term":"ライフスタイル","reading":"らいふすたいる","meaning":"仕事や学校、家庭などを含む、その人の生活の送り方や習慣全体のこと。","note":"スポーツを生活に取り入れるとき、前提として見つめる自分の生活そのものを指す。","example":""},{"term":"スポーツライフの設計","reading":"すぽーつらいふのせっけい","meaning":"自分の生活や体力、目的に合わせて、いつ・何を・どのくらい行うかという運動の計画を立てること。","note":"このテーマの中心的な活動で、現状の把握と目標設定を経て行う。","example":""},{"term":"現状の把握","reading":"げんじょうのはあく","meaning":"今の体力や運動習慣、生活時間などを確かめ、自分の現在の状態を知ること。","note":"設計の最初の手順であり、無理のない目標を立てる土台になる。","example":""},{"term":"目標設定","reading":"もくひょうせってい","meaning":"運動で何を目指すかを具体的で達成可能な形で決めること。期間や数値を入れると進み具合が分かりやすい。","note":"現状の把握の次に行う手順で、続ける意欲を保つ役割も持つ。","example":""},{"term":"すきま時間の活用","reading":"すきまじかんのかつよう","meaning":"通学や休憩などの短い空き時間を使って、軽い運動やストレッチを取り入れる工夫のこと。","note":"忙しい生活でも運動を続けるための、具体的な工夫の一つである。","example":""},{"term":"PDCAサイクル","reading":"ぴーでぃーしーえーさいくる","meaning":"計画、実行、評価、改善の四つを繰り返して物事をよくしていく進め方のこと。","note":"立てたスポーツライフの計画を見直し、続けやすく改善していく方法として使う。","example":""}]},{"topic":"スポーツ推進の取り組み","cards":[{"term":"スポーツ庁","reading":"すぽーつちょう","meaning":"国のスポーツ政策を担当する行政機関で、競技力の向上から地域のスポーツ振興まで幅広く担う。","note":"推進の取り組みでは、国レベルの施策の中心として位置づく。","example":""},{"term":"総合型地域スポーツクラブ","reading":"そうごうがたちいきすぽーつくらぶ","meaning":"地域住民が運営の中心となり、多種目・多世代・多志向を特徴とする地域のスポーツクラブ。","note":"地域レベルで推進を支える具体的な仕組みとして取り上げる。","example":""},{"term":"スポーツボランティア","reading":"すぽーつぼらんてぃあ","meaning":"大会の運営補助や地域の活動支援など、報酬を目的とせずスポーツを支える活動や、その参加者のこと。","note":"ささえる関わり方の代表例で、大会や地域行事を成り立たせる存在である。","example":""},{"term":"障がい者スポーツ","reading":"しょうがいしゃすぽーつ","meaning":"障がいのある人が参加するスポーツや、障がいに合わせて用具やルールを工夫したスポーツのこと。","note":"誰もがスポーツに関われる社会を目指す推進の柱の一つとして扱う。","example":""},{"term":"スポーツツーリズム","reading":"すぽーつつーりずむ","meaning":"スポーツの観戦や参加を目的とした旅行や、それによる地域への人の流れのこと。","note":"スポーツが地域の活性化につながる側面を示す取り組みである。","example":""},{"term":"レガシー","reading":"れがしー","meaning":"大きな大会などの開催をきっかけに、施設や文化、人材などの良い影響が開催後に社会に残るもののこと。遺産とも訳される。","note":"大会を一過性で終わらせず、推進の成果として残す視点を表す言葉である。","example":""}]},{"topic":"豊かなスポーツライフの創造","cards":[{"term":"スポーツの多様な価値","reading":"すぽーつのたようなかち","meaning":"健康や体力だけでなく、楽しさや交流、感動、地域のつながりなど、スポーツが持つさまざまな良さのこと。","note":"このテーマ全体を貫く考え方で、勝敗以外の価値に目を向ける出発点になる。","example":""},{"term":"フェアプレイ","reading":"ふぇあぷれい","meaning":"ルールを守り、相手や審判を尊重して正々堂々と競う姿勢のこと。","note":"スポーツの価値を守る基本的な心構えとして、ドーピングの対極にも置かれる。","example":""},{"term":"ドーピング","reading":"どーぴんぐ","meaning":"競技で不正に力を高めるために、禁止された薬物や方法を使うこと。健康を害し、公平さも損なう。","note":"フェアプレイに反する行為として、なぜ許されないかを考える対象になる。","example":""},{"term":"スポーツと交流","reading":"すぽーつとこうりゅう","meaning":"スポーツを通して世代や地域、国境を越えて人々が出会い、理解し合うつながりのこと。","note":"多様な価値の一つであり、豊かなスポーツライフを広げる側面として扱う。","example":""},{"term":"スポーツと環境","reading":"すぽーつとかんきょう","meaning":"自然の中で行うスポーツや大会運営が環境に与える影響と、環境を守りながら楽しむ工夫のこと。","note":"スポーツを持続可能な形で続けるための視点として位置づく。","example":""},{"term":"関わり方の変化","reading":"かかわりかたのへんか","meaning":"年齢や生活の変化に合わせて、する側からみる側、ささえる側へとスポーツとの関わり方が変わっていくこと。","note":"生涯にわたってスポーツと付き合う姿として、このテーマのまとめにあたる考え方である。","example":""}]}]}];
